window.__D("text/torat-shmuel/c036",{"p":[[2002180159,"אלפים משל שהם ג' אלפים מדריגות שעד בחי' חכמה תתאה דמל' דאצי', ועד\"מ חשן ואפוד שלמטה שנתלבש בגשמיות החשן והאפוד שעשו לאהרן כה\"ג, הנה הוא רק בחי' משל לבד לבחי' החשן ואפוד שיש למעלה<sup data-n=\"345\">14</sup> ברוחניות העשייה, וכן חשן ואפוד שברוחניות העשייה ה\"ה משל לבחי' חשן ואפוד שלמעלה הימנו כו', ועד\"ז השיג שלמה שלשת אלפים מדריגות שכ\"א ה\"ה רק משל לגבי שלמעלה הימנו. וכל שלשת אלפים משלים אלו זהו רק לגבי ג' עולמות בי\"ע כנ\"ל. ובאמת יש עוד מדריגות הרבה יותר, רק ששלמה לא השיג יותר מן בחי' ח\"ת המהוה בי\"ע כנ\"ל, וזהו שדרשו רז\"ל א\"ת הליכות אלא הלכות שע\"י בחי' התורה נמשך ההילוך מלמעלמ\"ט, וכמו המהלך שיכול לילך למרחוק מאד, כך ע\"י התורה נמשך בחי' ההארת פנים עד למטה, והיינו שמבחי' חכמת אדם שהיא חכמת התורה המאירה את פני בחי' כמראה [אדם] יומשך גם באדם שלמטה שלומד תורה שיאירו פניו כו'.\n<b>וזהו</b> מה שנמשל התורה לשלג כמ\"ש לבושי' כתלג חיור שקאי על התורה, דהיינו כמו השלג עיקר מהותו הוא מים אלא שנקרש<sup data-n=\"346\">15</sup> ונגלד, וכשמתפשר נעשה עוה\"פ מים, רק באמצעיתו כשנקרש ונגלד נראה מהותו לשלג, וכך התורה היא חכ' בראש וחכ' בסוף, שבתחילה היא בחי' מים המצמיחים כל מיני תענוג היינו בחי' תענוג רוחני אשר עי\"ז תאיר פניו של בחי' כמראה אדם שלמעלה כנ\"ל, ובסוף ה\"ה ג\"כ בחי' מים להצמיח התענוג באדם שלמטה הלומד תורה עד שיצהבו פניו שלמטה מבחי' התענוג כנ\"ל.\n<b>וכמו</b> שע\"י התורה נמשך בחי' ההארת פנים כן ע\"י בחי' ההתבוננות באלקות איך שהוא ית' ממכ\"ע וסוכ\"ע, וכולא קמי' כלא ממש חשיב עי\"ז נמשך בחי' הארת פנים. וזהו יאר זהו מאור תורה אשר יאר ה' פניו אליך, והיינו כמו שלמעלה בחי' חכמת אדם דתורה תאיר בחי' פני כמראה אדם אשר היא מראה דמות כבוד הוי' כו', כן יאר ה' פניו הנ\"ל אשר מאיר מאור תורה גם אליך למטה בגשמיות, שע\"י לימוד התורה הרי ע\"י התורה נעשה בחי' הילוך והמשכה למטה שגם פני הלומד תורה יצהיבו מבחי' הענג העליון אשר תאיר פני בחי' כמראה אדם כו'. וזהו שאה\"כ בית יעקב לכו ונלכה באור הוי', פי' באור הוי' היינו באור שמאיר בשם הוי'<sup data-n=\"347\">16</sup> היינו בחי' חכמת אדם פנימי אשר תאיר פני בחי' כמראה אדם שהוא מראה דמות כבוד הוי', ופי' בית יעקב היינו נש\"י שלמטה<sup data-n=\"348\">17</sup> שע\"י לימוד התורה לכו ונלכה באור שבשם הוי' היינו בחי' ההארת פנים שלמטה* שמתארך ונמשך גם למטה כו'.",[["345","14","<b>חשן ואפוד שלמטה . . רק בחי' משל . . החשן ואפוד שיש למעלה</b>: ראה בארוכה אוה\"ת תצוה ע' א'תרמה-ו. א'תרסה ואילך. א'תרעט. סה\"מ תרל\"ג ח\"א ע' קסה-ו. [ובהנסמן שם בתחילת המאמר]."],["346","15","<b>השלג עיקר מהותו הוא מים אלא שנקרש</b>: ראה בהנסמן ע\"ז בסה\"מ תרכ\"ז ע' תכז."],["347","16","<b>בית יעקב לכו ונלכה באור הוי' . . באור שמאיר בשם הוי'</b>: ראה תו\"א שמות נ, רע\"ג (ע\"פ זח\"ג קל, א). סה\"מ תרל\"ג ח\"ב ע' שסד. שסח. ועוד."],["348","17","<b>שלמטה</b>: אוצ\"ל: שלמעלה."]]],[2002180160,"<span data-k=\"ks\"><b>קיצור.</b> מה שנש\"י עלו במח' זהו בחי' כמראה אדם למעלה ועל בחי' אדם זה נא' חכ' אדם שהיא חכ' התורה תאיר פניו, ע\"ד צהבו פניו דר\"א, ובמד\"ר יאר מאור תורה, כי הליכות עולם שנמשך ההילוך למרחוק עד למטה באדם הלומד, ולכן נמשלה לשלג שתחילתו וסופו מים המגדלים תענוג בבחי' כמראה אדם, ובאדם שלמטה, ולכן לכו ונלכה באור שמלובש בש' הוי' כו'.</span>\nג) <b>וזהו</b> דכתיב כמים הפנים<sup data-n=\"349\">18</sup> לפנים כן לב האדם אל האדם פי' כמים הפנים קאי על התורה שנק' בשם מים כמ\"ש הוי כל צמא לכו למים, והיינו כמו שהמים מטהרים את האדם, כך התורה היא מטהר ומזכך את האדם, וכמו שהמים יורדים מגבוה לנמוך, כמ\"כ התורה נמשכה מלמעלמ\"ט וממשכת בחי' הארת פנים העליון עד למטה כו', וזהו פי' כמים הפנים לפנים שבחי' מי התורה ממשיכים בחי' הארת פנים לבחי' הפנים העליון דבחי' כמראה אדם הנ\"ל כן לב האדם העליון דבחי' כמראה אדם לאדם היינו בחי' אדם התחתון, והיינו שע\"י התורה נמשך בחי' ההארת פנים גם למטה באדם שלמטה כו'. ובזה יובן ג\"כ מה ששבת נק' פנים חדשות שזהו מפני שבשבת מאיר מוחין חדשים, דהנה שבת לאו זמן תפילין הוא<sup data-n=\"350\">19</sup>, כי ענין התפילין הוא שבהם וע\"י נמשכים בחי' ד' מוחין כנודע, אמנם מצות תפילין הוא לשאת אותם ע\"ג הראש שרומז שאם היות שממשיכים ע\"י בחי' המוחין אמנם זהו ע\"ג הראש בבחי' מקיף לבד ולא בבחי' פנימיות, אך הנה בשבת נמשכים המקיפים להיות בחי' פנימים, ולכן שבת לאו זמן תפילין הוא להיות כי ע\"י התפילין נמשך בחי' המוחין רק בבחי' מקיף לבד אבל בשבת מאיר בחי' מקיף זה דפנימיות כו', ולכן נק' בשם פנים חדשות. ולכן ארז\"ל אינו דומה מאור פניו של אדם בשבת למאור פניו בחול, להיות כי בשבת מאיר בחי' הארת פנים מבחי' המוחין שנמשכים בפנימיות להאיר פניו כו'. וזהו שנק' התורה בשם מגילה כתובה פנים, כי ע\"י התורה נמשך בחי' הארת פנים כו'.\n<b>והנה</b> כמו שע\"י התורה נמשך בחי' הארת פנים<sup data-n=\"351\">20</sup>, כמ\"כ ע\"י המצות נמשך ג\"כ בחי' הארת פנים, כמ\"ש עטרת תפארת שיבה בדרך צדקה תמצא, פי' שיבה הוא בחי' י\"ג ת\"ד שהם בחי' יגמה\"ר, וזהו שיגמ\"ד שהתורה נדרשת בהם הם כנגד יגמה\"ר<sup data-n=\"352\">21</sup>, ופי' תפארת שיבה הוא בחי' הדרת פנים, ועיקר הדרת פנים תלוי בזקן וכמארז\"ל על ר' יוחנן שלא הי' לו הדרת פנים מפני שלא הי' לו זקן, ובחי' תפארת שיבה זו שהם יגת\"ד יגמה\"ר בחי' הדרת פנים שזהו כענין הארת פנים שע\"י חכמת",[["349","18","<b>וזהו דכתיב כמים הפנים . . קאי על התורה</b>: ראה גם לעיל ח\"א ד\"ה כמים הפנים. — בהבא לקמן בפיסקא זו ראה המשך תרס\"ו שם ע' רלח."],["350","19","<b>דהנה שבת לאו זמן תפילין הוא</b>: ראה בהנסמן באוה\"ת דברים (כרך ו) ע' ב'תתפט."],["351","20","<b>והנה כמו שע\"י התורה נמשך בחי' הארת פנים</b>: בהבא לקמן ראה המשך תרס\"ו שם ע' רלט ואילך."],["352","21","<b>וזהו שיגמ\"ד שהתורה נדרשת בהם הם כנגד יגמה\"ר</b>: ראה גם לקו\"ת בהעלותך ל, ב ואילך. עקב טז, ב ואילך. ראה לג, ד. וראה או\"ת להה\"מ ס\"פ בהעלותך (מו, ב). סה\"מ תרכ\"ט ע' רל. וש\"נ."]]],[2002180161,"אדם הנ\"ל, ה\"ז בדרך צדקה תמצא, שע\"י הצדקה נמשך בחי' הדרת פנים שז\"ע הארת פנים כו', והיינו שע\"י שנותן צדקה לעני ומחי' אותו, עי\"ז נמשך מלמעלה ג\"כ בחי' באור פני מלך חיים, וכן ע\"י כל המצות ממשיכים ג\"כ בחי' הארת פנים שהרי כל המצות נק' בשם צדקה כמ\"ש וצדקה תהי' לנו כי נשמור לעשות את כל המצוה. וזהו דכתיב תחת אשר לא עבדת כו' מרוב כל, כל הוא בחי' העמוד המחבר ג\"ע<sup data-n=\"353\">22</sup> התחתון עם בחי' ג\"ע העליון, ופי' מרוב כל שיש ריבוי בחי' כל, שהגם שלא נז' בספרים כ\"א ב' בחי' ג\"ע, התחתון והעליון, אמנם באמת יש ריבוי מדריגות בג\"ע שהרי ארז\"ל ע\"פ ילכו מחיל אל חיל שת\"ח אין להם מנוחה כו' ולא בעוה\"ב שתמיד עולים ממדריגה למדריגה, אלא שבד\"כ נחלקים לב' בחי' געה\"ת וגעה\"ע, אמנם בפרטית יש ריבוי בחי' ג\"ע, וא\"כ יש ריבוי בחי' כל המחברים התחתון עם הגבוה הימנו כו', ועבודה בשמחה היא יותר טוב מכל הבחי' כל. והיינו כמארז\"ל יפה שעה א' בתשובה ובמעש\"ט [בעוה\"ז] מכל חיי העוה\"ב, והוא מפני כי כל חיי העוה\"ב ה\"ה רק בחי' הארה בעלמא מבחי' עדן, וכמ\"ש ונהר יוצא מבחי' עדן להשקות את הגן שע\"י הנהר נמשך הארה מבחי' עדן בבחי' גן ושע\"ש המשכה זו נק' הגן בשם גן עדן, והיינו שהוא גן שנמשך בו הארה מבחי' עדן ע\"י הנהר, אמנם ע\"י עשיית המצות נמשך בחי' הארת פנים להיות בחי' תפארת שיבה הדרת פנים, שזהו המשכה מבחי' עדן עצמו אשר עדן עין לא ראתה כו', ולכן העבודה בשמחה היא טוב יותר מרב כל כו'.\n<span data-k=\"ks\"><b>קיצור.</b> כמים הפנים לבחי' פנים העליון כן לב האדם עליון אל אדם התחתון, ושבת הוא פנים חדשות לפי שמאיר המקיף בפנימי, וכמו שע\"י התורה נמשך הארת פנים כן ע\"י המצות נמשך ג\"כ בחי' הארת פנים, ולכן יפה שע\"א כו' מכל חיי העוה\"ב כו'.</span>",[["353","22","<b>וזהו דכתיב תחת אשר לא עבדת . . כל הוא בחי' העמוד המחבר ג\"ע</b>: ראה בכ\"ז לעיל ח\"א ד\"ה החודש הזה לכם. וש\"נ."]]],[2002180162,"<h3>[כי יש אדם שעמלו בחכ'] (ב) ואחור</h3>\n<b></b><b>בס\"ד. (ש\"פ פנחס, ט\"ל).</b>\n<b></b>אחרי ה\"א תלכו כו' תפלה ותורה אחור ופנים, יעקב ישראל (ד-וא\"ו)\n[פנחס]\nד) <b>ואחור</b> הוא בחי' תפילה שנק' אחור<sup data-n=\"354\">1</sup><sup data-n=\"355\">2</sup>, והענין הוא דכתיב אחרי ה' אלקיכם תלכו, שענין מעלת ההילוך אחרי ז\"ע היותינו בבחי' הביטול לילך אחרי ה' אלקינו, וכענין דכתיב זכרתי לך חסד נעורייך לכתך אחרי במדבר, שהיו בבחי' הביטול שהלכו במדבר אשר הוא לא מקום זרע, ובלי הכנת מזון כ\"א שבטחו בה' והלכו אחריו בבחי' הביטול, ועד\"ז הוא מ\"ש אחרי ה' אלקיכם תלכו בבחי' הביטול לאלקות, שז\"ע התפילה שעיקר התפילה היא בחי' שפיכות הנפש בבחי' הביטול לאלקות כמ\"ש ואהבת את ה' אלקיך בכל לבבך בשני יצריך, ע\"י ההתבוננות באחד הוא בחי' יחו\"ע ובשכמל\"ו הוא בחי' יחו\"ת, אשר ע\"י העמקת הדעת בההתבוננות יבא לבחי' התשוקה לאלקות כי מי לי בשמים ועמך לא חפצתי בארץ, שמים וארץ הם בחי' תענוגים רוחני' וגשמיים<sup data-n=\"356\">3</sup> ולהיותם רק עמך בטל וטפל לך לכן לא חפצתי בהם, כ\"א להיכלל ולבטל באוא\"ס ב\"ה, וע\"ש זה נק' התפילה בשם אחור, להיות כי מדריגתה היא להיות בבחי' ההילוך אחרי ה' כו'.\n<b>ועוי\"ל</b> שמלבד שההילוך דתפילה<sup data-n=\"357\">4</sup> היא מלמטלמ\"ע בבחי' אחרי הוי', הנה גם בחי' ההתבוננות אשר ממנה בא בחי' ההילוך הוא ג\"כ בחי' אחרי הוי'. דהנה כל ענין בחי' ההתבוננות הוא רק בבחי' זיו והארה לבד שהוא בחי' מלכותך מלכות כל עולמים, שכל בחי' וענין בחי' מלכותך נק' בשם אחרי הוי'. דהנה כתיב מושיב מלכים לכסא, וכתיב וישב ה' מלך לעולם, והנה בחי' הישיבה היא בבחי' אחוריים לבד, וכך מ\"ש מלכותך מלכות כל עולמים זהו רק בחי' אחוריים וחיצוני' לבד, שהוא רק בחי' זיו והארה בעלמא שאינו נוגע לעצמיותו.\n<b>וזהו</b> מלכותך מל' כל עולמים<sup data-n=\"358\">5</sup>, פי' כל עולה מספרו חמשים, והיינו שכל האריכות דנו\"ן אלפים יובלות הם הכל מבחי' מלכותך לבד, וכדי שיהי' בחי' מלוכה זו כתי' כבוד מלכותך יאמרו וגבורתך ידברו שזהו ע\"י בחי' גבורות וצמצומים. וזהו ג\"כ שא' אתה גיבור לעולם אד', שכדי שיהי' בחי' שם אד' שמורה איך שאנת אשתמודע אדון על כולא, זהו ע\"י שאתה גבור שע\"י בחי' הגבורות וצמצומים עי\"ז נמשך שיהי' בחי' אדון לעולם כו'. וזהו שאומרים בנוסח התפילה פסוקים המורים",[["354","1","<b>ד) ואחור הוא בחי' תפילה שנק' אחור</b>: מאמר זה הוא המשך להמאמר שלפנ\"ז ד\"ה לא הביט און. לכללות המאמר ראה בהנסמן שם בתחילת המאמר.\nהנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר זה נדפסה לקמן בהוספות ושם מתחיל: ”כי יש אדם שעמלו בחכ'\"."],["355","2","<b>ואחור הוא בחי' תפילה</b>: בהבא לקמן עד סוף הפיסקא ראה המשך תרס\"ו שם ס\"ע רמא-ב."],["356","3","<b>שמים וארץ . . תענוגים רוחני' וגשמיים</b>: ראה לקמן ד\"ה בהעלותך הנחת כ\"ק אדמו\"ר מהורש\"ב. וש\"נ."],["357","4","<b>ועוי\"ל שמלבד ההילוך דתפילה</b>: בהבא לקמן בפיסקא זו ראה ד\"ה כי מראש צורים בהמשך תרס\"ו שם ע' רצז."],["358","5","<b>וזהו מלכותך מל' כל עולמים</b>: בהבא לקמן ראה ד\"ה תתן אמת ליעקב בהמשך תרס\"ו שם ע' שב-ג."]]],[2002180163,"שההתבוננות היא בבחי' מל' שנק' אחרי הוי' כמו יהללו את שם הוי' היינו בחי' שם והארה מבחי' שם הוי', וכן ישתבח שמך לעד, וכולם מקדישים ומעריצים וממליכים את שם, שהוא בחי' אריכות ההתבוננות איך ששרש התהוות כל העולמות עליונים ותחתונים הוא רק מבחי' זיו והארה בעלמא שאינו נוגע כלל לבחי' עצמותו ית', ועי\"ז נעשה להיות ואהבת את הוי' אלקיך כו' דהיינו להיות בבחי' אהבה ותשוקה לעצמותו ית', כמ\"ש מי לי בשמים ועמך לא חפצתי בארץ כנ\"ל, כ\"א כלה שארי ולבבי, בבחי' צמאון כמ\"ש צמאה לך נפשי, שענין הצמאון הוא תשוקה נפלאה מאד, שלכן נאמר לשון צמאון, ולא אמר לשון רעב, לפי שענין בחי' הצמאון היא תשוקה יותר נפלאה, כמו מי שהוא צמא למים הוא תשוקה היותר גדולה מכמו הרעב ללחם, ולכן אמר צמאה לך נפשי שע\"י ההתבוננות בתפילה בבחי' אני ה' לא שניתי, ולכן מי לי בשמים כו' עי\"ז בא להיות בבחי' צמאון ותשוקה לאור א\"ס עצמו\"ה שלא יהי' לו שום רצון אחר כלל, כמו הצמא למים שמפני שהתשוקה למים היא גדולה אצלו כ\"כ עד שכל רצונותיו בטלים לגבי צמאונו למים כו'. וכל זה הוא ע\"י ההתבוננות בבחי' אחרי הוי', היינו שכל השתלשלות העולמות הוא מבחי' אחורים וחיצוני' שהוא הארה בעלמא לבד בחי' מלכותך מלכות כל עולמים, ולכן נק' התפילה בשם אחור כו'.\n<b>אך</b> הנה א\"א להגיע לבחי' פנים שהוא בחי' תורה, כ\"א ע\"י בחי' אחור שהוא בחי' תפלה, וז\"ע שאמר בהמגילה שהיא כתובה פנים ואחור שכולא חד, להיות כי א\"א לבוא לבחי' פנים כ\"א ע\"י בחי' אחור. והענין הוא דבסש\"ב מפרש פסוק כמים הפנים לפנים<sup data-n=\"359\">6</sup> מלמעלמ\"ט, והיינו שהתורה נק' מים, והנה נודע שפעולת המים לרוות הצמאון, אמנם כ\"ז הוא כשהוא צמא למים אז המים ערבים עליו, משא\"כ כשאינו צמא למים אינם מרוים אותו כלל, ולכן השותה מים לצמאו מברך שהכל נהי' בדברו משא\"כ לאנסו כו', וזהו שאה\"כ כמים קרים על נפש עיפה, שלנפש עיפה שהוא צמא למים מאד אז המים קרים מרוים צמאונו כו'. ועד\"ז יובן בנמשל דהנה נת' לעיל שע\"י התורה נמשך הארת פנים בבחי' כמראה אדם שלמעלה שז\"ע חכ' אדם תאיר פניו, וגם נק' הליכות עולם שיורד ונמשך בחי' ההארת פנים גם למטה באדם הלומד עד שיצהבו פני הלומד ועוסק בתורה כו', אמנם כ\"ז הוא כשיש לו תשוקה וצמאון, והיינו כשהוא בבחי' צמאון לאלקות אז מי התורה מרווין צמאונו כמ\"ש הוי כל צמא לכו למים, אבל כשאין אצלו בחי' הצמאון כלל אז אין המים דמי התורה מרווים אותו כלל, והצמאון הלזה ז\"ע התפילה דוקא שע\"י ההתבוננות בתפילה בבחי' אחרי הוי' עי\"ז בא בבחי' התשוקה וצמאון עד שעמך לא חפצתי כ\"א כלה שארי ולבבי באוא\"ס עצמו\"ה, ואז מי התורה מרווים צמאונו. וזהו שנאמר בפ' ראשונה דק\"ש והיו הדברים האלה וארז\"ל בד\"ת הכתוב מדבר, והיינו לאחר ההתבוננות בפסוק ראשון דק\"ש עד שבא לואהבת בכל לבבך כו' מאדך, והאיך היא הדרך לדבקה בו באוא\"ס",[["359","6","<b>דבסש\"ב מפרש פסוק כמים הפנים לפנים</b>: תניא פמ\"ו. וראה גם סה\"מ תקס\"ד ע' צד ואילך. אוה\"ת בשלח ע' תעז ואילך. ובכ\"מ."]]],[2002180164,"ע\"ז אומר והיו הדברים האלה שבד\"ת הכתוב מדבר שאורייתא וקוב\"ה כולא חד. וא\"כ מובן שבכדי שיהי' בחי' כמים הפנים לפנים שז\"ע הארת פנים מאדם פנימי דחכמה בבחי' כמראה אדם שרש נש\"י למעלה כנ\"ל, ושעי\"ז יהי' לב האדם העליון דבחי' כמראה אדם לאדם שלמטה הלומד תורה שיתארך בחי' ההארת פנים עד למטה באדם הגשמי, זהו הכל תלוי בבחי' התשוקה והצמאון שצריך להיות תחילה, שבלא תשוקה לאלקות אין המים דתורה מרוה כלל כו'.\n<span data-k=\"ks\"><b>קיצור.</b> שהתפילה נק' אחור שע\"י התפילה נמשך אחרי הוי' כו', הב' שגם ההתבוננות הוא בבחי' אחורים וחיצוני' היינו מה שהוא רק זיו והארה לבד, אך לבוא לבחי' פנים א\"א כ\"א ע\"י שיהי' תחילה בחי' אחור היינו בחי' התפילה שע\"י התפילה בא לבחי' צמאון ואז מים דתורה מרווים צמאונו כו'.</span>\nה) <b>ועוי\"ל</b> הטעם שנק' התפילה בשם אחור, דהנה ארז\"ל הני ח\"י ברכות כנגד מי, כנגד ח\"י אזכרות שבק\"ש, וכנגד ח\"י חוליות שבשדרה<sup data-n=\"360\">7</sup>. והנה החוט שבתוך הח\"י חוליות שבשדרה נמשך מבחי' מוח הדעת שהוא ממול ערפו כנגד בחי' האחורים, כי תלת מוחין שבגולגלתא הנה מוח החכמה ומוח הבינה הם כנגד הפנים, ומוח הדעת הוא כנגד האחוריים, והחוט נמשך ממוח הדעת כנ\"ל. והענין הוא דהנה חכמה היא בחי' התורה כנ\"ל בענין חכמת אדם, ומדריגתה הוא בחי' ראי', וכענין דכתיב במשה וירא ראשית לו, והחכמים נק' עיני העדה, וגם ארז\"ל איזהו חכם הרואה, וזהו שרצה משה לכנוס לארץ, שביקש אעברה נא ואראה את הארץ, והיינו כי רצה להמשיך בחי' ראי'<sup data-n=\"361\">8</sup> בארץ, פי' ארץ הם נש\"י כמ\"ש כי תהיו אתם ארץ חפץ, ורצה לפעול בנש\"י שכל ישראל יבואו לבחי' ראי' באלקות כו', ולא פעל זה, כי לא כל הרוצה ליטול את השם יטול, שלא הכל יכולים לבוא לבחי' גבוה כזו להיות להם בחי' ראי' ממש באלקות, כ\"א ע\"י שראה מרחוק את הארץ פעל בנש\"י שנק' ארץ שיחידי סגולה יהי' יכולים לבוא לבחי' ומדריגת הראי', וזהו מעלת ומדריגת התורה, בחי' חכ' אדם תאיר פניו שיכולים לבוא למדריגת ראי' ממש באלקות כו', אך לא כל אדם זוכה לזה כ\"א יחידי סגולה ובני עלי' שמועטים המה כמ\"ש מזה במ\"א<sup data-n=\"362\">9</sup>.\n<b>אמנם</b> לבחי' ומדריגת הדעת זה יכולים כל אדם לבוא, והיינו שענין הדעת הוא בחי' ההכרה והרגשה כאילו רואה, הגם שאינו בחי' ראי' ממש, מ\"מ בחי'",[["360","7","<b>ה) ועוי\"ל הטעם שנק' התפילה בשם אחור . . ח\"י חוליות שבשדרה</b>: בהבא לקמן בפרק זה ראה ד\"ה לא הביט און בלקו\"ת בלק שם ע, ד ואילך."],["361","8","<b>וזהו שרצה משה לכנוס לארץ . . כי רצה להמשיך בחי' ראי'</b>: ראה בכ\"ז בארוכה לקו\"ת ואתחנן ב, סע\"ג ואילך. ג, ג ואילך. סה\"מ תרל\"ג ח\"ב ע' תכג. [ובהנסמן שם בתחילת המאמר]. ובהנסמן בהערה שלאח\"ז."],["362","9","<b>כ\"א יחידי סגולה ובני עלי' שמועטים המה כמ\"ש מזה במ\"א</b>: ראה סה\"מ תרכ\"ז ע' רצב. שפט. תרכ\"ט ע' רלא (וש\"נ). תרל\"ב ח\"א ע' קסח. שיט. ח\"ב ע' שע. תרל\"ג ח\"ב ע' תכח."]]],[2002180165,"הכרה והרגשה הוא כאילו רואה. דהנה יש ב' בחי' דעת ואמונה<sup data-n=\"363\">10</sup>, אמונה הוא למעלה מן השכל שהוא רק בחי' מקיף לבד, ומפני שהוא בבחי' המקיף לבד לכן יכול להיות שיעשה נגד לגמרי<sup data-n=\"365\">11</sup>, ועכ\"ז יאמין, וע\"ד שארז\"ל גנבא אפום מחתרתא רחמנא קריא<sup data-n=\"364\">12</sup>, ולכאורה מאחר שהוא נכנס במחתרת לגנוב שזהו היפך רצה\"ע שא' לא תגנב, והאיך הוא קורא רחמנא, שהקב\"ה יעזור לו לעשות היפך רצונו, אלא שקריאתו זה הוא בבחי' מקיף כ\"כ עד שגם אם היות שהוא מאמין בהקב\"ה שה\"ה קורא אליו שיעזור לו, עכ\"ז בחי' מקיף זה כ\"כ רחוק ואינו נוגע בפנימיותו עד שעושה היפך רצונו ית', משא\"כ בחי' דעת הוא בחי' התקשרות בבחי' הכרה והרגשה כאילו רואה שנמשך בפנימיותו. וזהו מה שנצטוינו וידעת היום כו' כי הוי' הוא האלקים, ודוד צוה לשלמה בנו דע את אלקי אביך ועבדהו שיהי' בבחי' דעת שהוא הכרה והרגשה כאילו רואה עכ\"פ, וזהו מדריגת התפילה שהיא בחי' הדעת והכרה כו', וזהו דכתיב דע את אלקי אביך ועבדהו בלב שלם ענין עבודה שבלב זהו תפילה, וזהו בחי' הדעת ולכן אמר דע כו' ועבדהו, ונודע כי דעת נחלק לחו\"ג שבעבודה זהו בחי' אהוי\"ר. וזהו דכתיב ובשתיים יעופף וקרא זא\"ז ואמר קדוש, שכדי שיומשך בחי' קדוש כו' הוי' בצבאי צבאות זהו ע\"י שבשתיים יעופף שהוא בחי' אהוי\"ר. וזהו שאומרים בתפילה ברוך אתה הוי', שפירושו שמבקשים שיהי' המשכת שם הוי' מבחי' אתה דקאי על אוא\"ס עצמו\"ה שלמעלה מבחי' שם הוי', שהרי שם הוי' הוא ג\"כ רק בחי' שם לבד כמ\"ש אני הוי' הוא שמי, וכנודע ששם הוי' מורה<sup data-n=\"366\">13</sup> על בחי' ההשתלשלות יו\"ד צמצום ה' התפשטות כו', ובחי' הארה הנמשכת בסדר השתלשלות היא רק הארה מצומצמת לבד לגבי בחי' שלמעלה מסדר ההשתלשלות, וז\"ע הבקשות שבתפילה ברוך היינו שיומשך בחי' ברכה והמשכה עצומ\"ה מלמעלה מסדר השתלשלות דהיינו מבחי' אתה שהוא אוא\"ס שלמעלה מהשתלשלות להיות צמצום היו\"ד דשם הוי' הוא בחי' סדר ההשתלשלות כו'. ופרטי הברכות רופא חולי כו' ומברך השנים עד\"מ הם הכלים שבו מתגלה המשכת אלקותו ית' בגשמיות כשמרפא החולים ומברך השנים, וכן כל הח\"י ברכות פרטים.\n<b>וז\"ע</b> שהתפילה שהיא בחי' עבודה שבלב זהו בחי' יעקב עבדי<sup data-n=\"367\">14</sup>, כי יעקב הוא בחי' יו\"ד עקב שנמשך היו\"ד אפי' בבחי' עקביים, והיינו עד\"מ החוט השדרה שנמשך מהמוח ומתפשט עד הירכיים שהם הרגליים, שזהו בנמשל בחי' היו\"ד שנמשך עד העקביים, ובעבודה בחי' יו\"ד זה הוא בחי' רעו\"ד שהוא בחי' הביטול",[["363","10","<b>דהנה יש ב' בחי' דעת ואמונה</b>: בהבא לקמן ראה בארוכה לקו\"ת ואתחנן ד, א ואילך. ו, א ואילך."],["365","11","<b>שיעשה נגד לגמרי</b>: אוצ\"ל: שיעשה נגד רצה\"ע לגמרי. [כמ\"ש כאן בסמוך]."],["364","12","<b>אמונה הוא למעלה מן השכל . . בחי' מקיף . . שארז\"ל גנבא . . רחמנא קריא</b>: ראה בכ\"ז בארוכה סה\"מ תר\"ל ע' קיא. תרל\"ב ח\"א ע' צ-צא. [ובדרושים שנסמנו שם בתחילת המאמר]."],["366","13","<b>וכנודע ששם הוי' מורה . . ההשתלשלות יו\"ד צמצום ה\"א התפשטות</b>: ראה גם לקו\"ת בלק שם ע, ד. לקמן ד\"ה אנכי אנכי. וש\"נ."],["367","14","<b>וז\"ע שהתפילה . . זהו בחי' יעקב עבדי</b>: בהבא לקמן עד סוף הפרק ראה לקו\"ת בלק שם עא, ד."]]],[2002180166,"ע\"ד בחי' היו\"ד דאזעירת גרמי' כנקודא חדא בחי' ביטול כו', והוא נקודא אוכמי דלית בי' חיוורא כלל מחמת רוב בחי' הביטול, ולכן בחי' גבוה כזו יכול להיות נמשך עד למטה מטה דהיינו גם בבחי' העקביים כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ח\"י ברכות כנגד ח\"י חוליות השדרה, שחוה\"ש נמשך ממוח הדעת שהוא מול ערפו בבחי' אחור, שהתורה היא בחי' פנים ראי', אך לא כל אדם זוכה לזה, ולבחי' הדעת יכול כל אדם לבוא שהוא בחי' הכרה והרגשה כאילו רואה, וכנודע ההפרש בין אמונה שהיא מקיף לבד ובין הדעת שהוא בפנימיות, ודעת נחלק לחו\"ג אהוי\"ר אשר ע\"י שתיים אלו יעופף להיות קדוש הוי' כו', וזהו ברוך אתה ה' שיתברך ויומשך מבחי' אתה שלמעלה מסדר השתלשלות שיהי' הוי' יו\"ד צמצום כו', וזהו יעקב יו\"ד עקב, ע\"ד החוה\"ש שמתחיל מהמוח עד הרגלים, ובעבודה רעו\"ד יו\"ד יכול להיות נמשך עד העקביים כו'.</span>\nוא\"ו) <b>אך</b> הנה בחי' תורה זהו מעלת בחי' ישראל שנק' בן כמ\"ש בני בכורי ישראל, שהוא בחי' כמראה אדם שנת' לעיל שמאיר ע\"י בחי' חכמת התורה כמ\"ש חכמת אדם תאיר פניו בבחי' כמראה אדם. וזהו מה שמו הוא בחי' מה דחכמה ובחי' מה זה תאיר פניו של בחי' כמראה אדם שזהו בחי' מה שם בנו. אך מ\"מ א\"א להגיע לבחי' ישראל שהוא בחי' תורה הנק' פנים כ\"א ע\"י תפילה בחי' אחור הנ\"ל, וצ\"ל ב' הבחי' ביחד דוקא יעקב וישראל. ולכן הגם דכתיב ולא יקרא עוד שמך יעקב כ\"א ישראל יהי' שמך, מ\"מ לא נעקר שם יעקב ממנו לגמרי, ואינו כמו באברהם שארז\"ל כל הקורא לאברהם אברם עובר בעשה, והיינו מפני כי אהדרי קרא לקרותו יעקב, אמנם ג\"ז אינו מובן מפני מה אהדרי קרא לקרותו יעקב אחרי אשר בשם ישראל יכונה. אלא מפני כי ב' השמות דיעקב וישראל צריכים להיות, מפני כי גם אחרי אשר בשם ישראל יכונה יש בחי' ומדריגת יעקב בעבודה, אשר ע\"י בחי' יעקב יעלה ויבא ויגיע לבחי' ישראל כו', וא\"כ ה\"ה צריך לשם ישראל, וכנ\"ל שבלא התשוקה והצמאון אין המים מרוווים כלל, א\"כ בלא בחי' יעקב א\"א להיות בחי' ישראל כו', נמצא שלבחי' ישראל בהכרח שיהי' גם בחי' יעקב כו' ולכן אהדרי קרא לקרותו יעקב בכדי שע\"י בחי' יעקב יגיע לבחי' ישראל כו'.\n<b>וזהו</b> דכתיב לא הביט און ביעקב<sup data-n=\"368\">15</sup> ולא ראה עמל בישראל, דכשיש ב' הבחי' יעקב וישראל אז האון א\"א לו להביט בבחי' יעקב גם מצד עצמו, דהנה פי' און הוא בחי' הלעו\"ז דבחי' יעקב, שענין און הוא כמ\"ש איש און מחשבותיו, שז\"ע המרמה ורמאות, ומחשבות והרהורין בישין שהם לעומת בחי' התפילה שהיא עבודה שבלב ומח' טובה שהיא בחי' כוונת הלב שהעיקר הוא המחשבה, וע' בלק\"ת בד\"ה כי ביום הזה יכפר בפ' אחרי דרוש הראשון<sup data-n=\"369\">16</sup>, ולכן כשהאדם מתבונן בבחי' חב\"ד שבנפשו",[["368","15","<b>וזהו דכתיב לא הביט און ביעקב</b>: בהבא לקמן בפיסקא זו ראה ד\"ה לא הביט בלקו\"ת בלק שם ע, סע\"ד. [והוא ע\"פ ל' הלקו\"ת שם בשינויים]."],["369","16","<b>וע' בלק\"ת בד\"ה כי ביום הזה יכפר בפ' אחרי דרוש הראשון</b>: כה, ד ואילך."]]],[2002180167,"ברוממות וגדולת ה', עומדים כנגדו מח\"ז והירהורים בישין שמסט\"א שהם מחשבות דאיש און הנ\"ל בכדי לבלבלו כו', אמנם גדול כח בחי' יעקב גם מצד עצמו לדחותו ולהעבירו כי ניתן כח ויתרון לקדושה על הסט\"א. וזהו לא הביט און ביעקב שלא יוכל האון להביט בבחי' יעקב ולבלבלו כי לא יוכל לו כמ\"ש וירא כי לא יכול לו, כ\"א נפל יפול לפניו כו'.\n<b>ולא</b> ראה עמל בישראל<sup data-n=\"370\">17</sup>, ולכאורה צ\"ל הלא כתיב אדם לעמל יולד, אך באמת הלא ארז\"ל בסנהדרין דצ\"ט ע\"ב שזהו בחי' עמל תורה, והגם דכתיב מה יתרון לאדם בכל עמלו שיעמול תחת השמש, הנה ארז\"ל ע\"ז בפ\"ב דשבת ובזהר בכ\"ד, שאני עמלא דאורייתא<sup data-n=\"371\">18</sup> דלעילא מן שמשא היא. ואמנם מה שצ\"ל הלא בפ' שני' דק\"ש נאמר ואספת דגנך כו' שזהו העמל שתחת השמש הוא, אך הענין הוא דכתיב שמש ומגן ה' אלקים, שנמשל שם הוי' לשמש, והיינו כמו שהאור המאיר מהשמש הוא רק בחי' זיו לבד שהוא הארה בעלמא, וגם הזיו וההארה זו עצמה היא בטילה בתכלית בעצם כדור השמש עד שאינו עולה בשם כלל, עד\"ז יובן ענין בחי' שם הוי', שאם היות שש' הוי' הוא לשון התהוות, וכנודע שעיקר ההתהוות היא משם הוי', מ\"מ הנה הוא רק זיו והארה בעלמא, וכמ\"ש אני הוי' הוא שמי שגם שם הוי' הוא רק שם לבד שהוא הארה וזיו, וגם הנה הוא בטל בתכלית, ושם אלקים נמשל למגן<sup data-n=\"372\">19</sup> שכמו מגן השמש הנה הוא מכסה על אור השמש כך בחי' שם אלקים הוא מגן ומסתיר על בחי' אור ה' וקדושתו כו', אך הנה מ\"מ אין ההסתר דשם אלקים בחי' הסתר גמור, והיינו הגם שע\"י אמצעית בחי' ש' אלקים נעשה בחי' מציאות היש, מ\"מ היש הוא יכול להיות בטל לאין, אמנם יש בחי' ק\"ך צירופי אלקים אשר ע\"י בחי' צירופי' האחרונים דשם אלקים נעשה בחי' העלם והסתר גמור, עד שנראה העוה\"ז ליש ודבר נפרד לגמרי.\n<b>וע\"ז</b> הוא שאמר בפ' שני' דק\"ש ואספת דגניך<sup data-n=\"373\">20</sup> שיאסוף כל דברים הגשמיים לאלקות, והיינו כי ק\"ש הוא בחי' ביטול, אחד ועד הם בחי' יחו\"ע ויחו\"ת,",[["370","17","<b>ולא ראה עמל בישראל</b>: בכל הבא להלן (עד סיום המאמר) ראה בשינויים כו' אוה\"ת נ\"ך כרך א' ע' תרי-יא [ד\"ה נפש עמל עמלה לו]. כרך ב' ע' א'קא [ד\"ה מה יתרון לאדם בכל עמלו]. כרך ג' ע' א'שעח [ד\"ה יש אדם שעמלו בחכמה]. ובאריכות ושינויים בד\"ה לא הביט: סה\"מ תרל\"ב ח\"ב ע' שפג ואילך. סה\"מ תרס\"ט ע' רי ואילך. [וראה בהנסמן עוד בהמ\"מ בסה\"מ תרל\"ב שם]. מכאן עד סוף המאמר מיוסד על סד\"ה לא הביט און בכת\"י 466 קכג, א [הוא כת\"י הכולל הנחות של מאמרי אדמו\"ר הצ\"צ]."],["371","18","<b>הנה ארז\"ל ע\"ז בפ\"ב דשבת ובזהר בכ\"ד </b> [ בכמה דוכתי]<b> שאני עמלא דאורייתא</b>: בסה\"מ תרל\"ב שם ע' שפד מביא מגמ' שבת ד\"ל ע\"ב (ופירש\"י שם) וזח\"א ויחי דרכ\"ג סע\"ב. וראה גם זח\"ב נט, א: אבל ההיא מלה דאיהי פולחנא דמרי' דא סליק לעילא מן שמשא כו' צדיקייא דכל עובדיהון למעלה מן שמשא כו'. וראה גם קה\"ר עה\"פ."],["372","19","<b>דכתיב שמש ומגן ה' אלקים שנמשל שם הוי' לשמש . . ושם אלקים נמשל למגן</b>: ראה תניא שעהיחוה\"א פ\"ד ואילך. תו\"א בראשית ד, סע\"ד ואילך. יהל אור להצ\"צ ס\"ע ש ואילך."],["373","20","<b>וע\"ז הוא שאמר בפ' שני' דק\"ש ואספת דגניך</b>: ראה גם סה\"מ תרכ\"ו ע' קסט וע' קעא. ובכ\"מ."]]],[2002180168,"וצריך לאסוף דברים הגשמיים שגם הם יבואו להתכלל בבחי' הביטול והיינו ואספת דגנך הם כל המלאכות הגשמיי' הזורע והחורש והקוצר כו' שא\"א לאדם מבלי שיטרח על מזונותיו. אמנם ארז\"ל עשה תורתך קבע ומלאכתך ארעי, שענין קבע וארעי אין הכוונה בשהיית הזמן כ\"א בעיקר המכוון וכמשל עשיית המסחר הגם שמוציא ע\"ז זמן הרבה עיקר הכוונה הוא בשביל הריוח שהוא בשעה מועטת, כמ\"ש מזה במ\"א באורך<sup data-n=\"374\">21</sup>, וכך כל עיקר ענין עשיית מלאכתו או מו\"מ יהי' בשביל שירויח בכדי שיוכל ליתן צדקה, והזן ומפרנס בניו וב\"ב זהו עושה צדקות בכל עת, וגם בכדי שיוכל ללמוד ולהתפלל, ועי\"ז אוסף עסקיו הגשמיים ג\"כ לאלקות כו'<sup data-n=\"375\">22</sup>.\n<b></b>[וזהו ששזפתני השמש<sup data-n=\"376\">23</sup>, היינו כמו למשל שהשמש ע\"י תוקף החום הוא משחיר, וכך הוא ענין שע\"י התבוננות בק\"ש בבחי' ש' הוי' שנק' שמש, עי\"ז נשרף בשלהובא דרחימותא, וכמ\"ש ואהבת כו', אך כשנמשך בבחי' חמימות ותאוות בלעו\"ז שהוא בחי' אדמת בני חם, חמימות ותאוות שזהו ע\"י ריבוי צירופי' של ש' אלקים שהוא בחי' מ\"ח צירופי' אחרונים המסתירים לגמרי, לזה נאמר מה יתרון לאדם בכל עמלו שיעמול תחת השמש כו'. נמצא שיש ב' בחי' עמל, עמל שתחת השמש, שהוא בחי' עמל שמסתיר על אלקים לגמרי, ובחי' עמל שבטל לאלקים מלאכתן עראי.\n<b>אך</b> הנה עמל תורה הוא למעלה גם מבחי' עמל זה וכמשארז\"ל שאני עמלא דאורייתא דהוא לעילא מן שמשא. והענין הוא דהנה כתיב כי יש אדם שעמלו בחכמה ובדעת ובכשרון ולאדם שלא עמל בו יתננו חלקו גם זה הבל ורעה רבה, ומדרש אגדה בתנחומא יכנהו כלפי הקדב\"ה שנאמר בו ועל הכסא דמות כמראה אדם עליו מלמעלה, שעמלו בחכמה שנאמר ה' בחכמה יסד ארץ כונן שמים בתבונה בדעתו תהומות נבקעו, ולבריות שלא עמל בו יתן חלקו בם, גם זה הבל ורעה רבה, והם נעשו דור של הבל ורבה רעת האדם בארץ בדור המבול ע\"כ. והנה לכאורה אין זה מובן שהרי כתיב לא בעמל ולא ביגיעה ברא את העולם.\n<b>אך</b> הענין הוא דהנה ברה\"ע הוא [לא] בעמל ולא ביגיעה, לפי שהוא רק מבחי' זיו והארה בעלמא כו', אך מ\"ש יש אדם שעמלו בחכמה קאי על התורה, שהוא בחי' חכ' אדם תאיר פניו, והנה בתורה נמשך המשכה פנימי' כו' וע\"כ לגבי ברה\"ע שהוא רק בחי' זיו והארה לגבי בחי' זו נק' המשכה שע\"י התורה בחי' עמל, וזהו שאני עמלא דאוריי' דהוא לעילא מן שמשא, לפי שהוא למעלה מבחי' עמל של בחי' שמש הוי' לפי שאף שעמל של בחי' שמש, בחי' תורתן קבע ומלאכתן ארעי, אעפ\"כ צריך",[["374","21","<b>עשה תורתך קבע . . כמ\"ש במ\"א באורך</b>: ראה סה\"מ תרכ\"ו ע' קסח. קעא. תרכ\"ט ע' כז. תא. תר\"ל ע' רמד. רנב. תרל\"ב ח\"ב ע' שפה. שפח. תרל\"ג ח\"א ע' קלז. ועוד."],["375","22","<b>לאלקות כו'</b>: ע\"כ נרשם בגוכי\"ק."],["376","23","<b>[וזהו ששזפתני השמש</b>: מכאן עד סוף המאמר הוא חלק מד\"ה לא הביט און בכת\"י 466 שם, ונמצא בבוך תרל\"ט בכת\"י מעתיק בהמשך להמאמר — בהבא לקמן ראה גם לקו\"ת שה\"ש ה, ד."]]],[2002180169,"לעשות מלאכה שזהו רק בחי' ביטול היש לבד, ותורתן אימתי נעשית, וכמו שהקשה רשב\"י, אפשר שיהא חורש בשעת חרישה וזורע בשעת זריעה וקוצר בשעת קצירה, תורתן אימתי נעשית, אלא כשעושין רצונו של מקום מלאכתן נעשית ע\"י אחרים, והנה בחי' זו שיהי' תורתן קבע אומנתן ממש זהו בחי' עמלא דאורייתא דהוא לעילא מן שמשא, יש אדם שעמלו בחכמה, וזהו משארז\"ל נפש עמל עמלה לו כו'<sup data-n=\"377\">24</sup>. והנה ע\"י בחי' עמלא דאורייתא עי\"ז ולא ראה עמל בישראל שהוא בחי' עמל שתחת השמש כו'.\n<b>ה'</b> אלקיו עמו ותרועת מלך בו, והיינו כי עמו הוא רק בבחי' מקיף, וכמ\"ש עמו אנכי בצרה גלו לבבל שכינה עמהם שהוא רק בבחי' מקיף לבד, ותרועת מלך בו הוא בבחי' המשכה פנימי' כו'. וזהו ענין תורה ומצות, שמצות הם רק בבחי' מקיף לבד והתורה הוא בבחי' המשכה פנימי' כו'].",[["377","24","<b>וזהו משארז\"ל נפש עמל עמלה לו כו'</b>: בסנהדרין צט, ב: שנאמר נפש עמל עמלה לו כו' הוא עמל במקום זה ותורתו עומלת לו במקום אחר. ובאוה\"ת נ\"ך שם ע' תריא: וזהו הפי' שתורתו עומלת לו כי חכמת אדם קאי על התורה והיינו מ\"ש רש\"י שעומלת לו שיתגלו לו רזי תורה כו'."]]],[2002180170,"<h3>וידבר כו' ידור נדר כו' (א)</h3>\n<b></b><b>בס\"ד. (ש\"פ מטו\"מ, ט\"ל).</b>\nשרש היתר ואיסור (פרק: א-ג)\nמטו\"מ\n<b>וידבר</b> משה<sup data-n=\"378\">1</sup> אל ראשי המטות כו' זה הדבר כו' איש כי ידור נדר כו', וצ\"ל שורש ענין הנדרים הלא ארז\"ל בירושלמי רפ\"ט דנדרים, הובא בח\"פ להרמב\"ם פ\"ה, א\"ר דימי בשם ר' יצחק לא דייך מה שאסרה לך התורה אלא שאתה מבקש לאסור עליך דברים אחרים, ולפ\"ז צריך להבין שרש ענין מעלת הנדרים, וגם איך ע\"י הדבור שלו יש ביכולתו לאסור דברים המותרים, ואם יש כח בדבורו לאסור דברים המותרים איך החכם ע\"י דבורו ביכולתו להתיר דבר הנדור כו'.\n<b>והענין</b> יובן בהקדם תחלה שרש ענין היתר ואיסור<sup data-n=\"379\">2</sup> מהו, והוא כי שרש ההיתר הוא מק\"נ שמעורב טו\"ר, ושרש דברים האסורים הוא מגקה\"ט לגמרי, ונמצא",[["378","1","<b>וידבר משה</b>: מאמר זה (והמאמר שלאחריו ד\"ה אמנם כו' ענין הנדרים) נמצא ג\"כ בסה\"מ תר\"ל ע' רטז ואילך, רכג ואילך, וכאן הוא בתוס' הגהות וקיצורים. ומיוסד על ביאור לד\"ה וידבר גו' ראשי המטות באוה\"ת מטות ע' א'דש ואילך. מאמר האוה\"ת הוא הגהות לביאור לד\"ה וידבר גו' ראשי המטות בס' מאמרי אדה\"ז תקס\"ז ע רצו ואילך. תוכן המאמר נמצא בהרחב הביאור בד\"ה זה בסה\"מ עטר\"ת ע' תקלז. ובד\"ה להבין ענין הנדרים בסה\"מ תשי\"ד ע' 154 ואילך. תו\"מ חי\"ב ע' 126 ואילך."],["379","2","<b>והענין יובן בהקדם תחלה שרש ענין היתר ואיסור</b>: בהבא לקמן ראה אוה\"ת מטות שם ס\"ע א'דש ואילך. — וראה בכ\"ז תניא ספ\"ז ופ\"ח."]]],[2002180171,"כי ק\"נ הוא ממוצע בין עולמות דקדושה לגקה\"ט, כי מעולמות דקדושה אין ביכולת גקה\"ט לקבל שום יניקה אם לא ע\"י אמצעית ק\"נ, ולכן הוא מעורב טו\"ר כמו הממוצע שכלול מב' הבחי'. וזהו שמצינו בערלה שציוה לנו שלש שנים יהי' לכם ערלים לא יאכל, ובשנה הרביעית יהי' כל פריו קדש הלולים (בפ' קדושים י\"ט ך\"ג ך\"ד), והיינו כי ג' שנים הראשונים הם כנגד גקה\"ט לגמרי לכן לא יאכל, אבל בשנה הרביעית שהיא כנגד ק\"נ אז מהני פדיון שע\"י הפדיון נכלל בקדושה. וזהו שנק' ק\"נ בשם להט החרב המתהפכת שפעמים מתהפכת ליכלל בקדושה ופעמים להיפוך כו'. ומאחר ששרש כל מאכלים המותרים הם מק\"נ לכן כשאוכל המאכל בכדי שע\"י כח האכילה יוכל ללמוד ולהתפלל הרי הוא מעלה המאכל מבחי' ק\"נ להכלל בקדושה, ואז מיתוסף לו חיות מהמאכל ע\"ד שארז\"ל<sup data-n=\"380\">3</sup> עד לא אכילנא בישרא דתורא לא צילאי דעתאי, ורב נחמן אמר עד דלא שתינא רביעית חמרא לא צלילנא דעתאי (ערובין דס\"ד א'), וכן א' רבא חמרא וריחני פקחין (סנהדרין ד\"ע, הוריות די\"ב), ופי' רש\"י שעי\"ז נעשה חכים, הרי שע\"י המאכל והיין ניתוסף כח שכלו, והוא כי באמת שרש המאכל הוא גבוה מאד נעלה כידוע ממארז\"ל אין לך עשב מלמטה שאין לו מזל מלמעלה המכה בו ואומר גדל, וכ\"ש בע\"ח כו', ושרש שרשם הוא מבחי' עולם התהו<sup data-n=\"381\">4</sup> שקדם לעולם התיקון, ולכן כשאוכל המאכל בכדי שיוכל ללמוד ולהתפלל שז\"ע מ\"ש צדיק אוכל לשובע נפשו אז המאכל מוסיף חיות וכח ועוז באדם דתיקון כו', והיינו שכשם שהמאכל מוסיף חיות באדם בגשמיות, כן כשמברר אותו ומעלהו בשרש שרשו בבחי' התהו הרי כשנמשך אור התהו באדם דתיקון נעשה חכים ביתר שאת, שהרי תהו קדם לתיקון במעלה, ולכן ענין הוספה זו הוא כדרך תוספתו של הקב\"ה שמרובה על העיקר כו'.\n<b>אבל</b> אם אוכל לתאוות נפשו אז ע\"י אכילה כזו מוריד המאכל מק\"נ לגקה\"ט, וכענין שארז\"ל ברכות ל\"ב א' מלי כריסי' זינא בישא ע' בפרש\"י שם, שזהו אפי' כשאוכל דברים המותרים וכענין דכתיב וישמן ישורון ויבעט, שמנת עבית כשית, פי' כשית בשין שמאלית הוא כמו כסית בסמך שעי\"ז מכסה ומסתיר ומעלים על בחי' אור ה' וקדושתו עד שנעשה בבחי' ערלת לב כו' כמ\"ש מזה במ\"א<sup data-n=\"382\">5</sup>, וכן כתיב וישב העם לאכול ושתו, מה נאמר אח\"כ לך רד כי שחת עמך כו' סרו מהר כו' (בפ' תשא ל\"ב וז\"ח). וזהו שאה\"כ כי דור תהפוכות המה בנים לא אמון בם (בפ' האזינו ל\"ב ך') ופי' רש\"י אמון ל' אמונה כתרגומו אמרו בסיני נעשה ונשמע ולשעה קלה בטלו הבטחתם ועשו העגל, והיינו כי אמן הוא מל' חוזק מל' ותקעתי יתד במקום נאמן, הא אם אינו חזק הוא נק' דור תהפוכות מל' הפכפך דרך איש וזר",[["380","3","<b>שארז\"ל עד דלא אכילנא בישרא דתורא . . וכן א' רבא חמרא וריחני</b>: ראה תניא פ\"ז שם."],["381","4","<b>באמת שרש המאכל הוא גבוה מאד . . מבחי' עולם התהו</b>: בהבא לקמן ראה בארוכה לקו\"ת מטות פא, ב ואילך. פב, ג ואילך. סה\"מ תרכ\"ט ע' שנח ואילך. [ובהנסמן שם]. תרל\"ג ח\"ב ע' שצד ואילך."],["382","5","<b>וכענין דכתיב וישמן ישורון ויבעט . . כשית . . כמו כסית . . כמ\"ש מזה במ\"א</b>: ראה לקו\"ת פינחס פ, ד. ר\"ה ס, א. האזינו עו, ב. לעיל ד\"ה ואמנם עדיין כו' האלף לך שלמה."]]],[2002180172,"(במשלי סי' ך\"א ח') שהוא בחי' ק\"נ שפעמים מתהפכת לקדושה ופעמים להיפך, וזהו להט החרב המתהפכת כו'. וע' מפסוק הפכפך דרך איש וזר ופסוק כי דור תהפוכות במד\"ר ריש רות ע\"פ ויהי בימי שפוט דף מ'. ובכלל קאי פסוק כי דור תהפכות על המרגלים שבעת ששלחם משה היו צדיקים אנשי שם ואח\"כ נתהפכו להיות רשעים גמורים כו', שזהו מפני הרע דק\"נ שנהפך להיות רע גמור כו', ע' בסש\"ב פך\"ט.\n<b>וזהו</b> שנצטוינו והתקדשתם והייתם קדושים (בפ' שמיני י\"א מ\"ד) ופי' רש\"י והתקדשתם קדשו עצמכם למטה והייתם קדושים שאקדש אתכם מלמעלה. וזהו כענין שארז\"ל ביבמות דף כ' גבי שניות לעריות, קדש עצמך במותר לך, והיינו להמשיך בחי' קדוש במותר, ופי' קדש הוא בחי' חכמה, והיינו ע\"י חכמת התורה שעי\"ז ממשיכים מבחי' קדוש בבחי' מותר. ולכן ארז\"ל באבות פ\"ג משנה ג' שלשה שאכלו על שולחן אחד ולא אמרו עליו ד\"ת כאלו אכלו מזבחי מתים, אבל שלשה שאכלו על שולחן אחד ואמרו עליו ד\"ת כאלו אכלו משולחנו של מקום ב\"ה, והיינו כי ע\"י התורה ממשיכים מבחי' קדוש בבחי' מותר כו'.\n<span data-k=\"ks\"><b>קיצור.</b> לא דייך מה שאסרה תורה, היתר ק\"נ, איסור גקה\"ט, ג\"ש ערלה גקה\"ט, רביעית ק\"נ ולכן מהני פדיון, להט החרב המתהפכת, ולכן כשאוכל לש\"ש מעלה המאכל לשרשו שגבוה מאד בתהו, ואז נותן כח לאדם בתיקון, אבל כשממלא כריסו זינא בישא ה\"ה מורידו, וזהו והתקדשתם קדשו עצמכם למטה והייתם קדושים שאקדש אתכם מלמעלה, וזהו קדש עצמך במותר לך, להמשיך בחי' קדוש בהיתר, ע\"י התורה, וגם כענין יוחנן בן גודגדא הי' אוכל עטה\"ק כל ימיו.</span>\nב) <b>ומעתה</b> צ\"ל שרש ענין הנדרים<sup data-n=\"383\">6</sup>, שלכאורה הלא דייך מה שאסרה תורה, אלא שאתה מבקש לאסור דברים המותרים כו'. אך הענין הוא דמעלת הנדרים הוא כמארז\"ל באבות פ\"ג מי\"ג נדרים סיג לפרישות, ופי' בס' מדרש שמואל שענין פרישות הוא מילי דחסידותא יעו\"ש. ופי' וענין מילי דחסידותא הוא כי בד\"כ יש ד' מדרגות צדיק ובינוני ורשע, וחסיד, שחסיד גבוה במעלה ומדריגה גם מבחי' צדיק<sup data-n=\"384\">7</sup> כמ\"ש הרח\"ו בשע\"ק. ולכן מצינו שארז\"ל ברכות דל\"ב סע\"ב על מתניתין דברכות רפ\"ה חסידים הראשונים היו שוהין שעה אחת, וכי מאחר שהיו שוהין ט' שעות ביום בתפלה תורתן האיך משתמרת ומלאכתן האיך נעשית, אלא מתוך שחסידים היו תורתן משתמרת ומלאכתן מתברכת, וכן כתיב וללוי אמר תומיך ואוריך לאיש חסידיך, נמצא שמעלת החסיד גבוה מאד כו'. והיינו כי ג' בחי' צדיק ובינוני ורשע הוא כנגד ג' עולמות בי\"ע<sup data-n=\"385\">8</sup> כמ\"ש בפע\"ח שער חגהמ\"צ, בענין ארבעה",[["383","6","<b>ב) ומעתה צ\"ל שרש ענין הנדרים</b>: בהבא לקמן ראה אוה\"ת מטות שם ע' א'שז. א'שכ."],["384","7","<b>שחסיד גבוה במעלה . . מבחי' צדיק</b>: ראה בכ\"ז [נוסף לאוה\"ת מטות שם] מאמרי אדהצ\"צ הנחות תרי\"ד ע' כט. וש\"נ."],["385","8","<b>צדיק ובינוני ורשע הוא כנגד ג' עולמות בי\"ע</b>: ראה אוה\"ת ואתחנן ע' תד. (בשם סש\"ב). סה\"מ תרל\"ג ח\"א ר\"ע רו."]]],[2002180173,"בנים דברה תורה, חכם באצי', רשע בעשי', והיינו שבעשי' רובו רע ומיעוט טוב והטוב מעורב ברע, ואפ\"ל שזהו בלבושים דעשי', אבל בע\"ס דעשי' לא יש בחי' הרע, כ\"א בלבושים דעשי' רובו רע ומיעוטו טוב והטו\"ר מעורבים זע\"ז, ולכן זהו בחי' רשע שרובו רע, ועכ\"ז מעט טוב יש בו שהרי הוא מתפלל בכ\"י ומלא מצות כרמון כו', ובינוני הוא כנגד עולם היצי' אשר שם מחצה טוב ומחצה רע, וצדיק כנגד עולם הבריאה אשר שם רובו טוב ומיעוטו רע והרע אינו מעורב בהטוב כ\"א מובדלים זמ\"ז. והגם שבסש\"ב פי' שהצדיק הוא שאין בו בחי' רע כלל<sup data-n=\"386\">9</sup>, אמנם לפי' הגמ' כל שיש בו רובו טוב ה\"ה נק' צדיק. וחסיד הוא כנגד עולם האצי' אשר שם לא יגורך רע כלל, שלא יש אפי' מעט מזעיר בחי' הרע כו'.\n<b>וזהו</b> ע\"פ פשוט, ועפ\"י חסידות יש לפרש ההפרש שבין חסיד לצדיק, והוא בהיות ידוע שענין ק\"ש הוא למסור נפשו באחד, ולכאורה צ\"ל מהו שאומרים אח\"כ ואהבת כו' בכל נפשך וארז\"ל במשנה ספב\"ת דברכות אפי' נוטל את נפשך שז\"ע מס\"נ, ומה\"ע ב\"פ מס\"נ<sup data-n=\"387\">10</sup> למסו\"נ באחד ובכל נפשך. אך הענין יובן ע\"פ מה שידוע שיש ב' בחי' שכינתא עילאה ושכינתא תתאה<sup data-n=\"388\">11</sup>, ופי' וענין שכינתא עילאה ושכינתא תתאה הוא מה שנמשך מב' בחי' התבוננות אחד, ועד. אחד הוא בחי' יחו\"ע איך דכולא קמי' כלא חשיב, ואני הוי' לא שניתי, שאתה הוא קודם שנבה\"ע ואתה הוא לאחר שנבה\"ע בלי שום שינוי ח\"ו כלל וכלל, ומה שנראה העולם ליש ודבר, זהו מחמת ריבוי ההעלמי' והצמצומים וההסתרים עד שנראה ליש ודבר שז\"ע מ\"ש כי אל דיעות ה' ד\"ע וד\"ת<sup data-n=\"389\">12</sup>, ד\"ת הוא שהבריאה היא יש ודבר ונתהווה מאין, והיינו מפני שלמטה אינו מושג למעלה יותר מבחי' האין המהוה היש כו', אבל בחי' ד\"ע הוא שלמעלה היש האמיתי ולמטה הוא אין וכולא קמי' כלא חשיב. וכאשר יעמיק דעתו בהתבוננות זו דבחי' יחו\"ע איך שקמי' כלא חשיב אזי יבוא לבחי' שכינתא עילאה הוא בחי' כלה עילאה להיות בבחי' כליון מל' כלה שארי ולבבי דת\"י ואשתיצי גושמא, שהוא בחי' כליון כל הרצונות ליכלל וליבטל באוא\"ס ב\"ה בבחי' ביטול במציאות כו'. אך הנה לא כל אדם יכול לבוא לבחי' ביטול זה דלמס\"נ באחד בחי' ביטול במציאות, כמ\"ש במ\"א בענין אנשי יריחו היו כורכים את שמע<sup data-n=\"390\">13</sup> כו', לזאת",[["386","9","<b>שבסש\"ב פי' שהצדיק הוא שאין בו בחי' רע כלל</b>: ראה תניא פ\"א. פ\"י."],["387","10","<b>שענין ק\"ש . . למסור נפשו באחד . . מהו שאומרים אח\"כ . . בכל נפשך . . ומה\"ע ב\"פ מס\"נ</b>: הבא לקמן עד סוף הפרק מיוסד על ד\"ה שיר השירים בלקו\"ת שה\"ש א, א ואילך. מאמרי אדה\"ז תקע\"א ע' סב ואילך. הנחות הר\"פ ע' קלח. כתובים ח\"א ע' א. דרמ\"צ קלח, ב ואילך. אוה\"ת שה\"ש (כרך א) ע' טו ואילך. סה\"מ תרל\"ב ח\"ב ע' תצט ואילך. וע' תקיב ואילך."],["388","11","<b>אך הענין יובן ע\"פ מה שידוע שיש ב' בחי' שכינתא עילאה ושכינתא תתאה</b>: בהבא לקמן ראה גם סה\"מ תרל\"ב ח\"א ע' קצו. ח\"ב ע' תצט ואילך. המשך תער\"ב ח\"א ע' תצה ואילך. ע' תרסז ואילך. ובהנסמן להלן בסמוך."],["389","12","<b>כי אל דיעות ה' ד\"ע וד\"ת</b>: בהבא לקמן ראה בארוכה לעיל ד\"ה מזמור לתודה. וש\"נ."],["390","13","<b>כמ\"ש במ\"א בענין אנשי יריחו היו כורכים את שמע</b>: ראה תו\"א שמות נא, א. יתרו סז, ג. לקו\"ת צו יד, סע\"ג. [ובמקומות שנסמנו לעיל הערה ד\"ה שענין ק\"ש]. לעיל ד\"ה ובראשי חדשיכם. וש\"נ."]]],[2002180174,"התקינו לומר ועד שהוא בחילופי אתוון אחד, הוא בחי' ההתבוננות דיחו\"ת ד\"ת איך שהבריאה היא יש מאין, ומ\"מ צ\"ל ביטול היש לאין כו', וז\"ע מס\"נ דבכל נפשך אפי' נוטל את נפשך שהוא ענין מס\"נ דביטול היש לאין כו' ע\"י התבוננות דועד בחי' יחו\"ת שכינתא תתאה שהוא ג\"כ בחי' כלה הוא בחי' כלתה נפשי לחצרות כו' שהוא ג\"כ בחי' כלה אבל אינו כמו כלה שארי ולבבי כמ\"ש מזה במ\"א, וע' בלק\"ת בשה\"ש ד\"ה שה\"ש<sup data-n=\"391\">14</sup>. וכמו ההפרש שבין ב' בחי' כלה אלו כן הוא ההפרש בין צדיק לחסיד, שצדיק הוא בחי' ביטול היש לאין כמו בחי' כלה ושכינתא תתאה שמזה נמשך בחי' ביטול היש בנבראים דבריאה, אבל חסיד הוא כמו בחי' שכינתא עילאה בחי' ביטול במציאות ממש כו'.\n<span data-k=\"ks\"><b>קיצור.</b> מעלת הנדרים הוא שנדרים סיג לפרישות, ופרישות הוא מילי דחסידותא, שיש ד' מדריגות צדיק רשע ובינוני חסיד, שחסיד גבוה מצדיק כמ\"ש הרח\"ו, והם כנגד ד' עולמות אבי\"ע, רשע כנגד העשי' שרובה רע ומעורב, בינוני כנגד יצי' מחצה על מחצה, צדיק נגד עולם הבריאה שרובה טוב ואינו מעורב, חסיד נגד האצי' שלא יגורך רע כלל, ושרש ההפרש בעבודה זהו כמו ההפרש שבין למס\"נ באחד ובין בכל נפשך, כי יש ב' בחי' שכינתא עילאה ושכינתא תתאה, שכינתא עילאה מהתבוננות דאחד בחי' איך שלא שניתי כלל, בחי' ד\"ע שלמעלה היש שעי\"ז בא יבוא לבחי' כליון בחי' כלה שארי אשתצי גושמא, אך לא כל אדם יכול לבוא לזה, לכן אומרים ועד בחי' יחו\"ת ד\"ת שהיש בטל לאין ועי\"ז בא ג\"כ לבחי' כלה אלא שזהו בחי' כלתה נפשי, וזהו בכל נפשך אפי' נוטל כו', ועד\"ז ההפרש בין צדיק לחסיד צדיק הוא ע\"ד בחי' ביטול היש, וחסיד זהו כמו שכינתא עילאה ביטול במציאות כו'.</span>\nג) <b>ועפ\"ז</b> יובן מה שפי' במד\"ש על ענין נדרים סייג לפרישות שה\"ע מילי דחסידותא, פי' כי ענין הנדרים הוא מה שפורש א\"ע מהמאכלים הוא לפי שענין בירור המאכלים הוא ענין ביטול היש לאין, וע\"פ תורה שנתלבש בבריאה באפשרי לברר את המאכל שיוכלל בבחי' אין, שז\"ע היתר שאם יאכל אותו בכדי שיוכל ללמוד ולהתפלל אזי עולה מק\"נ ונכלל בבחי' ביטול היש לאין, וזהו שאמרו בירושלמי לא דייך מה שאסרה תורה היינו בחי' איסור לגמרי כנ\"ל סעי' א', אלא שאתה מבקש לאסור עליך דברים אחרים דק\"נ ג\"כ, הלא ע\"פ התורה שנתלבשה בבריאה באפשרי לברר זה שיוכלל בבחי' ביטול היש לאין.\n<b>אמנם</b> הנה כ\"ז הוא כמדריגת הצדיק שהוא בחי' ביטול היש לאין דבריאה, אך לגבי בחי' חסיד בחי' ביטול במציאות דאצי' הנה בירור זה דבירור המאכלים בחי' ביטול היש לאין הוא גשמי בערכו. וע\"ד דוגמא שאמר משה מאין לי",[["391","14","<b>כמ\"ש מזה במ\"א וע' בלק\"ת בשה\"ש ד\"ה שה\"ש</b>: דף א, א שם ואילך. וראה גם לקו\"ת במדבר ח, ב ואילך. סה\"מ תרל\"ב ח\"ב שם ע' תצט ואילך וע' תקיב ואילך."]]],[2002180175,"בשר פי' שלעוצם מעלת ומדריגת משה שהי' מבחי' מ\"ה דחכמה כמ\"ש ונחנו מה (ולכן התורה נק' ע\"ש משה כמ\"ש זכרו תורת משה עבדי, כי אורייתא מחכ' נפקת, ומשה הי' בחי' מ\"ה דחכמה כמ\"ש בד\"ה קדש ישראל<sup data-n=\"392\">15</sup>, וע' בפרד\"ס בשער ך\"ג הוא שער ערה\"כ פ\"ח, אות חכמה) לא הי' יכול להשפיל א\"ע להשפיע בחי' בשר, והיינו שלעוצם מעלת ומדריגת משה, הנה בחי' בשר גם לאחר הבירור שהוא בחי' אהבה ברשפי אש כמ\"ש מזה במ\"א<sup data-n=\"393\">16</sup>, לא הי' יכול להשפיל א\"ע להשפיע בחי' בשר להיותו תמיד בבחי' הביטול דמ\"ה דחכ' כו' אלא ע\"י אמצעית הע' זקנים שאמר לו הקב\"ה אספה לי שבעים איש כו' ואצלתי מן הרוח כו' ושמתי עליהם שהם היו למטה במדריגה מבחי' משה ולכן יהיו יכולים להשפיל בבחי' השפעת בשר היא אהבה ברשפי אש כו' וע' בלק\"ת בד\"ה והי' מדי חדש, בענין יבא כל בשר כו'<sup data-n=\"394\">17</sup>. ועד\"ז יובן בשרש ענין הנדרים שלגבי מעלת ומדריגת בחי' חסיד הבירור דביטול היש הוא גשמי בערך לגבי ביטול דעולם האצי' כו'.\n<b>וזהו</b> שנאמר וללוי אמר תומיך ואוריך לאיש חסידך, שאהרן הוא בחי' איש חסיד כו', כי הנה נודע ההפרש בין אהבה דאהרן לאהבה דאברהם<sup data-n=\"395\">18</sup>, שבכלל אהבה דאברהם הוא בחי' אהבת עולם, ואהבה דאהרן הוא בחי' אה\"ר כו', פי' אהבת עולם הוא האהבה שנמשכת מהתבוננות עולמות איך שנתהוו ריבוי עולמות עד אין שיעור, ובכל עולם ועולם פרטים רבים עד אין שיעור, ובטובו מחדש בכי\"ת מע\"ב, שבכל עת ובכל רגע נמשך חיות חדש להוות ולהחיות מאין ליש כו', אשר ע\"י בחי' התבוננות זאת באה לבחי' אהבה הוא בחי' אהבה דבכל נפשך בחי' ביטול היש לאין, ונק' נפשי אויתיך בלילה, בחי' חשך העלם שנמשכה מהתבוננות מלכותך מלכות כל עולמים ל' העלם כו', ואם שהיא ג\"כ בחי' ומדריגה גבוה שהרי ז\"ע מס\"נ דבכל נפשך אפי' נוטל כו' מ\"מ ה\"ז רק בחי' ביטול היש לאין. אבל ענין אהבה דאהרן הוא בחי' אה\"ר שבלי גבול, אהרן אותיות נראה, בחי' באורך נראה אור ביטול במציאות, ולכן נק' איש חסיד שממשיך בחי' ורב חסד כו'.\n<b>וזהו</b> מ\"ש חסידה ברושים ביתה<sup data-n=\"396\">19</sup> ופי' בזהר ויצא דקס\"ג ע\"א א\"ת ברושים אלא בראשים, והיינו כי ביתה הוא בחי' בי\"ע, ומל' דאצי' כמו שהיא באצי' הוא ג\"כ בראשים ביתה כנודע שפנימי' מל' דאצי' כמו שהיא באצי' היא בחי' כלת משה",[["392","15","<b>ומשה הי' בחי' מ\"ה דחכמה כמ\"ש בד\"ה קדש ישראל</b>: סה\"מ תר\"ל ס\"ע ריב. וראה גם סה\"מ תרכ\"ז ע' קנח ואילך. קפד ואילך."],["393","16","<b>לא הי' יכול להשפיל א\"ע . . אהבה ברשפי אש כמ\"ש מזה במ\"א</b>: לקו\"ת בהעלותך לא, ד ואילך. וראה גם סה\"מ תרל\"ב ח\"ב ע' תיד ואילך וע' תכא ואילך."],["394","17","<b>וע' בלק\"ת בד\"ה והי' מדי חדש בענין יבא כל בשר כו'</b>: פ' ברכה צז, ד."],["395","18","<b>הנה נודע ההפרש בין אהבה דאהרן לאהבה דאברהם</b>: ראה בארוכה לעיל ד\"ה בהעלותך גו'. וש\"נ."],["396","19","<b>וזהו מ\"ש חסידה ברושים ביתה</b>: בכ\"ז ראה אוה\"ת מטות שם ע' שז."]]],[2002180176,"שכינתא עילאה כמ\"ש מזה במ\"א<sup data-n=\"397\">20</sup>, ובמאו\"א אות ח' סעי' פ\"ה פי' חסידה בינה, חסיד חכ', וכן עולה פי' דברי הזהר הנ\"ל וע' במק\"מ, וע' בס' זה\"ח בפי' דברי הזח\"א הנ\"ל שחסידה היא בינה, ולכן בעשי\"ת שהם תלוי' בבינה כנודע צ\"ל פרישות<sup data-n=\"398\">21</sup> למטה יותר כמ\"ש בשו\"ע או\"ח סי' תקפ\"א ס\"ב לענין סיגופים וסי' תר\"ג לענין פרישות, והיינו כי אז אומרים אל מלך יושב על כסא רחמים מתנהג בחסידות, לכן צ\"ל למטה ג\"כ פרישות וכמו נדרים שהם בבינה הוא סייג לפרישות, שבבחי' זו צ\"ל פרישות בכדי שהדבר אשר פורש ממנה לא יעכב ולא ימנע לבחי' מילי דחסידותא בחי' חסידה בראשים כו', ועד\"ז בעשי\"ת שתלוי' ג\"כ בבינה. וזהו שמתנהג בחסידות צ\"ל למטה ג\"כ פרישות כו'. וזהו כמ\"ש ה' צלך, שכמו הצל<sup data-n=\"399\">22</sup> הנה כל מה שהאדם עושה בידו או בשאר אבר כנגדו עושה הצל ג\"כ כנגדו כמו\"כ ה' צלך כו'. ולכן בעשי\"ת צ\"ל זהירות ופרישות יותר מפני שמתנהג בחסידות שתלוים בבינה כו' צ\"ל למטה ג\"כ בחי' פרישות.\n<span data-k=\"ks\"><b>קיצור.</b> ועפ\"ז יובן מעלת הנדרים, כי בירור המאכלים זהו בחי' ביטול היש שע\"פ תורה שבבריאה ה\"ז בירור היתר, כענין מעלת הצדיק, אבל לגבי חסיד עדיין זה מסתיר, וכענין שא' משה מאין לי בשר, שגם בשר לאחר הבירור שהוא בחי' אהבה ברשפי אש לא הי' יכול משה להשפיל א\"ע בבשר, כ\"א הזקנים שהיו פחותים במעלה נגד משה ואהרן שהיו בבחי' מ\"ה דחכמה, ולכן וללוי אמר תומיך ואוריך לאיש חסידך שנק' חסיד, כנודע ההפרש בין אהבה דאברהם שהיא אה\"ע לאהבה דאהרן אה\"ר ביטול במציאות, וזהו חסידה ברושים, בראשית כלת משה פנימי' המל' שכ\"ע כמו בינה, כאמה בתה, ולכן בעי\"ת פרישות כי אז מתנהג בחסידות, ועד\"ז בכדי לבוא למילי דחסידותא זהו ע\"י פרישות, אשר נדרים סייג לפרישות כו'.</span>\n<b>",[["397","20","<b>כנודע שפנימי' מל' דאצי' . . כלת משה שכינתא עילאה כמ\"ש מזה במ\"א</b>: לקו\"ת שה\"ש לט, ד. וראה גם תו\"א וארא נח, ד. ובכ\"מ."],["398","21","<b>ולכן בעשי\"ת . . צ\"ל פרישות</b>: בהבא לקמן ראה אוה\"ת מטות שם ע' א'שח."],["399","22","<b>וזהו כמ\"ש ה' צלך שכמו הצל</b>: באוה\"ת מטות שם ע' א'שח מביא זה מהמדרש שמואל. עיי\"ש. ובכ\"מ מובא זה בשם הבעש\"ט ראה סה\"מ תרכ\"ז ע' שכו. וש\"נ."]]],[2002180177,"<h3></b>[היתר נדרים פורחין באויר] (ב) אמנם הנה כל ענין הנדרים</h3>\n<b></b><b>בס\"ד. (ש\"פ דברים, ט\"ל).</b>\n(ד-וא\"ו)\nדברים\nד) <b>אמנם</b> הנה כל ענין הנדרים<sup data-n=\"400\">1</sup> והפרישות הוא בד\"כ רק בחי' שמאל דוחה שמדחה את הדבר ההיא לבלי להעלותו רק שא\"א לו בדרך דחי' מפני כי אחור צרתני כמ\"ש במ\"א<sup data-n=\"401\">2</sup>, לכן הוא משפיל א\"ע ומגבי' את הדבר הנדור שהוא גבוה ממנו מצד שרשו, לכן א\"א לו להעלותו והרי הוא פורש א\"ע ממנו. וזהו ענין הפרישות שהוא מילי דחסידותא, שהוא בחי' הביטול דאצי', ולגבי בחי' ביטול זה הבירור הפשוט שהוא בחי' ביטול היש לאין מבלבל ומונע ומעכב נגד הביטול שבאצי', וע\"ד שצם ר\"ז מאה תעניתא<sup data-n=\"402\">3</sup> כי היכא דלשכח תלמוד בבלי, מפני שלגבי לימוד הירושלמי בלבל לו ידיעת השגתו בתלמוד בבלי כו', ועד\"ז יובן בענין בחי' ביטול היש לגבי בחי' ביטול אמיתי, ולכן כשמגיע לבחי' ביטול זה צ\"ל בבחי' פרישות, אבל אם הי' יכול להעלותו הי' יותר טוב הרבה, ונמצא כי כל זה הוא רק בחי' שמאל דוחה שהוא בעבודה בחי' שמאלו תחת לראשי כו'.\n<b>אבל</b> ענין מה שהחכם מתיר את הנדר<sup data-n=\"403\">4</sup> הוא שמעלה את הדבר הנדור להיות בבחי' אתהפכא מחשוכא לנהורא שגם הדבר הנדור יתעלה ליכלל בבחי' הביטול ולקרבו שהחשך יהפך לאור כו'. ויובן זה מענין האכילה דשבת<sup data-n=\"404\">5</sup>, שבשבת הגם כי אוכל לתאוות נפשו מ\"מ מאכילה דשבת שהיא מצוה אינו נמשך שום יניקה לחיצוני' כלל, שדוקא בששת ימי חול אם אוכל ח\"ו לתאוות נפשו אז מוריד המאכל כנ\"ל סי' א', אבל בשבת אפי' כשאוכל לתאוות נפשו ח\"ו אינו נמשך שום יניקה לחיצונים כלל שהרי האכילה היא מצוה כו'. ולכאורה צ\"ל מהו ענין שמובדל כ\"כ האכילה דשבת מששת ימי החול. אך הענין הוא דששת ימי החול שרשם מששה מדות הוא בחי' ששת ימים עשה, ולא נאמר בששת כמ\"ש במ\"א<sup data-n=\"405\">6</sup>, ושורש ששת ימים אלו הוא מבחי' בינה אם הבנים כו' אשר בינה מינה דינין מתערין, והיינו בסופה שהוא בחי' כעס על ההיפוך כשעמי לא התבונן ח\"ו, וע\"ז נאמר אש לפניו תלך ותלהט סביב צריו. והוא שנאמר וחרה אף בפ' שני' דק\"ש שלכאורה יפלא איך שייך ל' וחרה בבחי' הביטול דק\"ש, אך זהו כענין משארז\"ל מזיעתן של חיוה\"ק נהר דינור יוצא על ראש רשעים",[["400","1","<b>ד) אמנם הנה כל ענין הנדרים</b>: מאמר זה הוא המשך להמאמר שלפנ\"ז ד\"ה וידבר גו' המטות. וראה בהנסמן שם לכללות המאמר. הנחת כ\"ק אדמו\"ר מהורש\"ב מהמאמר נדפסה לקמן בחלק ההנחות, ושם מתחיל: ”היתר נדרים פורחין באויר\"."],["401","2","<b>מפני כי אחור צרתני כמ\"ש במ\"א</b>: ראה לקו\"ת מטות שם פא, ב. פב, ג ואילך."],["402","3","<b>וע\"ד שצם ר\"ז מאמר תעניתא</b>: ראה בכ\"ז תו\"א יתרו סט, ג. ובכ\"מ."],["403","4","<b>אבל ענין מה שהחכם מתיר את הנדר</b>: בהבא לקמן ראה אוה\"ת מטות שם ע' א'שח ואילך."],["404","5","<b>ויובן זה מענין האכילה דשבת</b>: בהבא לקמן ראה תו\"א חיי שרה טו, ג ואילך. בשלח סה, סע\"ב-ג. סידור עם דא\"ח רב, ג ואילך. לעיל ד\"ה מי זאת הנשקפה פ\"ג."],["405","6","<b>ששת ימים עשה ולא נאמר בששת כמ\"ש במ\"א</b>: ראה לקו\"ת אמור לא, ד. סה\"מ תרכ\"ט ע' ח. וש\"נ."]]],[2002180178,"יחול בגיהנם, שלכאורה הלא החיות הקדש עומדים ברעש גדול ואיך יומשך מהם בחי' דין קשה. אך באמת היא הנותנת שמפני שעומדים ברעש גדול כו' לכן בחי' הזיעה שלהם היא הפסולת מזה נמשך דין קשה על המנגד המונע ומעכב. וכן באדם שהוא עולם קטן צ\"ל בבחי' לעולם ירגיז אדם יצ\"ט על יצה\"ר על שמונע ומעכב אותו, והיינו שצריך לעורר הגבורות שבו על עצמו, היינו על בחי' הרע שבו שהוא מסט' דס\"מ ונוקבי' שהם הרשעים, וז\"ע על ראש רשעים יחול כו', ובזה יובן ענין וחרה שבפ' שני' דק\"ש שבא מהתלהבות דפ' ראשונה דק\"ש כו'. ועפ\"ז יובן ג\"כ ענין בינה מינה דינין מתערין בסופה שהוא בחי' קו השמאל שדיני' מתערים בסופה, הוא בחי' כעס על ההיפוך כשעמי לא התבונן ח\"ו כו'. ומפני כי בחי' זו היא מקור לבחי' סדר ההשתל' כו', לכן בבחי' זו א\"א להעלות הדבר הנדור כ\"א להיות בבחי' פרישות כו'. ולכן באכילה דחול ששרשו מגיע לבחי' זו, כשמגיע לבחי' ביטול זה צ\"ל בבחי' פרישות דוקא דאל\"כ א\"א לו להגיע לבחי' מילי דחסידותא כו' שמונע ומעכב כו'. אבל בשבת שהוא בחי' מוחין דאבא שהוא בחי' שלמעלה מהשתלשלות כמ\"ש במ\"א<sup data-n=\"406\">7</sup> ששם מאיר אוא\"ס ב\"ה שלמעלה מהשתלשלות משם נמשך שיהי' בבחי' אתהפכא מחשוכא לנהורא שיתעלה בחי' הטוב דנוגה עד שלא יומשך מהאכילה שום יניקה ח\"ו כו', והרע דנוגה שבמאכל ה\"ה נפרד בע\"ש עם חשיכה כנודע ממ\"ש במ\"א באריכות<sup data-n=\"407\">8</sup>. וכענין שתי הלחם שבשבועות שהיו באות חמץ, וכנודע ממארז\"ל כל המנחות באות מצה חוץ מתודה ושתי הלחם שהיו באות חמץ, והיינו שלעוצם הגילוי שמאיר אז גם חמץ יוכל להתעלות כו' כמ\"ש במ\"א כו'<sup data-n=\"408\">9</sup>. ולכן החמץ שבתודה ושתי הלחם הי' נאכל לכהנים דוקא, להיות כי שרש בחי' הכהנים הוא מבחי' חכמה כמ\"ש אתה כהן לעולם, כמ\"ש מזה בהגהות לד\"ה מזמור לתודה שבסידור<sup data-n=\"409\">10</sup>. וזהו ג\"כ ענין מה שע\"ה אסור לאכול בשר, ותלמיד חכם הוא להיפך שחמרא וריחני פקחין, ועד דלא אכילנא בשרא דתורא כו' כנ\"ל זהו מפני היותו תלמיד חכם שמקבל מבחי' החכ' אשר בחכ' אתברירו שגם הבשר יתעלה, וממילא יוסיף תוס' בבחי' חכמה דתיקון מפני כי שרשו הוא מבחי' התהו כנ\"ל. ועד\"ז יובן ענין האכילה דשבת שהוא מוחין דאבא, וכן ענין מה שהחכם מתיר את הנדר שגם דבר הנדור יתעלה להיות בבחי' אתהפכא מחשוכא לנהורא כו'. וכענין ההפרש שבין נדרים לחכם המתיר את הנדר כמו\"כ הוא ההפרש בין נדרים לקרבנות<sup data-n=\"410\">11</sup>, שהרי הקרבן היו מקריבים הבהמה ע\"ג המזבח והי' עולה כולה כליל שהי' נכללת באש שלמעלה, ולכן הכהן המקריב",[["406","7","<b>בשבת שהוא בחי' מוחין דאבא . . שלמעלה מהשתלשלות כמ\"ש במ\"א</b>: ראה לקו\"ת צו יא, ד ואילך. ביאוה\"ז לאדהאמ\"צ פ, ג ואילך. סה\"מ תרכ\"ז ע' תפט. וש\"נ."],["407","8","<b>נפרד בע\"ש עם חשיכה כנודע ממ\"ש במ\"א באריכות</b>: ראה תו\"א קיב, ד. סה\"מ תרכ\"ט ע' ח. תרל\"ב ח\"א ע' רל. תרל\"ג ח\"א ע' עט. ובכ\"מ."],["408","9","<b>גם חמץ יוכל להתעלות כו' כמ\"ש במ\"א כו'</b>: ראה סידור עם דא\"ח מה, א ואילך. פיה\"מ לאדהאמ\"צ צה, ג ואילך."],["409","10","<b>כמ\"ש מזה בהגהות לד\"ה מזמור לתודה שבסידור</b>: אוה\"ת נ\"ך ח\"ב ע' תתקפה ואילך. וראה לעיל ד\"ה מזמור לתודה. וש\"נ."],["410","11","<b>וכענין ההפרש שבין נדרים לחכם . . הוא ההפרש בין נדרים לקרבנות</b>: בהבא לקמן ראה בארוכה אוה\"ת מטות שם ע' א'שי."]]],[2002180179,"את הבהמה שרשו מבחי' חכמה קו הימין, בחי' ימין מקרבת, וארי' דאכיל קרבנין, אריה אור י\"ה, ופני ארי' אל הימין הוא בחי' ימין מקרבת שמקרב הבהמה, שז\"ע קרבן ל' קירוב, משא\"כ נדרים בכלל הוא בחי' שמאל דוחה.\n<b>ובעבודה</b> בנפש האדם זהו ההפרש בין תורה לתפלה, שתפלה הוא בחי' שמאל דוחה שז\"ע הוידוים שאומרים בתפלה אחר שמו\"ע אשמנו בגדנו, וגם בתפלה אומרים סלח לנו כי חטאנו, ולכאורה יפלא למה אחר המס\"נ בק\"ש אומרים סלח לנו<sup data-n=\"411\">12</sup> כו' והוידוים שאחר שמו\"ע. אך הענין הוא דקודם התפלה דרך איש ישר בעיניו ואם לא עבר על רצונו ית' ועושה ומקיים רצונו ית' בקיום המצות נדמה לו שקרוב הוא ואינו מרגיש כלל דקות הרע שבו, אך לאחר פסוד\"ז שהוא מל' זמיר עריצים כמ\"ש במ\"א<sup data-n=\"412\">13</sup>, וברכות ק\"ש הוא אריכות ההתבוננות בביטול המלאכים איך שהאופנים וחיות הקדש כו' ועי\"ז פועל הביטול בנה\"ב שמסכים ג\"כ להיות כי שרשו משם כמ\"ש במ\"א<sup data-n=\"413\">14</sup>, ואח\"כ בק\"ש כאו\"א לפום שעו\"ד אם למס\"נ באחד או לכה\"פ בבחי' בכל נפשך ביטול היש לאין, והעלי' דשמו\"ע, אז רואה ומרגיש בנפשו דקות הרע המונעו ומעכבו שע\"י א\"י להתעלות כו' לכן אומר סלח לנו כי חטאנו, ועיקר הוידוי הוא לאחר התפלה אשמנו כו' שהו\"ע הרחקת הרע ודחייתו בבחי' שמאלו תחת לראשי בחי' שמאל דוחה לבלי יעכבו עוד מלהתעלות כו', וה\"ז כדוגמת הנדרים שהם בבחי' שמאל דוחה, מפני כי אינו יכול להעלותו לכן פורש ממנו ומדחה אותו כו'. אבל ענין התורה הוא בחי' ימין מקרבת לקרב דברים שבנוגה שהתורה היא בחי' ימין כמ\"ש מימינו אש דת, ובחכמה שבתורה אתברירו בחי' קו הימין שגם דבר זה שבנוגה יוכל להתעלות כו'.\n<b>וז\"ע</b> התרת נדרים שאומרים כל נדרי ביוהכ\"פ, שהו\"ע התרת נדרים או משנה העברה או על שנה הבא כמחלוקת הפוסקים בזה<sup data-n=\"414\">15</sup>, ולכאורה הלא יוהכ\"פ הוא מעשי\"ת שנת\"ל שהם בבינה ואיך משם יומשך ענין התרת נדרים. אך הענין הוא דלוחות האחרונות ניתנו ביוהכ\"פ שהוא יום הארבעים מארבעים יום דלוחות האחרונות, לכן אז יכול להיות התרת נדרים כענין החכם שמתיר את הנדר כו', וע' בת\"א בד\"ה כי אברהם לא ידענו (דקנ\"ו ע\"ב דפוס קאפוסט<sup data-n=\"415\">16</sup>), והנה פורים ויוהכ\"פ בחד דרגא הארת יסוד אבא בנוק' והארתו יוצא עד למטה בבי\"ע.",[["411","12","<b>למה אחר המס\"נ בק\"ש אומרים סלח לנו</b>: בהבא לקמן ראה הוספות לתו\"א קיא, ד. לקו\"ת בהעלותך ל, ב. תצא לה, סע\"ב ואילך. דרושים לש\"ש סה, ג. סה\"מ תר\"ל ע' קיג. תרל\"ב ח\"א ע' צג. לעיל ד\"ה מי זאת הנשקפה. לקמן ד\"ה תקעו בחודש. ועוד."],["412","13","<b>פסוד\"ז שהוא מל' זמיר עריצים כמ\"ש במ\"א</b>: לקו\"ת פקודי ח, א. בחוקותי מז, ד. נצבים נא, ד. האזינו עד, א."],["413","14","<b>וברכות ק\"ש הוא אריכות ההתבוננות . . כי שרשו משם כמ\"ש במ\"א</b>: ראה לקו\"ת ויקרא ב, ב ואילך. פ' ראה לג, ג. לד, ב. ובכ\"מ."],["414","15","<b>או משנה העברה או על שנה הבא כמחלוקת הפוסקים בזה</b>: ראה תוס' ושא\"ר נדרים כג, ב."],["415","16","<b>בת\"א בד\"ה כי אברהם לא ידענו (דקנ\"ו ע\"ב דפוס קאפוסט)</b>: בדפוסים שלפנינו הוא בדף צג, ג."]]],[2002180180,"<span data-k=\"ks\"><b>קיצור.</b> שענין הנדרים זהו בחי' שמאל דוחה, אבל מה שהחכם מתיר הנדר זהו בחי' ימין מקרבת לקרב הניצוץ ולהעלותו ע\"ד אכילה דשבת שאינו מגשם ופרש שבתכם לא נאמר מפני שלא יש בו פסולת, וכענין חמץ שבתודה ושתי הלחם שנאכל לכהנים דוקא, וכמו ת\"ח שהבשר ויין מוסיפים לו חכמה, וכמו הקרבנות שמתעלים ע\"י הכהן ליכלל בבחי' אריה אור י\"ה, ובעבודה ז\"ע תפילה ותורה, תפילה היא כענין הנדרים שאומר סלח לנו אשמנו ע\"ד דחיות דקות הרע, ותורה ימין מקרבת בחכמה אתברירו ולכן ביוהכ\"פ שבו ניתנו לוחות אחרונות אומרים כל נדרי, בחי' היתר נדרים, והגם שהוא מעשי\"ת שהם בבינה, עכ\"ז ביוהכ\"פ מאיר הארת יסו\"א כמ\"ש בת\"א בד\"ה כי אברהם לא ידענו.</span>\nה) <b>אך</b> עדיין צ\"ל מהו ענין הדבור שהי' בקרבנות שהי' צריך להקדיש בפה, וגם בנדרים לבטא בשפתים דוקא, ומאין יש כח בדבור ע\"ז וכן דבור החכם להתיר הנדר כו'. אך הענין הוא דהבהמה שלמטה הוא גשמי ובכדי שתוכל להתעלות זהו ע\"י דבור האדם שממשיך ע\"י דבורו בחי' אור מקיף<sup data-n=\"416\">17</sup> על הבהמה, והכח שיש בדבור ע\"ז להיות כי שרש הדבור הוא גבוה מאד נעלה, שהרי אנו רואים שהתינוק כל ימי משך היניקה אינו יכול לדבר בטוב, כ\"א לאחר מוחין דיניקה כשנשלמים המוחין אצלו קצת אזי יכול לדבר בטוב, והוא לפי ששרש אותיות הדבור הם גבוהים מאד כמ\"ש ה' בחכמה יסד ארץ, אבא יסד ברתא, ששרש הדבור בחי' ברתא הוא מבחי' שם הוי' שבחכמה כו', לכן ע\"י דבור האדם יוכל להמשיך בחי' או\"מ על הבהמה להעלותה מגשמיותה ואח\"כ ע\"י הקרבן הוא ההעלאה והמשכה בפנימי'. וכן בנדרים כתיב ג\"כ איש כי יפליא לנדור (בפ' נשא סי' וא\"ו פסוק ב') וארז\"ל בנדה דף מ\"ו ע\"ב ובנזיר דף ך\"ט ב' מופלא הסמוך לאיש, ופי' מופלא הסמוך לאיש זהו בחי' הארת החכמה שמאיר בבינה כו' כמשי\"ת לקמן אי\"ה, ומזה נמשך הכח לבטא בשפתים בנדרים כו'.\n<span data-k=\"ks\"><b>קיצור.</b> שהקרבן צריכים להקדיש בפה דוקא, וכן בנדרים לבטא בשפתים, שהבהמה ודבר הנדור הם גשמי' ולכן צריכים להעלותם ע\"י שממשיך להם או\"מ ע\"י דבורו ששרשו מחכמה כמ\"ש בחכמה יסד ארץ, ואז יכול להיות העלאת הקרבן והמשכת נחוח לה', וכן בנדרים כי יפליא, הארת החכמה שמאיר בבינה כמשי\"ת.</span>\nוא\"ו) <b>ועפ\"ז</b><sup data-n=\"417\">18</sup> יובן הפסוק וידבר משה אל ראשי המטות כו' זה הדבר, פי' מטות הם י\"ב שבטים ששרשם וא\"ו מדות כפולות והם י\"ב גבולי אלכסונים חסד שבגבורה וגבורה שבחסד כו', וראשי המטות הם מוחין של מדות אלו, ומשה הוא",[["416","17","<b>שממשיך ע\"י דבורו בחי' אור מקיף</b>: ראה בכ\"ז בארוכה לקו\"ת מטות פב, ב. פג, ב ואילך."],["417","18","<b>וא\"ו) ועפ\"ז יובן הפסוק וידבר משה . . מטות .ֿ. י\"ב שבטים . . י\"ב גבולי אלכסון</b>: בהבא לקמן ראה אוה\"ת מטות שם ס\"ע א'שיג ואילך."]]],[2002180181,"בחי' מ\"ה שבחכמה מוחין בעצם. וע\"ד כמו ענין ישראל מתקשראן באורייתא שפי' ישראל הוא לי ראש בחי' ראש ומוחין, ועכ\"ז צ\"ל מתקשראן באורייתא בחי' חכמה כי אורייתא מחכמה נפקת, והיינו מפני כי המוחין דישראל לי ראש היינו בחי' מוחין של המדות בחי' מוחין דז\"א, ולכן צ\"ל ישראל מתקשראן באורייתא דמחכמה נפקת בחי' מוחין בעצם. ועד\"ז מלמעלמ\"ט וידבר משה בחי' מ\"ה דחכמה אל ראשי המטות בחי' מוחין דז\"א בחי' נדרים והיתר נדרים כו'. וזהו זה הדבר, דהנה כל הנביאים נתנבאו בכה נוסף עליהם משה שנתנבא בזה, פי' כה הוא בחי' כדמותנו כמ\"ש וביד הנביאים אדמה בבחי' דמות לבד ולא עצם הדבר, ולכן נק' אספקלרי' שאינה מאירה פי' כמו מה שקורין בל\"א שפיגל, שהגם שרואה דרך בה מ\"מ אינו רואה עצם הדבר כ\"א הדמות לבד, אבל משה נתנבא בזה בחי' אספה\"מ<sup data-n=\"418\">19</sup>, עד\"מ כמו כשרואים דרך זכוכית בהירה שאינו מסתיר כ\"כ על עצם הדבר ורואים דרך בה עצם הדבר. וז\"ע איזהו חכם הרואה שהוא בחי' ראי' דחכמה שאינו דומה שמיעה לראי', פי' כי הגם ששומע הדבר ומאמין שכך הוא ומצייר בנפשו הדבר ההיא, ואח\"כ כשרואה דבר אשר שמע ממנו תחלה ונצטיירה אצלו ממה ששמע כו' אינו דומה שמיעה לראי', והיינו כי הנחת הדבר ההיא בכחות נפשו אינו דומה שמיעה לראי', והוא לפי ששמיעה הוא בחי' בינה אזן מילין תבחן שהוא בחי' שמיעה בחי' בינה לבד כמ\"ש מזה בד\"ה הטה כו' פקח עיניך וראה<sup data-n=\"419\">20</sup>, אבל איזהו חכם הרואה הוא בחי' הראי' דחכמה כו'. ובעבודה זהו ההפרש בין שמע ישראל ל' השגה והבנה לבחי' שאו מרום עיניכם וראו בבחי' ראי' ממש כו'. וזהו וידבר משה בחי' מ\"ה דחכמה אל ראשי המטות בחי' מוחין דמדות, להיות אצלם הדבר בבחי' זה בחי' ראי' שיוכלו להתיר הנדר, שמזה שאמר אל ראשי המטות נלמד מזה ענין מה שיחיד מומחה מתיר את הנדר, והיינו שמשה המשיך להם בחי' איזהו חכם הרואה עד שיוכלו להעלות דבר הנדור בבחי' אתהפכא מחשוכא לנהורא ולהתיר אותו שיוכלל בקדושה כו'.\n<b>ולהבין</b> בתוס' ביאור<sup data-n=\"420\">21</sup> באיזהו כח הי' יכול משה להמשיך בחי' זו כו', הנה ארז\"ל במשנה פ\"א דסנהדרין סנהדרי גדולה היו של שבעים ואחד ולמדו זה ממשה שנאמר אספה לי שבעים ומשה על גביהם הרי ע\"א, והנה משה הי' מופלא שבב\"ד מופלא שבסנהדרין, והיינו כי פי' מופלא<sup data-n=\"421\">22</sup> הוא לפי שנאמר אספה לי שבעים כו' ואצלתי מן הרוח כו' וכתיב אח\"כ ויאצל מן הרוח כו' שהזקנים נאצלו מאור",[["418","19","<b>כל הנביאים נתנבאו בכה . . משה שנתנבא בזה . . אספה\"מ</b>: ראה בכ\"ז לעיל רד\"ה דבר גו' בהעלותך. וש\"נ. וראה בכ\"ז אוה\"ת מטות שם ס\"ע א'שטו ואילך."],["419","20","<b>כמ\"ש מזה בד\"ה הטה כו' פקח עיניך וראה</b>: סה\"מ תרכ\"ח ע' יב ואילך."],["420","21","<b>ולהבין בתוס ביאור</b>: בהבא להלן בפיסקא זו ראה אוה\"ת מטות שם ע' א'שיא-ב."],["421","22","<b>והנה משה הי' מופלא שבב\"ד . . פי' מופלא</b>: בהבא לקמן ראה גם אוה\"ת חנוכה (כרך ב) רפט, סע\"ב ואילך. ביאוה\"ז להצ\"צ ח\"א ע' תקל. ועוד."]]],[2002180182,"משה, ופי' ל' אצילות הוא הפרשת הארה<sup data-n=\"422\">23</sup>, וכענין הארת הנפש המחי' את הגוף שלא כל הנשמה מלובש בגוף כ\"א הארה ומקצת מן הנשמה, שהנשמה בעצמה אינו שייך בה חילוקי רמ\"ח אברים כו', ונמצא הארת הנפש המחי' את הגוף הוא רק מה שנאצל מן הנשמה הפרשת הארה לבד, דהנה אוא\"ס ב\"ה עצומ\"ה מובדל ומרומם מגדר עולמות ובכדי להיות בחי' בראתיו יצרתיו כו' זהו ע\"י ממוצע שהוא בחי' אצי', שאצי' הוא הפרשת הארה מאוא\"ס ב\"ה כו', ועד\"ז יובן ענין השבעים זקנים שנאצלו מן הרוח שעל משה שהיו רק הפרשת הארה מרוח משה כו', ומשה לגביהם הי' בבחי' מופלא כענין במופלא ממך אל תדרוש ובמכוסה ממך אל תחקור שהי' לגבי ע' איש הזקנים בבחי' פלא ובבחי' אתכסיא מהם כו', ולכן הי' בכחו להמשיך בחי' היתר נדרים שראשי המטות בחי' יחיד מומחה יהי' יכול להתיר הנדר, שענין התרת נדרים פורחים באויר בחי' אור יו\"ד בחי' אוירא דכיא כו', ומשה שהי' בחי' מופלא לגבי ע' איש הי' יכול להמשיך הכח לענין היתר נדרים כו'. ולכאורה צ\"ל הלא בנדרים יש ג\"כ בחי' מופלא שז\"ע מ\"ש לעיל איש כו' כי יפליא, מופלא הסמוך לאיש כו'. אך הענין דבאמת יש ב' בחי' מופלא, והיינו בחי' אאלפך חכמה אאלפך בינה, ובחי' מופלא הסמוך לאיש הוא בחי' הארת החכמה המאיר בבינה בחי' חכם בבינה ומזה נמשך הכח לבטא בשפתים כו', אבל בחי' פלא דמשה הוא בחי' אאלפך חכמה שהוא בחי' במופלא ממך אל תדרוש כו', לכן הי' בכחו להמשיך בחי' היתר נדרים שפורחין באויר בחי' אור יו\"ד כו' שגם ראשי המטות יוכלו להתיר הנדר כו'.\n<b>ובד\"כ</b> בחי' זה הדבר בעבודה הוא בחי' תפלה ותורה, תפלה היא מלמטלמ\"ע כענין שרש הנדרים שהם מלמטלמ\"ע לכן צ\"ל בחי' שמאל דוחה כו', ותורה הוא בחי' המשכה מלמעלמ\"ט בחי' ימין מקרבת שז\"ע מ\"ש בתורה ודברי אשר שמתי בפיך, וגם ארז\"ל כל הקורא בתורה הקב\"ה קורא ושונה כנגדו כו' שהוא בחי' המשכה מלמעלמ\"ט להיות בבחי' ימין מקרבת כו'. וזהו וידבר מל' ידבר ל' הנהגה, שמשה המשיך בראשי המטות בחי' היתר נדרים כו'.\n<span data-k=\"ks\"><b>קיצור.</b> משה מ\"ה דחכמה, ראשי המטות מוחין דז\"א, ע\"ד ישראל לי ראש מוחין דז\"א מתקשראין באורייתא שמחכמה נפקת, ואמר להם זה הדבר, זה אספה\"מ, איזהו חכם הרואה שאינו דומה שמיעה לראי', שיחיד ומומחה מתיר שגם הנגה שבמאכל יתהפך לנהורא כו', וביאור הענין איך המשיך משה זה לראשי המטות, כי משה הוא ע\"ד מופלא שבסנהדרין, בחי' אאלפך חכמה לכן המשיך בחי' היתר נדרים שפורחין באויר בחי' אור יו\"ד בחי' אוירא דכיא כו'.</span>",[["422","23","<b>אספה לי שבעים איש כו' ואצלתי . . ל' אצילות הוא הפרשת הארה</b>: ראה בכ\"ז תו\"א בראשית ג, א. וירא יד, א. מאמרי אדה\"ז תקס\"ג ח\"א ע' רצב ואילך. אוה\"ת ואתחנן ע' קפו ואילך. סה\"מ תרל\"ב ח\"א ע' מב. וש\"נ. ועוד."]]],[2002180183,"<h3>ואתחנן כו'</h3>\n<b></b><b>בס\"ד. (ש\"פ ואתחנן, ט\"ל).</b>\n<b></b>ברכות המצות כו' אני ראשון כו' מצות וארץ כו' אי לך ארץ - ג\"פ קיצורים\nואתחנן\n<b>ואתחנן</b><sup data-n=\"423\">1</sup> אל הוי', אעברה נא ואראה את הארץ הטובה כו', וארז\"ל שהתפלל משה תקט\"ו תפלות כמנין ואתחנן שיכנס לא\"י, והקשו בגמ' וכי לאכול מפרי' הי' צריך אלא לקיים מצות התלויות בה. והנה באמת כל עיקר המצות תלויות בארץ דוקא<sup data-n=\"424\">2</sup> ואפי' מצות שהן חובת הגוף ונוהגות גם בחו\"ל, כתי' ג\"כ לעשות בארץ כמו ק\"ש שהיא חובת הגוף ונוהגת בכ\"מ כתיב בה וזאת המצוה כו' לעשות בארץ<sup data-n=\"425\">3</sup>, וצ\"ל שייכות ענין מצות לארץ דוקא.\n<b>אך</b> הנה מתחלה צ\"ל ענין מהות המצוה, דהנה כתיב סוף דבר הכל נשמע<sup data-n=\"426\">4</sup> את האלקים ירא ואת מצותיו שמור כי זה כל האדם כו'. ולהבין כ\"ז צ\"ל ענין ברכות המצות, דהנה מברכים קודם כל מצוה ברוך אתה הוי' אמ\"ה אשר קדשנו במצותיו כו', דהנה פי' מלך העולם שהתהוות כל העולמות הוא מבחי' מל' כמ\"ש מלכותך מלכות כל עולמים דהיינו רק במח' אחת מה שעלה במח' אנא אמלוך<sup data-n=\"427\">5</sup> מזה נתהוו כל העולמות, ונק' רק בשם לבוש כמ\"ש ה' מלך גאות לבש, ואף גם בחי' מח' דאנא אמלוך הוא ג\"כ בחי' לבוש כידוע שאותיות המח' הם רק בחי' לבושים ומבחי' זו נתהוו כל העולמות, וזהו עולם ל' העלם<sup data-n=\"428\">6</sup> שנעלם ומוסתר עצמותו ואינו מאיר רק בחי' מלך בחי' לבוש כו'. ובענין לבוש המח' י\"ל שמלבד שהמח' היא לבוש שענין הלבוש הוא מעלים ומכסה על הלבוש<sup data-n=\"429\">7</sup> בו, וא\"כ לבוש גיאות דמלוכה מעלים על אוא\"ס המלובש בו, הנה לבוש המחשבה הוא לבוש שהוא בהעלם והסתר מזולתו ג\"כ, שהרי כשיראה האדם שחבירו חושב דבר מה הנה הוא מבין רק שחושב אבל",[["423","1","<b>ואתחנן אל ה'</b>: הוא ד\"ה זה הנדפס בסה\"מ תרל\"ד ע' רפד ואילך, וכאן הוא בחלוקה לפרקים ובתוס' קיצורים ואיזה הגהות [ולהלן במ\"מ נסמנו ההגהות שניתוספו כאן]. המאמר מיוסד על ד\"ה זה באוה\"ת ואתחנן ע' קלג ואילך. ונמצא בהרחב הביאור בסה\"מ עטר\"ת ע' תקעא ואילך."],["424","2","<b>כל עיקר המצות תלויות בארץ דוקא</b>: ראה רמב\"ן אחרי יח, כה: ”כי עיקר כל המצות ליושבים בעדת ה' [ומביא שם מספרי עקב יא, יז: אע\"פ שאני מגלה כו' היו מצויינים]. וברמב\"ן ואתחנן ד, ה: ”שעיקר המצוות כולן בארץ\". ובלקו\"ת שלח מג, ד: כי המצות מעשיות שנוהגין בחו\"ל אינם אלא בערך חמישית מרמ\"ח מצות וארבע הידות אינו נוהג כ\"א בא\"י דוקא. וראה גם ס' מאמרי אדהאמ\"צ במדבר ח\"ג ע' תתקצא, ובהנסמן במילואים להמ\"מ שם ע' א'רעט. סה\"מ תרכ\"ז ע' שעט. וש\"נ."],["425","3","<b>כמו ק\"ש . . כתיב בה וזאת המצוה כו' לעשות בארץ</b>: ראה ג\"כ לקו\"ת ואתחנן ט, א."],["426","4","<b>אך הנה מתחלה צ\"ל . . דהנה כתיב סוף דבר הכל נשמע</b>: מכאן עד סוף ס\"א מיוסד על לקו\"ת מטות פא, א."],["427","5","<b>מה שעלה במח' אנא אמלוך</b>: ראה גם לקו\"ת נשא כא, ד ובהמ\"מ לשם. דרמ\"צ קע, סע\"ב. ובכ\"מ."],["428","6","<b>וזהו עולם ל' העלם</b>: ראה לקו\"ת במדבר ה, סע\"ג (ע\"פ קה\"ר ג, יא). שם שלח לז, ד. ביאוה\"ז להצ\"צ ח\"א ע' שנה (ע\"פ פסחים נ, א). וראה גם ת\"ז תמ\"ב. סידור האריז\"ל במוסף לר\"ה (היום הרת עולם). כתר שם טוב סכ\"ד. לקו\"ש חל\"ד ע' 112. ובכ\"מ."],["429","7","<b>ובענין לבוש המח' י\"ל שמלבד שהמח' הוא לבוש</b>: פיסקא זו (עד: לבוש זה עצמו הוא ג\"כ בבחי' העלם) הוא הוספה בגוכי\"ק בס' תרל\"ט."]]],[2002180184,"מה שחושב נעלם ממנו, א\"כ לבוש המח' משונה משארי לבושי', שבשארי לבושים אם היות שהם מסתירים על הלבוש בו, עכ\"ז הלבוש נראה ונגלה עכ\"פ, אבל לבוש המח' הנה לבוש זה עצמו הוא ג\"כ בבחי' העלם. אבל אשר קדשנו במצותיו כו' היינו שע\"י המצות ממשיכים מבחי' קדש העליון מה שהוא קדוש ומובדל דהיינו כמ\"ש אני ראשון ואני אחרון ומבלעדי אין אלקים<sup data-n=\"430\">8</sup>, פי' אני ראשון היינו כמו שהי' קודם שנבה\"ע שהי' אוא\"ס ממלא כל החלל וכמ\"ש בפדר\"א עד שלא נבה\"ע הי' הוא ושמו בלבד, ואני אחרון היינו לאחר שיכלו כל העולמות כי קיום כל העולמות הם בגבול נ' אלפים יובלות<sup data-n=\"431\">9</sup> ואח\"כ יהי' הארת עצמותו, ומבלעדי אין אלקים היינו באמצעיתא עכשיו שנבראו עולמות ג\"כ אין אלקים קמי', פי' כי שרש כל העולמות הוא מבחי' שם אלקים המסתיר על עצמותו כי מבחי' עצמות אוא\"ס לא הי' באפשרי להיות שמים וארץ גשמי', וכמו לע\"ל שיהי' התגלות עצמות אוא\"ס כתי' כאשר השמים החדשים כו' אשר אני עושה, היינו מחמת שאני עושה התגלות עצמות אוא\"ס לא יהי' באפשרי להוות שמים וארץ גשמי' כ\"א שמים חדשים כו', ושרש שמים וארץ גשמי' הוא רק מבחי' אלקים שמסתיר ומעלים על עצמותו. והנה ההסתר דבחי' אלקים אינו אלא רק לפנינו<sup data-n=\"432\">10</sup> אבל קמי' גם ההסתר אינו הסתר, לפי שבחי' ההסתר דש' אלקים נמשך ג\"כ מעצמותו וכמ\"ש אכן אתה אל מסתתר, הוי' הוא האלקים, שהוי' הוא עצמו האלקים והצמצום שנתצמצם להיות עולמות נפרדים בע\"ג כהדין קמצא דלבושי' מיני' ובי'<sup data-n=\"433\">11</sup>, וזהו ומבלעדי אין אלקים.\n<span data-k=\"ks\"><b>קיצור.</b> בכדי להבין שייכות ענין המצות לארץ, צ\"ל נוסח הברכה בא\"ה אמ\"ה אקב\"ו, מלך העולם ששרש העולמות הוא ממ' דאנא אמלוך שהיא ג\"כ לבוש כמ\"ש ה' מלך גיאות לבש, ולכן עולם ל' העלם שגם מח' היא מעלמת על הלובשה, וגם בהעלם מזולתו, אבל ע\"י המצות ממשיכים ממה שהוא קדוש ומובדל היינו בחי' אני ראשון שקודם ההשתלשלות ואני אחרון לאחר נו\"ן אלפים יובלות, ומבלעדי באמצעיתא ג\"כ קמי' אין אלקי', כי אתה הוא אל מסתתר, והוי' עצמו הוא האלקי' כו'.</span>\nב) <b>והנה</b> ע\"י המצות ממשיכים מבחי' זו, דהיינו מבחי' אני ראשון שיאיר למטה כמו למעלה, וכמ\"ש במצוה ראשונה שנצטוו במצרים החדש הזה לכם ראשון",[["430","8","<b>כמ\"ש אני ראשון ואני אחרון ומבלעדי אין אלקים</b>: ראה ג\"כ בכ\"ז: סה\"מ תרכ\"ז ע' שה. שטו. תרכ\"ט ע' רעו ואילך. לעיל ד\"ה שמע ישראל. ובכ\"מ."],["431","9","<b>כי קיום כל העולמות הם בגבול נ' אלפים יובלות</b>: ראה סה\"מ תקס\"ב ח\"ב ע' תסב (ובהמ\"מ שם). תקס\"ט ע' פג (מס' התמונה). ס' מאמרי אדהאמ\"צ דברים ח\"א ע' רסח (ובהמ\"מ). עטרת ראש סז, ב. אוה\"ת ר\"ה ס\"ע א'רפח (ע\"ש בשם הבחיי פ' בהר). סה\"מ תרע\"ח ריש ע' דש (מס' התמונה, ע\"ש)."],["432","10","<b>והנה ההסתר דבחי' אלקים אינו אלא רק לפנינו</b>: ראה גם לקו\"ת שה\"ש א, א. ובאוה\"ת ואתחנן ס\"ע קלג. וש\"נ."],["433","11","<b>כהדין קמצא דלבושי' מיני' ובי'</b>: ראה תניא ספכ\"א. לקו\"ת ויקרא הוספות נג, א ואילך. שלח מג, ג. סה\"מ תרכ\"ז ע' שנ ואילך. תרכ\"ט ע' שעג."]]],[2002180185,"הוא לכם כו', פי' שע\"י המצוה נמשך לכם בחי' ראשון, וכן בשאר המצות כתי' ג\"כ ראשון וכמ\"ש ולקחתם לכם ביום הראשון, ביום הראשון מקרא קדש, וזהו ראשון לציון הנה הנם. וזהו נעשה אדם בצלמנו כדמותנו, והנה צלמנו הוא בחי' תורה, וכדמותנו הוא בחי' מצות, וע\"ז כתי' ראשון לציון שע\"י ציון שהוא בחי' מצות עי\"ז נמשך בחי' ראשון אני ראשון. וזהו אשר קדשנו במצותיו דהיינו שמתחלה נמשך במצותיו כי פי' מצותיו הוא כמ\"ש הקב\"ה מניח תפילין ומתעטף בציצית<sup data-n=\"434\">12</sup>, וכן שבת להוי', ופי' תפילין שלמעלה היינו כי תפילין הוא ד' בתים דהיינו ד' מוחין, קדש והי' חו\"ב, שמע והי' חו\"ג, ופי' הקב\"ה מניח תפילין היינו שיהי' התחברות אוא\"ס בבחי' חו\"ב אשר אין ערוך אליו כמ\"ש כולם בחכ' עשית, שהחכ' נחשבת כעשי' גופניות נגדו ית'<sup data-n=\"435\">13</sup>, וז\"ע מה שהקב\"ה מניח תפילין שנתחבר ונמשך בבחי' חכ' ומדות ולכן כותבן בתפילין בדיו על קלף לבן כי הקלף מורה על בחי' לבושי' כתלג חיור והאותיות הוא בחי' ושער רישי' כעמר נקי, וכן ציצית הם ל\"ב חוטין שהוא המשכת אוא\"ס בבחי' ל\"ב נ\"ח<sup data-n=\"436\">14</sup>. אך מי הוא המעורר להיות הקב\"ה מניח תפילין, זהו ע\"י וצונו במעשה המצות גשמי', כמו לכתוב על קלף גשמי אחד שעושין הקלף כלי לבחי' אחד, וכמ\"ש במ\"א בפי' המד\"ר שמה שהוא עושה זהו ע\"י שאומר לישראל לעשות<sup data-n=\"437\">15</sup>. אך שיעשה אותם בבחי' ביטול שלזה ארז\"ל הוקשה כל התורה לתפילין דהיינו כמו תפילין הם לשעבד הלב ומוח לאבינו שבשמים בבחי' ביטול, וכן קרבנות הוא ג\"כ בחי' ביטול שנכלל הבהמה גשמי' באש של מעלה, וכן צדקה הוא נותן חיי נפשו לחבירו<sup data-n=\"438\">16</sup>, וע\"י ביטול זה שמבטל א\"ע בעשיית המצוה עי\"ז מעורר למעלה שיומשך אוא\"ס בע\"ס עליונות, וכמארז\"ל גדולים מעשה צדיקים<sup data-n=\"439\">17</sup> ממעשה שמים וארץ, דאילו שמים וארץ מאין ליש, אבל מעשה הצדיקים מיש לאין דהיינו ביטול היש. וכן בתורה כתיב ודברי אשר שמתי בפיך דוקא, שלא יהי' הדבור שלו רק שיהי' דברי ממש, והדבור של האדם לא יהי' רק כמ\"ש תען לשוני כעונה אחר הקורא. וזהו מ\"ש לכו לחמו בלחמי, תומ\"צ נק' בחי' לחם דהיינו כמו שלחם גשמי מחי' את האדם דהיינו מוצא פי הוי' שיש בלחם וכמ\"ש כי לא על הלחם לבדו כו' כי על כל מוצא פי הוי'",[["434","12","<b>הקב\"ה מניח תפילין ומתעטף בציצית</b>: ראה ס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תסז. במדבר ח\"ד ע' א'רצב. א'שיב. דברים ח\"א ע' סד. אוה\"ת ואתחנן ע' קלד. וש\"נ."],["435","13","<b>כמ\"ש כולם בחכ' עשית שהחכ' נחשבת כעשי' גופניות נגדו ית'</b>: ראה תניא פ\"ב בהגה\"ה. שער היחוד והאמונה ספ\"ט בהגה\"ה."],["436","14","<b>וכן ציצית הם ל\"ב חוטין שהוא המשכת אוא\"ס בבחי' ל\"ב נ\"ח</b>: ראה לקו\"ת שלח לז, א. מז, ב. מט, ב. נא, ב. ס' מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקטז [ובהמ\"מ שם]."],["437","15","<b>וכמ\"ש במ\"א בפי' המד\"ר שמה שהוא עושה זהו ע\"י שאומר לישראל לעשות</b>: שורה זו ניתוספה כאן בגוכי\"ק בס' תרל\"ט. וראה סה\"מ תרכ\"ח ע' פז ואילך. תרכ\"ט ע' רכג. תרל\"ב ח\"ב ע' פד. תרל\"ד ע' נג."],["438","16","<b>צדקה הוא נותן חיי נפשו לחבירו</b>: ראה תניא פל\"ז (מח, ב). תו\"א וישב כט, ד. לקו\"ת שה\"ש ו, ד."],["439","17","<b>וכמארז\"ל גדולים מעשה צדיקים</b>: ראה ג\"כ תו\"א בשלח סו, סע\"ב. לקו\"ת נשא כא, סע\"ב ואילך. ס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תתי. סה\"מ תרכ\"ז ע' רנה. תרל\"ג ח\"א ע' רסח. ח\"ב ע' תל ואילך. וש\"נ."]]],[2002180186,"יחי' האדם<sup data-n=\"440\">18</sup>, ולכאורה צ\"ל הלא באדם ישנו ג\"כ בחי' מוצא פי הוי' מאמר נעשה אדם כו', אלא דהנה ידוע ששרש דצ\"ח שרשם גבוה מבחי' אדם רק שנפלו בשה\"כ ולכן כאשר האדם מברר אותן הם מחי' את האדם, כן התו\"מ שרשם גבוה מאד כי תר\"ך מצות הם תר\"ך עמודי אור בחי' כתר<sup data-n=\"441\">19</sup> רק שנתלבשו בדברים גשמי' וצריך האדם לברר אותן ועי\"ז שמקיים אותן בבחי' ביטול עי\"ז נמשך גילוי אוא\"ס ב\"ה. אך עיקרה של המצוה הוא הכוונה, כמשארז\"ל מצות בלא כוונה כגוף בלא נשמה<sup data-n=\"442\">20</sup>, שע\"י הכוונה נעשה כלי להמשיך ע\"י גילוי אלקות, ולזה נתקן ענין התפלה שהתפלה היא הרצוא לאלקו', ולזה נק' התפלה סולם<sup data-n=\"443\">21</sup> מוצב ארצה וראשו מגיע השמימה שזהו ענין הרצוא, ואח\"כ יוכל להיות מלאכי אלקים עולים ויורדים בו דהיינו המשכת אלקות ע\"י מצות. וזהו מ\"ש וזאת המצוה ואח\"כ א' שמע ישראל לבד, לפי שק\"ש היא כללות כל המצות<sup data-n=\"444\">22</sup>, לפי שק\"ש היא תחלה בחי' רצוא למס\"נ באחד<sup data-n=\"445\">23</sup>, ואח\"כ כתיב ואהבת בכל מאדך שהוא ענין ביטול היש לאין, ואח\"כ כתיב והיו הדברים האלה וקשרתם שהוא מעשה המצות.\n<span data-k=\"ks\"><b>קיצור.</b> שע\"י המצות ממשיכי' מבחי' ראשון, כמ\"ש ראשון לציון שע\"י ציון מעשה המצות ממשיכי' בחי' אני ראשון, וסדר ההמשכה הוא ע\"י בחי' מצותיו הקב\"ה מניח תפילין שנמשך במוחין חב\"ד, והוא ע\"י וצונו שמה שהוא עושה זהו ע\"י שאומר לישראל לעשות, אך העשייה צ\"ל בבחי' ביטול, כי הוקשה כו' לתפילין שהם לשעבד הלב והמוח, וזהו גדולי' מעשי צדיקים ממעשה שמים וארץ, וזהו לכו לחמי בלחמי שכמו הלחם בשרשו גבוה יותר רק שנפל בשה\"כ וצריכי' להגביהו ואז מוסיף חיות באדם דתיקון גם ברוחניות כמשנ\"ת בד\"ה וידבר משה אל ראשי המטות<sup data-n=\"446\">24</sup>, כן מצות שרשם בכתר ונשפלו בדברי' גשמיים וצריכין להעלותם ואז הם כמשל הלחם שמחי' כו', והעיקר הוא הכוונה וז\"ע תפילה סולם דא צלותא ומלאכי אלקי' הם מעהמ\"צ שהם שלוחי' כמ\"ש במד\"ת פ' ויגש הוי זהירי' במצות שהם שלוחי ושלוחו של אדם כמותו, ולכן על ק\"ש שהיא רצוא נא' וזאת המצוה להיותה כוונת כל המצות.</span>",[["440","18","<b>כי לא על הלחם לבדו כו' כי על כל מוצא פי הוי' יחי' האדם</b>: ראה לקו\"ת להאריז\"ל פ' עקב. פע\"ח שכ\"ז פ\"א. ס' הליקוטים להאריז\"ל בתחילתו. של\"ה עד, א (ועוד). תו\"א נח ט, ד. בשלח סה, ד. לקו\"ת צו יג, ב. מטות פא, ב ואילך. [וראה הנסמן להלן בפנים המאמר בהקיצור]. עקב יד, א ואילך. סידור עם דא\"ח קז, ב-ג. ובכ\"מ."],["441","19","<b>כי תר\"ך מצות הם תר\"ך עמודי אור בחי' כתר</b>: ראה תיקוני זהר חדש צו, ד. פרדס ש\"ח פ\"ג. לקו\"ת להאריז\"ל משלי (עה\"פ באבוד רשעים רנה). תניא אגה\"ק סכ\"ט (קנ, א). ובכ\"מ."],["442","20","<b>כמשארז\"ל מצות בלא כוונה כגוף בלא נשמה</b>: ראה של\"ה רמט, ב. תניא פל\"ח (נ, א ואילך). תו\"א בראשית ל, א. לקו\"ת אחרי כה, ד. וראה סה\"מ תרל\"ג ח\"א ע' לג. קכג. ח\"ב ע' תקלד. ובכ\"מ."],["443","21","<b>ולזה נק' התפילה סולם</b>: ראה גם תו\"א בראשית ב, ב. ויקהל פח, א ואילך. לקו\"ת בשלח ב, ב ואילך. נשא כו, ב ואילך. ועוד."],["444","22","<b>לפי שק\"ש הוא כללות כל המצות</b>: ראה גם סה\"מ תקס\"ז ע' שה. שערי תשובה לאדהאמ\"צ מא, א. אמרי בינה שער הק\"ש פ\"צ. ס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תקסט. סה\"מ תרכ\"ט ע' רכא. סה\"מ תרל\"ג ח\"א ע' קמב. ח\"ב ע' שסז. תפ ואילך."],["445","23","<b>למס\"נ באחד</b>: ראה זח\"ב קיט, א. זח\"ג לג, א. פע\"ח שער הק\"ש פי\"ב. ב\"ח או\"ח ר\"ס ס\"א. אוה\"ת תרומה ע' א'שסז. סה\"מ תרס\"ד ע' קצא."],["446","24","<b>כמשנ\"ת בד\"ה וידבר משה אל ראשי המטות</b>: ראה לעיל המאמר שלפני זה. ובלקו\"ת מטות פא, ב ואילך."]]],[2002180187,"ג) <b>ומעתה</b> י\"ל שייכות ענין המצות לארץ דוקא, הנה כתי' אי לך ארץ שמלכך נער, אשריך ארץ שמלכך בן חורין, ופי' בזוה\"ק<sup data-n=\"447\">25</sup> מלכך נער דא מט\"ט היינו דכתיב נער הייתי גם זקנתי שרו של עולם אמרו, מלכך בן חורין דא קוב\"ה. והנה החילוק שבין נער לגדול היינו שבנער הוא הכל בקטנות כי כל מה שיש בגדול ישנו ג\"כ בקטן רק שהוא בקטנות, וזהו אי לך ארץ שמלכך נער היינו כשההשפעה נמשך בבחי' קטנות וצמצום עד שיכול לומר כחי ועוצם ידי עשה לי כו', ובאמת כתיב וברכך ה' אלקיך בכל אשר תעשה שהכל נמשך מאתו ית', שהוא הוא הנותן לך כח לעשות חיל, רק ע\"י שנמשך ההשפעה ומתלבשת בע' שרים אינו רואה הכח אלקי שמלובש שם, וזהו בחי' נער, וזהו שרו של עולם אמרו עולם ל' העלם שמעלים ומסתיר על כח אלקי שמלובש שם. אבל מלכך בן חורין היינו כשיש גילוי אלקות כמו שהי' בשעת יצ\"מ וקרי\"ס ומ\"ת, וכן כל זמן בהמ\"ק שהי' גילוי אלקות ממש, וזהו בן חורין דא קוב\"ה שמאיר למטה כמו למעלה ואינו מתלבש ומתעלם בלבושים דע' שרים כו'. וזהו מ\"ש ונהר יוצא מעדן מה שמו דההוא נהר יובל שמו, יובל הוא עלמא דחירו, והיינו כי בעדן מאיר גילוי אלקות ע\"כ נק' בשם יובל שהוא בחי' חורין. אך אימתי מלכך בן חורין, זהו כשיש העלא' מלמטלמ\"ע בבחי' תו\"מ, וז\"ש אצל ומלכך בן חורין ושריך בעת יאכלו, דהנה פי' עת ר\"ת עולת תמיד<sup data-n=\"448\">26</sup> דהיינו כשיש אתעדל\"ת ע\"י קרבנות וכה\"ג עי\"ז נמשך ממקום גבוה בלי הסתרים וצמצומים, אבל כששריך בבקר יאכלו, בקר הוא בחי' חסד שהוא אתעדל\"ע בלי אתעדל\"ת ע\"ד שארז\"ל ך\"ו דורות מאדם עד מ\"ת היו ניזונים בחסדו של הקב\"ה, ולזה א' דוד ך\"ו כל\"ח נגד ך\"ו דורות הללו דהיינו שלא הי' בהם אתעדל\"ת כלל רק אתעדל\"ע מעצמו ולזה אינו נמשך ממקום גבוה כ\"כ, וגם זה בלבושים וצמצומים ע\"י ע' שרים.\n<b>וזהו</b> ענין שייכות המצות לארץ דוקא, כי ארץ היא בחי' רצוא, למה נק' שמה ארץ שרצתה לעשות רצון קונה<sup data-n=\"449\">27</sup>, והיינו כשהמצות הם בבחי' גדלות היינו ברעו\"ד אזי ההמשכה מלמעלה ג\"כ בבחי' גדלות מלכך בן חורין, אבל בחו\"ל כשהמצות נעשים בבחי' קטנות וכמ\"ש הדודאים נתנו ריח<sup data-n=\"450\">28</sup>, כי יש דודים ודודאים, דודים הוא בחי' גדלות ודודאים בחי' קטנות, אזי ההמשכה מלמעלה ג\"כ בבחי' קטנות בחי' נער. וכמ\"ש ועשה כרוב אחד כו', דהיינו כשההעלא' מלמטלמ\"ע בבחי' כרוב אפי זוטרי ההמשכה מלמעלמ\"ט ג\"כ בחי' כרוב בחי' קטנות. ולזה ביקש משה שיכנס",[["447","25","<b>הנה כתיב אי לך ארץ שמלכך נער . . ופי' בזוה\"ק</b>: זח\"א צה, ב. הובא גם בלקו\"ת בחוקותי נ, ב. סה\"מ תרל\"ג ח\"א ע' לט. סה\"מ פר\"ת ע' ס. ובכ\"מ."],["448","26","<b>דהנה פי' עת ר\"ת עולת תמיד</b>: ראה גם סה\"מ פר\"ת ע' סא."],["449","27","<b>למה נק' שמה ארץ שרצתה לעשות רצון קונה</b>: ראה ס' מאמרי אדהאמ\"צ במדבר ח\"א ע' צה ובהמילואים להמ\"מ לשם (ריש ע' שה)."],["450","28","<b>כשהמצות נעשים בבחי' קטנות וכמ\"ש הדודאים נתנו ריח</b>: ראה אוה\"ת מטות ע' א'שמא. ואתחנן ע' קלא. סה\"מ תרל\"ג ח\"א ע' מא ואילך."]]],[2002180188,"לארץ דוקא, כי בארץ ההמשכה שע\"י המצות הוא ממקום גבוה יותר. והנה ע\"י התורה נמשך ג\"כ מבחי' גדלות כמו בארץ, וכמ\"ש נער הייתי גם זקנתי, שבבחי' נער נמשך ג\"כ מבחי' זקנתי זקן שקנה חכ', וכמו שמצינו בראב\"ע<sup data-n=\"453\">29</sup> שנעשה נשיא בן י\"ח שנה אתרחיש ניסא ונעשה אצלו תמני סרי דרי חיורתא קרי על עצמו נער הייתי גם זקנתי, והיינו שע\"י תורה נמשך מבחי' ועת\"י יתיב בחי' כתר, וע\"כ כתיב בתורה חרות על הלוחות א\"ת חרות אלא חירות שאין לך בן חורין אלא מי שעוסק בתורה, לפי שע\"י תורה נמשך מבחי' מלכך בן חורין שיהי' ההמשכה בבחי' גילוי. ולזה נק' תושבע\"פ בשם ארץ<sup data-n=\"454\">30</sup> לפי שעיקר גילוי הרצון הוא בתושבע\"פ, כי בתושב\"כ אינו מבואר כל מצוה איך לעשותה כמו בתפילין אינו ידוע איך לעשותם מרובעים או עיגולים רק בתושבע\"פ נת' כל מצוה, וא\"כ עיקר גילוי הרצון הוא בתושבע\"פ, וע\"כ כמו שארץ נק' ארץ טובה כך תורה נק' ג\"כ טוב כמ\"ש כי לקח טוב נתתי לכם. וזהו גדול תלמוד שמביא לידי מעשה, שמה שע\"י מעשה נמשך בחי' גדלות מבחי' מלכך בן חורין הוא ע\"י תורה.\n<b>אך</b> א\"כ צ\"ל למה ביקש משה שיכנס לארץ דוקא אם ע\"י תורה נמשך גם בחו\"ל כמו בארץ ומשה קיבל את כל התורה כולה. אך הענין הוא דהנה יש עולם שנה ונפש<sup data-n=\"455\">31</sup>, והנה מה שע\"י התורה נמשך מבחי' גדלות הוא רק בבחי' נפש, אבל בעולם הגילוי הוא רק בבחי' קטנות בבחי' טבע, אבל משה רצה שיומשך הגילוי למטה בארץ כמו למעלה, כמו שיהי' לע\"ל שלמטה בארץ הגשמי יהי' גילוי אוא\"ס כמו למעלה, ולזה רצה ליכנס לא\"י דוקא. וזהו מ\"ש סוף דבר הכל נשמע כי זה כל האדם, זה הוא התגלות וכמ\"ש משה נתנבא בזה, כי כה הוא בחי' דמות שאינו עצם הדבר אספקלרי' דלא נהרא, והנה עיקר החילוק שבין כה לזה<sup data-n=\"456\">32</sup>, כה הוא בחי' שמיעה וכמ\"ש ואשמע את קול ה', אבל זה הוא בחי' ראי' וכמ\"ש במשה וירא ראשית לו, וז\"ש ואת מצותיו שמור כי זה כל האדם שיהי' התגלות בחי' זה, וזהו כי זה כל האדם רמ\"ח אברים דמלכא כו'<sup data-n=\"451\">33</sup>. ולכן התפלל תקט\"ו תפלות, ת\"ק הם נגד ה\"מ<sup data-n=\"457\">34</sup> וכ\"א כלול מיו\"ד ויו\"ד מיו\"ד, ט\"ו הוא בחי' י\"ה בחי' מוחין וכאשר מאיר המוחין במדות אז",[["453","29","<b>וכמו שמצינו בראב\"ע</b>: ראה גם יהל אור להצ\"צ ס\"ע קמ."],["454","30","<b>ולזה נק' תושבע\"פ בשם ארץ</b>: ראה גם תו\"א בראשית א, ג. מקץ מ, ב. וארא נז, ד ואילך. לקו\"ת בחוקותי מט, א. שה\"ש נא, ב. אוה\"ת בראשית כרך ג' תפב, א. כרך ו' תתרכז, ב ואילך. בא ע' ערד-ה. נ\"ך ע' תרמז. לעיל ד\"ה חודש הזה לכם. ובכ\"מ."],["455","31","<b>דהנה יש עולם שנה נפש</b>: ראה אוה\"ת יתרו ע' תתטז. וש\"נ."],["456","32","<b>משה נתנבא בזה . . החילוק שבין כה לזה</b>: ראה בכ\"ז בארוכה לעיל בהמאמר שלפנ\"ז ד\"ה וידבר גו' ראשי המטות."],["451","33","<b>וכמ\"ש ועשה כרוב א' כו'</b>: ראה גם תו\"א תרומה פ, א-ב."],["457","34","<b>ולכן התפלל תקט\"ו תפלות ת\"ק הם נגד ה\"מ </b> [ ה' מדות]<b></b>: ראה גם אוה\"ת ואתחנן ס\"ע קיג ואילך [ושם ע' קטז ד\"ה עוי\"ל ע\"ד הביאור כאן]. שם כרך ו' ע' ב'תקצג ואילך. ס' מאמרי אדמו\"ר הצ\"צ הנחות — תרט\"ו ע' קנו. קסא. רעג. סה\"מ תרכ\"ט ע' מ. תרל\"ג ח\"א ע' קמה. לקוטי שיחות ח\"ט ע' 70."]]],[2002180189,"נעשה זה שמאיר גילוי בעולמות ששרש העולמות הוא מבחי' מדות כמ\"ש ששת ימים עשה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ושייכות ענין המצות לארץ, כי יש הפרש גדול בין עשיית המצות ברעו\"ד שעי\"ז ממשיכין מבחי' ב\"ח ההשפעה שבבחי' גדלות, משא\"כ בח\"ל נמשך מבחי' נער קטנות, וזהו שאצל ב\"ח נאמר בעת יאכלו עת ר\"ת עולת תמיד היינו כשיש העלאה, משא\"כ אצל נער נא' בבקר בקר בחי' חסד אתעדל\"ע גם כשלא יש אתעדל\"ת שנמשך בצמצומי' כו', ולכן רצה משה לכנוס לארץ כי ארץ היא רצוא, ולכן שם קיום המצות הם באופן היותר נעלה, ולכן נא' לעשות בארץ גם במצות שהם חובת הגוף, והנה ע\"י התורה נמשך ג\"כ ע\"ד כמו בארץ<sup data-n=\"452\">35</sup>, ולכן במ\"ת נדמה להם כזקן, ותושבע\"פ נק' ארץ, וא\"כ למה רצה משה לכנוס לארץ הלא משה קיבל תורה מסיני, אך יש עש\"נ, ומה שנמשך ע\"י התורה זהו רק בנפש, אבל בעולם ושנה זמן ומקום נמשך ע\"פ הנהגת הטבע, אבל כשהי' נכנס לארץ הי' נמשך גם בזמן ומקום ג\"כ, וזהו כי זה כל האדם זה הוא בחי' גילוי נתנבא בזה אה\"מ<sup data-n=\"458\">36</sup>, ולכן התפלל ת\"ק נגד מדות ט\"ו י\"ה שיומשך המוחין במדות וממילא נמשך מלמעלה מן המוחין בכלליות ע\"ס כו'.</span>",[["452","35","<b>והנה ע\"י התורה נמשך . . גדלות כמו בארץ</b>: בהבא לקמן ראה גם אוה\"ת ואתחנן ע' שיד: עצה בחו\"ל להמשיך בחי' ארץ כו' עיי\"ש."],["458","36","<b>אה\"מ</b>: אספקליא המאירה."]]],[2002180190,"<h3>ושננתם כו'</h3>\n<b></b><b>בס\"ד. (ש\"פ עקב, ט\"ל).</b>\n<b></b>תלמוד או מעשה גדול כו' ושננתם ב' פי' כו' ויתר ולא ויתר כו' ודברת ובקומך כו' שינה כו' לע\"ל מעשה גדול כו' גדול תלמוד - יב\"פ. קיצורים\nעקב\n<b>ושננתם</b> לבניך<sup data-n=\"459\">1</sup> ודברת בם בשבתך בביתך כו' וקשרתם לאות על ידיך כו', הנה בפ' ראשונה נאמר תחלה ושננתם שהוא תלמוד תורה ואח\"כ בחי' מצות שהוקשה כל התורה לתפילין כו', ובפ' שני' נא' תחלה וקשרתם אותם לאות על ידכם שהוא בחי' מצות ואח\"כ ולמדתם אותם את בניכם כו'. והענין הוא דהנה יש פלוגתא בגמ' אם תלמוד גדול או מעשה גדול, ונמנו וגמרו תלמוד גדול מפני שמביא לידי מעשה, אך הנה כ\"ז הוא עתה שעכשיו תלמוד גדול מטעם הנ\"ל, אבל לע\"ל יהי'",[["459","1","<b>ושננתם לבניך</b>: מאמר זה (והמאמרים שלאחריו) מיוסד והגהות על ד\"ה זה מהצ\"צ שנמצא בכת\"י הנחות 466 רמה, א. וראה תוכן המאמר [רפ\"א, ופרקים ב-ה, י-יב) בשינויים בד\"ה ושננתם: בסה\"מ תקס\"ז ע' דש. אמרי בינה שער הק\"ש פ\"צ-צה. אוה\"ת ואתחנן ע' רלח (והמאמרים שלאחריו). שם (כרך ה) ע' ב'ט (והמאמרים שלאחריו). שם (כרך ו) ע' ב'ערב (והמאמרים שלאחריו). סה\"מ תרל\"ו ח\"ב ע' רפד-שג. תקלב ואילך. תקס ואילך. סה\"מ תרל\"ג ח\"ב ע' תעח ואילך. וש\"נ. תרל\"ד ע' פז ואילך. וראה גם סה\"מ תרכ\"ט ע' כד. תרל\"ג ח\"א ע' רסו.\nלחלק מהמאמר (ספ\"א, והפרקים ה-ח) ראה ד\"ה ושננתם באוה\"ת ואתחנן ע' שי ואילך. לפרק ט ראה ד\"ה כרע שכב באוה\"ת בלק ע' א'מה. וע' א'מח."]]],[2002180191,"מעשה גדול<sup data-n=\"460\">2</sup> כו'. ולכן בפ' ראשונה נא' מתחלה תלמוד ואח\"כ בחי' מעשה כמו שהוא עכשיו, אבל בפ' שני' שהוא קאי על לע\"ל<sup data-n=\"461\">3</sup> נא' מתחלה מעשה ואח\"כ תלמוד.\n<b>ולהבין</b> כ\"ז היטב י\"ל מתחלה הפי' של תיבת ושננתם, דהנה הפי' הפשוט הוא ושננתם הוא לשון לימוד לשון משנה, והב' הוא לשון חץ שנון<sup data-n=\"462\">4</sup> שהוא לשון חידוד וכמשארז\"ל ע\"פ זה שיהיו ד\"ת מחודדין בפיך כו', והיינו שיהיו ד\"ת בבחי' חידוד ופלפול.\n<b>וזהו</b> מ\"ש ברזל בברזל יחד ואיש יחד פני רעהו<sup data-n=\"463\">5</sup> כו' (משלי ך\"ז י\"ז), והנה פי' ברזל בברזל, דהנה כתי' ארץ אשר אבניה ברזל וארז\"ל א\"ת אבני' אלא בוני' שהוא ענין ת\"ח שעוסקי' בבנינו של עולם וכמשארז\"ל ת\"ח מרבים שלום בעולם שנא' וכל בניך למודי הוי' ורב שלום בניך א\"ת בניך אלא בוניך כו', וזהו פי' ברזל בברזל יחד שצ\"ל דוקא שיהיו שני ת\"ח עוסקי' בהלכה לפי שהם מחדדין זה את זה, לפי שאינו דומה שנים שעוסקים בתורה לאחד וכמשארז\"ל שנים שיושבין ועוסקים בתורה שכינה שרוי' ביניהם שנא' אז נדברו יראי הוי' איש אל רעהו ויקשב וישמע, ומנין אפי' אחד שיושב ועוסק בתו' שהקב\"ה קובע לו שכר שנא' ישב בדד וידום כו', נמצא שאינו דומה אחד העוסק בתורה לשנים העוסקים בתורה שבאחד אינו רק שהוא קובע לו שכר, משא\"כ שנים שכינה שרוי' ביניהם וכמ\"ש מזה באג\"ה סי' ך\"ג ע\"ש, וזהו ברזל בברזל יחד דוקא.\n<span data-k=\"ks\"><b>קיצור.</b> בפ' ראשונה נא' תו' תחילה כדעת מ\"ד תלמוד גדול, ובפ' שני' שמדבר לע\"ל נא' מצות תחילה כמ\"ד מעשה גדול, ויובן בהקדם פי' ושננתם הא' ל' לימוד הב' ל' שינון, וכענין ברזל בברזל, אבני' ברזל בוני' ת\"ח כי שנים דוקא שעוסקי' שכינה שרוי' ביניהם, משא\"כ אחד רק קובע לו שכר, וכמ\"ש ההפרש באגה\"ק סי' ך\"ג, שקביעת שכר זהו מה שנתלבש בלבוש מעטה תורתו לפי ערכו, אבל שכינה שרוי' זהו כמעלת אכל בי' עשרה שכינתי' שרי' בבחי' מקיף מה שא\"א להתצמצם באו\"פ כו'.</span>",[["460","2","<b>אבל לע\"ל יהי' מעשה גדול</b>: ראה מאמרי אדה\"ז תקס\"ז שם ע' שט ואילך. שיז ואילך. אוה\"ת בראשית מ, ב. ויגש שמח, ב. שם (כרך ה) תתקפה, א. אוה\"ת ואתחנן שם ס\"ע רמז ואילך. ערה ואילך. סה\"מ תרכ\"ט שם ע' כד. תרע\"ח ע' קכד ואילך. תרצ\"ט ע' 193 ואילך. סה\"מ מלוקט ח\"ב ע' רכג. ח\"ד ע' קיא. וע' קיט. לקו\"ש חכ\"ה ע' 263 ואילך. ועוד."],["461","3","<b>אבל בפ' שני' שהוא קאי על לע\"ל</b>: בסה\"מ תקס\"ז שם (ע' שט, ועד\"ז באוה\"ת שם ע' רעו) מפרש כאן: דהנה משמעות פרשה זאת כי כל דברי הפרשה שאינם ענין ציווי ואזהרה כו' אלא ענין מדבר על העתיד דהיינו שעתיד להיות כך וכך וזהו והי' אם כו' עד וסרתם ועבדתם כו' דר\"ל שעתיד להיות כן כו'."],["462","4","<b>ולהבין כ\"ז היטב . . תיבת ושננתם . . לשון לימוד . . לשון חץ שנון</b>: בהבא לקמן ראה אוה\"ת ואתחנן שם ע' שי-יא."],["463","5","<b>וזהו מ\"ש ברז\"ל בברזל יחד ואיש יחד פני רעהו</b>: ראה בכ\"ז אוה\"ת ואתחנן שם ע' שי ואילך. וראה אוה\"ת תצוה ע' א'תשיז מציין: ועמ\"ש ע\"פ ושננתם לבניך בענין ברזל בברזל כו'. וראה גם אוה\"ת נ\"ך (כרך א) ע' תרלב-ג. סה\"מ תרנ\"ט ע' סא. ובהוספות ע' רטז."]]],[2002180192,"ב) <b>ולהבין</b> זה בתוס' ביאור י\"ל מקודם הפלוגתא בענין תלמוד גדול או מעשה גדול שאחד אמר תלמוד גדול ואחד אומר מעשה גדול, דהנה ענין ופי' של מעשה הוא ל' כפי' והכרח כמו מעשין על הצדקה<sup data-n=\"464\">6</sup>, גט המעושה כו', והיינו כי מעשה המצות הוא בבחי' כפי' והכרח לפי שהם שלא עפ\"י שכל וטעם, כי בדבר שהוא עפ\"י שכל אינו שייך ע\"ז לשון כפי' כיון שהשכל מורה ע\"ז, וכמו בלימוד התורה אינו שייך ע\"ז לשון כפי' לפי שהתורה היא בחי' שכל וחכ' וכמו וידבר ה' אל משה ויאמר ה' אל משה שיש בזה השכלה כו' וכ\"ש תושבע\"פ כל עיקרה היא בבחי' שכל וסברא כו' ע\"כ בלימוד התורה אינו שייך בחי' כפי' לפי שטבע האדם לעסוק בחכ' כו', משא\"כ מעשה המצות הם למעלה מן השכל וכמו למשל ניקבה הריאה שהיא טריפה אע\"פ שהבהמה בריאה ושמינה כמו שאר כל הבהמות אעפ\"כ כיון שיש נקב משהו בריאה היא טריפה, וכן כל המצות הם למעלה מן השכל כמו לבישת שעטנז ואכילת חזיר כו', וע\"כ שייך ע\"ז בחי' כפי' והכרח שאעפ\"י שאין זה עפ\"י שכל מ\"מ הוא עושה זה מחמת שכך הוא רצה\"ע. וזהו שמעשה המצות נק' עבודת עבד לפי שעושה בבחי' קבלת עול בלי טעם כלל. וזהו שארז\"ל אל יאמר אדם אי אפשי לאכול בשר חזיר אלא אפשי אבל מה אעשה שאבי שבשמים גזר עלי, לפי שמעשה המצות צ\"ל דוקא בבחי' עול וביטול<sup data-n=\"465\">7</sup> ואם יאמר אי אפשי א\"כ אין זה קבלת עול כו'.\n<b>וזהו</b> שא' שמואל לשאול הנה שמוע מזבח טוב<sup data-n=\"466\">8</sup>, והיינו ששאול לקח ממיטב הצאן להביא מהם קרבנות, כי שאול הלך עפ\"י הטעם ועפ\"י טעם הי' אפשר להתברר שיביא מהם קרבנות שזהו בחי' בירור הניצוצות בחי' הטוב שיוכלו לעלות למעלה מקליפת עמלק אחר שלא החי' כל נשמה, וכמ\"ש מזה בשער האמונה ע\"ש<sup data-n=\"467\">9</sup>, והשיב לו שמואל הנה שמוע מזבח טוב כו' שביטול הרצון שיש בהמצוה הוא למעלה מן הכוונה וטעם וסוד, ואעפ\"י שיש בעולה וזבח שהן קרבנות טעם וסוד ה' אבל אין זה העיקר, והגם שבודאי יש חפץ ה' עכ\"פ בזבח הקרבן כי רצה\"ע הוא במעשה המצוה עצמה של הקרבן, אך בכאן בקליפת עמלק אין חפץ ה' בזבח שיעלה מהם, לפי ששנאת עמלק הוא למעלה מן הטעם כו', והיינו שעמלק יודע את רבונו ומתכוין",[["464","6","<b>מעשה . . כמו מעשין על הצדקה</b>: ראה בהנסמן ע\"ז בסה\"מ תרל\"ד שם ע' פו."],["465","7","<b>אל יאמר אדם אי אפשי . . אלא אפשי . . בבחי' עול וביטול</b>: ראה אודות ההפרש בזה בין צדיקים לבע\"ת: כש\"ט (הוצאת קה\"ת) סי' שצח. לקו\"א להה\"מ כו, ג. לקו\"ת ואתחנן ט, ד. המשך מים רבים תרל\"ו ע' רלד. סה\"מ תש\"ד ע' 136. תש\"ה ע' 42. סה\"מ מלוקט ח\"א ע' לה. לקו\"ש ח\"ד ס\"ע 1182 ואילך. חכ\"ט ע' 235. ועוד."],["466","8","<b>וזהו שא' שמואל לשאול הנה שמוע מזבח טוב</b>: בהבא לקמן ראה מאמרי אדה\"ז תקס\"ד ע' קל. נביאים ע' ה ואילך. אתהלך לאזניא ע' קט. מאמרי אדהאמ\"צ נ\"ך ע' א ואילך. אוה\"ת בשלח ע' תלט ואילך. סה\"מ תרכ\"ט ע' רפא. שפא. לקמן ד\"ה ויקהלו אל המלך."],["467","9","<b>וכמ\"ש מזה בשער האמונה ע\"ש</b>: כח, א ואילך."]]],[2002180193,"למרוד בו<sup data-n=\"468\">10</sup>, א\"כ הוא למעלה מן הטעם ודעת לכן הי' צריך להיות מחייתו ג\"כ בבחי' הביטול שלמעלה מן הטעם כו', ולא להביא קרבנות שהם ע\"פ טעם ודעת.\n<b>ועוי\"ל</b> שבכל עשיית המצות המעשה עיקר וגדול יותר מהכוונה, שהרי אם יכוון בכל הכוונות דאכילת מצה, או הנחת תפילין, ולא יאכל בפו\"מ מצה הגשמי, או שלא יניח תפילין בראשו וזרועו לא ימשיך עי\"ז כלום, ולא יקיים המצוה, משא\"כ כשאוכל מצה או מניח תפילין ולא יכוון כלום הרי קיים המצוה, רק שעשאה שלא כדבעי שהרי מצוה בלא כוונה כגוף בלא נשמה, ומ\"מ ה\"ה מצוה ונמצא כי העיקר היא המעשה כו'. וזהו שק\"ש היא כלליות כל המצות, שהרי כתי' וזאת המצוה כו' שמשמע כל המצות ונא' אח\"כ ק\"ש<sup data-n=\"469\">11</sup>, אלא מפני שק\"ש היא כללות כל המצות לפי שק\"ש היא בחי' קבעומ\"ש שמקבל ע\"ע בחי' עול וכמשארז\"ל למה קדמה פ' שמע לוהא\"ש כדי שיקבל עליו עומ\"ש תחלה ואח\"כ יקבל עליו עומ\"צ, שצריכה להיות תחלה קבעומ\"ש ואח\"כ קבלת עומ\"צ, וכמו שהי' מתחלה בשעת מ\"ת שהקדימו נעשה לנשמע, נעשה הוא בחי' קבעומ\"ש ואח\"כ נשמע, וכך ק\"ש הוא בחי' קבעומ\"ש, וע\"כ הוא כללות כל המצות כו'. וזהו ענין מעשה גדול, שכל עיקר המעלה של מעשה הוא מחמת הכפי' וביטול הרצון כו'.\n<span data-k=\"ks\"><b>קיצור.</b> מעשה מל' גט מעושה, ל' כפי' והכרח, והיינו כי זהו מלמעלה משכל המושג, ולכן אל יאמר אי אפשי אלא אפשי ואבי שבשמי' גזר, ולכן שמוע מזבח טוב, ובכל המצות העשי' גדול יותר מהכוונה, וכענין הקדמת נעשה, ולכן קודם שמע שהוא קבעמ\"ש נא' וזאת המצוה, והיינו כי זהו העיקר דכל המצות כו'.</span>\nג) <b>והנה</b> ע\"י כפי' וביטול הרצון שבנפש עי\"ז ממשיך למעלה ג\"כ בחי' כפי' והכרח, דהנה כתי' ועשיתם אותם מעלה אני עליכם כאלו עשאוני, דהנה באמת עצמות אוא\"ס הוא למעלה מגדר עולמות בחי' ממכ\"ע ואפי' מבחי' סוכ\"ע, דהנה עולם הוא בבחי' גבול ומדה וכיון שסוכ\"ע בחי' מקיף לעולם שהוא בבחי' גבול ומדה ממילא הוא ג\"כ בבחי' מקור לגבול, ואוא\"ס הוא בלתי בע\"ג בתכלית ואין ערוך אליו כו' אפילו כטפה בים אוקיינוס, לפי שטפה בים הוא ג\"כ ערך שיכולים לשער כמה טפות יש בים כו', וזהו שעש\"מ נק' מילין דהדיוטא וכמ\"ש בזהר לאו אורחא דמלכא לאשתעי במילין דהדיוטא כו', וכדי שיהי' מקור לבחי' סוכ\"ע וממכ\"ע הוצרך להיות צמצום שנתצמצם אורו הגדול העצמי ולא נשאר רק בחי' רשימו בעלמא, ואח\"כ נעשה בחי' סוכ\"ע וממכ\"ע, וכדי שיהי' בחי' צמצום האור העצמי ויניח אורו הגדול עד שיהי' מקור לעולמות כו' בחי' ועל הכסא דמות כמראה אדם שהוא בחי' ציור",[["468","10","<b>שעמלק יודע את רבונו ומתכוין למרוד בו</b>: עד\"ז הובא בכ\"מ בדא\"ח, ראה תו\"א תצוה פג, סע\"ד. פה, ד. וראה סה\"מ תרל\"ב ח\"א ע' קטו. [ובהנסמן ע\"ז שם]."],["469","11","<b>שק\"ש היא כלליות כל המצות . . וזאת המצוה . . ונא' אח\"כ ק\"ש</b>: ראה בכ\"ז בארוכה לקו\"ת ואתחנן ט, א ואילך."]]],[2002180194,"אדם בג' קוין<sup data-n=\"470\">12</sup> שהוא כמשל חכם גדול שצריך להשפיל א\"ע ולהסביר למשל את השכל לקטן שצריך לצמצם א\"ע ולהניח שכלו הגדול בכדי שיוכל להבין גם הקטן כו', וכמו\"כ ויותר מכן לאין קץ הצמצום של אוא\"ס שצמצם אורו הגדול כדי שיהי' מקור לעולמות בע\"ג, וכדי שיהי' בחי' צמצום זה זהו ע\"י הצמצום שבנפש האדם מה שמצמצם א\"ע ומניח שכלו ועושה רצה\"ע בלי שכל וטעם עי\"ז ממשיך מלמעלה ג\"כ שיהי' התגלות רצה\"ע בבחי' צמצום עצמותו שיתצמצם עצמו בבחי' כמראה אדם כו'. וזהו ענין מעשה גדול לפי שע\"י מעשה שהוא בחי' כפי' והכרח עי\"ז ממשיך מלמעלה שיהי' התגלות רצה\"ע בהשתלשלו' העולמות. וזהו ענין עושין רצונו ש\"מ<sup data-n=\"471\">13</sup>, שע\"י מעשה המצות ממשיכים רצה\"ע בבחי' מקום וזמן כו' שיהי' בחי' מקום וזמן כו'.\n<b>והנה</b> אף שע\"י מעשה המצות ממשיכים גילוי אוא\"ס, הנה הכלי לזה הגילוי הוא בחי' תורה כי אורייתא מח\"ע נפקת, ואוא\"ס שורה בחכ' וכמ\"ש הוי' בחכ'<sup data-n=\"472\">14</sup>, לפי שחכ' הוא בחי' כח מ\"ה ביטול במציאות ממש, שביטול של מעשה המצות הוא רק בחי' ביטול היש לבד, משא\"כ הביטול שבחכ' הוא בחי' ביטול במציאות ממש, וע\"כ שורה שם אוא\"ס כי אין אוא\"ס שורה אלא דוקא במי שבטל אליו, וזהו שאוריי' מח\"ע נפקת נק' היכלא עילאה דקודב\"ה והיינו כמו בהיכל ששם משכן המלך כמו\"כ באורייתא הוא המשכת הגילוי אוא\"ס. והגם שע\"י מעשה המצות ממשיכים את הגילוי אבל מ\"מ הכלי לזה הוא בחי' תורה<sup data-n=\"473\">15</sup> כמו למשל כשממשיכים את המלך צריכים להביא את המלך בהיכל, וההיכל הוא בחי' תורה, הגם כי אוא\"ס הוא למעלה גם מבחי' חכ' מ\"מ חכ' הוא הכלי לגילוי אוא\"ס, וכמו מבשרי אחזה אלק' שעיקר השראת הנפש הוא במוח הגם שהנפש היא למעלה מבחי' שכל מ\"מ הוא שורה במוח, ואח\"כ מהמוח מתפשט לרמ\"ח אברים כו', וכמו\"כ עיקר הכלי לגילוי אוא\"ס הוא בחי' תורה, ואח\"כ מתפשט לרמ\"ח פקודין כי רמ\"ח פקודין הוא רמ\"ח אברים דמלכא שהם מקבלים חיות מבחי' מוחין שבראש כו' שהוא בחי' תורה, וזהו ענין תלמוד גדול שמביא לידי מעשה שמבחי' תורה נמשך אח\"כ לרמ\"ח פקודין כו', וזהו שתלמוד נק' קדה\"ק<sup data-n=\"474\">16</sup> והיינו כי בקדה\"ק שם הוא שורה גילוי אוא\"ס וכמו בק\"ק של בהמ\"ק שהי' שם השראת אוא\"ס כו', וכך תלמוד נק' ק\"ק לפי ששם גילוי אוא\"ס, וכן חכ' נק' ק\"ק לפי שבחכ' שם שורה אוא\"ס כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וע\"י בחי' הכפי' במעהמ\"צ עי\"ז מעוררים צמצום הראשון בכדי שיהי' מקור לסוכ\"ע וממכ\"ע ולכן מעשה גדול, ומ\"מ המשכת האור הוא בתורה,</span>",[["470","12","<b>ועל הכסא דמות כמראה אדם . . ציור אדם בג' קוין</b>: ראה בארוכה תו\"א יתרו עב, ד ואילך. סה\"מ תרל\"ב ח\"א ע' יב. וס\"ע טו-ז. ועוד."],["471","13","<b>וזהו ענין עושין רצונו ש\"מ</b>: ראה בארוכה סה\"מ תרכ\"ט ע' קצז ואילך. [ובהנסמן שם]."],["472","14","<b>ואוא\"ס שורה בחכ' . . הוי' בחכ'</b>: ראה תניא פל\"ה בהגה\"ה (מד, סע\"ב)."],["473","15","<b>שע\"י מעשה המצות ממשיכים את הגילוי . . מ\"מ הכלי לזה הוא בחי' תורה</b>: ראה אוה\"ת ואתחנן שם ע' רמא. סה\"מ תרל\"ג ח\"ב ע' שנא. וש\"נ. וע' תפב. נת' בלקו\"ש חט\"ז ע' 440 ואילך. ובהע' 57 שם."],["474","16","<b>וההיכל הוא בחי' תורה . . שעיקר השראת הנפש היא במוח . . קדה\"ק</b>: בהבא לקמן עד סוף הפרק ראה בארוכה תניא פנ\"א ואילך."]]],[2002180195,"<b></b><span data-k=\"ks\">כי אורייתא מחכ', ובחכ' שורה אוא\"ס, ואורייתא היכלא עילאה דקוב\"ה, ולכן תלמוד גדול, וגם מביא לידי מעשה ע\"ד כמו שכלליות החיות שורה במוח ומשם מתפשט ההארה לכל הרמ\"ח איברים כו'.</span>\n(ד) <b>ולהבין</b> זה בתוס' ביאור ענין שאעפ\"י שהעיקר כדי שיהי' המשכת אוא\"ס הוא ע\"י מעשה המצות ואעפ\"כ תלמוד גדול לפי שהוא כלי, שלכאורה אינו מובן זה דלפי הנ\"ל הי' צריך שיהי' מעשה גדול לכל הדיעות לפי שהוא עיקר הממשיך. י\"ל זה ממה שא' משה שש מאות אלף רגלי<sup data-n=\"475\">17</sup> העם אשר אנכי בקרבו שהיו ישראל בחי' רגל לגבי משה, והנה אעפי\"כ במעשה העגל שחטאו ישראל כתי' לך רד וארז\"ל רד מגדולתך כלום נתתי לך גדולה אלא בשביל ישראל, ופי' גדולה היינו מ\"ש גדול ה' ומהולל מאד ולגדולתו אין חקר שהי' מאיר במשה בחי' גדול הוי' כו' שמשה נתנבא בזה אספקלרי' המאירה<sup data-n=\"476\">18</sup> שהי' בחי' חכ' כו', והנה הגדולה הזו מה שהי' מתנבא באספה\"מ הוא בשביל ישראל וכיון שחטאו ישראל ניטלה ממנו האור ולא נשאר אצלו כ\"א חלק א' מאלף כו', נמצא שעיקר הממשיך אצלו בחי' גילוי אוא\"ס הוא נש\"י ואעפ\"כ הגילוי הי' במשה ולא בישראל שלא היו בערך למשה כלל, אעפ\"י שהם המשיכו במשה כל הגילוי הזה, וזהו שנק' בחי' רגל והיינו כמו הרגל שהוא מעמיד את הראש כו' ואעפ\"כ עיקר הגילוי הוא בראש דוקא, וזהו שמצות נק' בשם רגל וכמ\"ש והארץ הדום רגלי כי הוא קאי על מעשה המצות כו', ובזה יובן ג\"כ ענין תלמוד גדול, אעפ\"י שמעשה המצות ממשיכים את גילוי אוא\"ס בחי' עושין רש\"מ מ\"מ עיקר הכלי הוא תורה דוקא.\n<span data-k=\"ks\"><b>קיצור.</b> דוגמא לדבר ישראל היו בחי' רגל משה שהי' הראש, והגדולה ניתן לו בשביל ישראל דוקא, ולכן כשחטאו א\"ל רד מגדולתך כו', ועכ\"ז הי' השראת הגדולה במשה דוקא, הגם שהממשיכים הגדולה היו ישראל, כן הגם כי ע\"י מעשה דוקא נמשך המשכת אוא\"ס מ\"מ ההשראה הוא בתורה דוקא כו'.</span>\nה) <b>ובזה</b> יובן מה שארז\"ל<sup data-n=\"477\">19</sup> במדרש איכה ויתר הקב\"ה על ע\"ז וג\"ע וש\"ד ולא ויתר על ביטול תורה, שלכאורה אינו מובן זה שעל שלשה עוונות אלו שהם חמורים מאד שיהרג עליהם ולא יעבור ויתר ועל ביטול תורה לא ויתר כו'. אך לפי הנ\"ל יתורץ היטב, דהנה ג' עוונות אלו הוא היפוך ג' קוין תורה ועבודה וגמ\"ח",[["475","17","<b>שא' משה שש מאות אלף רגלי . . ישראל בחי' רגל לגבי משה . . אעפ\"כ כתי' לך רד</b>: בהבא לקמן ראה תו\"א בראשית א, ב. סה\"מ תרל\"ב ח\"א ע' פג. וע' רמד. ובכ\"מ."],["476","18","<b>שמשה נתנבא בזה אספקלרי' המאירה</b>: ראה בארוכה לעיל ד\"ה בהעלותך. וד\"ה וידבר גו' המטות. וש\"נ."],["477","19","<b>ובזה יובן מה שארז\"ל . . ויתר הקב\"ה על ע\"ז .ֿ. ולא ויתר על ביטול תורה</b>: בהבא לקמן ראה אוה\"ת ואתחנן שם ע' רמו ואילך. ערב ואילך. רפז ואילך. שב ואילך. סה\"מ תרכ\"ט ס\"ע רפט ואילך. וש\"נ. [ובשאר דרושים שנסמנו לעיל בתחילת המאמר]."]]],[2002180196,"שהוא בחי' אדם דקדושה וזלעו\"ז עשה האלקי' שהוא בחי' אדם בליעל שיש בו ג\"כ בחי' ג' קוין והוא בחי' ע\"ז וג\"ע וש\"ד. ע\"ז הוא היפוך של קו העבודה, כי עיקר עבודה של הקרבנות הוא כדי להמשיך גילוי אלקות בחי' ועבדתם את הוי' אלקיכם, וע\"ז הוא ממש להיפוך מזה שהוא עובד אלקים אחרים וחושב אותם ליש ודבר, ואלקות הוא בבחי' העלם והסתר אצלו וקרו לי' אלקא דאלקיי' כו'. ושפ\"ד הוא היפוך מבחי' גמ\"ח, כי גמ\"ח הוא דוקא שיגמול איש עם חבירו חסד ואהבת לרעך כמוך וש\"ד הוא להיפוך מזה ממש כו'. וכן עריות הוא היפוך מבחי' תורה כי תורה הוא בחי' ביום חתונתו זו מ\"ת שהוא בחי' יחוד תושב\"כ ותושבע\"פ שהוא בחי' יחוד קודב\"ה ושכינתי' כו' והוא ממשיך בחי' יחוד זה בלעו\"ז.\n<b>והנה</b> עכ\"ז על ג' עבירות אלו ויתר כי הם בחי' אברים, והנה אנו רואים שאם נעשה איזה קלקול באבר א' ונסתלק חיותו, הנה עיקר הסתלקות הוא לעצמות כללות נפשו השורה במוח, והנה ע\"י הרפואות יכולים להמשיך מחדש חיותו באבר ההוא כו', אבל אם נעשה קלקול באברים הפנימי' כמו נקיבת המוח הנה א\"א להמשיך חיות חדש כו', וכך אלו ג' עבירות אעפ\"י שהם חמורים מ\"מ הוא רק הקלקול באברים החיצוני' רמ\"ח פקודין רמ\"ח אברים דמלכא, והנה ע\"י תשובה יכול להמשיך אורו מחדש, אבל ע\"י ביטול תורה נעשה הפגם במוחין שבראש שהוא בחי' חכ' שהוא בחי' הסתלקות אור הנפש לגמרי וע\"כ לא ויתר כו'. וזהו מ\"ש במדרש ואותי עזבו ואת תורתי לא שמרו, הלואי אותי עזבו ותורתי שמרו מתוך שהן מתעסקין בה המאור שבה<sup data-n=\"478\">20</sup> הי' מחזירן למוטב, לפי שתורה היא בחי' מוחין שבראש, והנה אם ישנו עדיין במוח שבראש יכולים להמשיך עדיין את האור לבחי' אברים כו', וע\"כ לא ויתר על עון ביטול תורה יותר משאר עוונות כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ולכן ויתר על ג' עבירות חמורים ולא ויתר על ביטול תורה, כי ג\"ד אלו הם נגד ג' קוין שבציור אדם, וה\"ז כמו קלקול באברים החיצונים שאין כל החיות תלוי בהם, אבל תו' זהו כמו ניקב קרום של מוח שהוא במשהו, ולכן על ג\"ד אלו ויתר כי ע\"י תשובה הי' נמשך מחדש, ולא ויתר על ביטול תורה, מפני שכלליות ההשראה היא בחכמה שבתורה כו'.</span>",[["478","20","<b>המאור שבה הי' מחזירן לטוב</b>: נת' בסה\"מ תרכ\"ט שם ע' רצ. ובדרושים שהובאו שם."]]],[2002180197,"<h3>[ברזל בברזל יחד] והנה בתורה יש ב' בחי' (ב)</h3>\n<b></b><b>בס\"ד. (ש\"פ ראה, ט\"ל).</b>\nראה\nוא\"ו) <b>והנה</b> בתורה יש שני בחי' תושב\"כ ותושבע\"פ<sup data-n=\"479\">1</sup>, לפי שהתורה היא בחי' ממוצע בין אוא\"ס לעולמות כמו המוח כו' ובכל ממוצע צריך שיהי' בו משני הבחי', וזהו ענין תושב\"כ ותושבע\"פ, תושב\"כ הוא בחי' ח\"ע, ותושבע\"פ הוא בחי' ח\"ת שהוא מקור לעולמות מל' פה תושבע\"פ קרינן לה שהוא מקור לבי\"ע כו'. וכמו שתושב\"כ ותושבע\"פ הם ב' בחי' שיש בבחי' הממוצע, כמ\"כ בתושב\"כ ושבע\"פ עצמן יש ג\"כ ב' בחי', והוא מ\"ש בכתהאריז\"ל בפי' הנוסח ועל תורתך שלמדתנו<sup data-n=\"480\">2</sup> שיש שני בחי' דהיינו התורה כמו שהיא למעלה שהוא בחי' תורתך, ושלמדתנו שנמשכת למטה כו'. והנה צריך שיהי' בחי' יחוד תושב\"כ ותושבע\"פ.\n<b>וזהו</b> ענין ברזל בברזל יחד<sup data-n=\"481\">3</sup> כמו שע\"י שמשחיזין ברזל בברזל יחד נעשה חד שעי\"ז מחדדין כו', כך שני ת\"ח העוסקים בהלכה עי\"ז ששנים יושבים ועוסקים בד\"ת עי\"ז נעשה יחוד כו' כי כיון שהם שנים וזה מקשה וזה מתרץ ממילא עי\"ז נעשה המשכה חדשה וממציאים דין חדש כו', וזהו למשל כמו היחוד שע\"י היחוד נעשה המשכה חדשה כו', כך ע\"י התורה של שנים שעוסקים בד\"ת ממשיכים מוחין חדשים בבחי' ח\"ע ג\"כ. וזהו ע\"ד מ\"ש המחדש בטובו בכל יום תמיד מע\"ב היינו שבכל יום נעשה המשכה חדשה כו' וכמו שיש י\"ב צירופי הוי' שבכל שעה נעשה צירוף חדש<sup data-n=\"482\">4</sup>, הנה אין הצירוף של שעה זו כמו של שעה זו ובכל שעה נעשה צירוף חדש ממש, עד\"ז יובן בתורה במכ\"ש, והיינו שכמו ביחוד חיצוני דחו\"ב נמשך בחי' חידוש הישנות בכ\"י, כ\"ש שביחוד פנימי דחו\"ב שע\"י התורה נמשך זיווג חדש<sup data-n=\"483\">5</sup> בכ\"י. והארה מבחי' זיו תורתן ועבודתן זהו מה שנמשך בג\"ע הארה חדשה בכ\"י, ובזה יובן מה שיש כמה נשמות שיושבין שם יותר מג' אלפים שנה<sup data-n=\"484\">6</sup> הנה בכל יום הלימוד אינו כמו שלמד תורה עתה אלא שבכל יום נמשך השגה חדשה כו' מזיו תורתן שלמדו",[["479","1","<b>וא\"ו) והנה בתורה יש שני בחי' תושב\"כ ותושבע\"פ</b>: מאמר זה הוא המשך להמאמר שלפנ\"ז ד\"ה ושננתם לבניך. וראה בהנסמן שם לכללות המאמר. הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר זה נדפסה לקמן בהוספות ושם מתחיל: ברזל בברזל יחד. והנחה נוספת מרשימות השומעים נדפסה לקמן בהוספות ובכותרת המאמר שם: ”בס\"ד ש\"ק פ' ראה ל\"ט, לד\"ה וקשרתם לאות על ידך\"."],["480","2","<b>מ\"ש בכתהאריז\"ל . . ועל תורתך שלמדתנו</b>: ראה בכ\"ז לקו\"ת עקב יז, ב. דרושים לחה\"ס פא, ד. סה\"מ תרל\"ד ע' רעח. וש\"נ. ה'ש\"ת ע' 68. וש\"נ."],["481","3","<b>וזהו ענין ברזל בברזל יחד</b>: בהבא לקמן בפיסקא זו ראה אוה\"ת ואתחנן שם ע' שי-יא."],["482","4","<b>י\"ב צירופי הוי' שבכל שעה נעשה צירוף חדש</b>: ראה תניא פמ\"א (נח, ב). וראה סה\"מ תרל\"ה ח\"א ע' קסו בשולי הגליון. הערת כ\"ק אדמו\"ר זי\"ע בליקוט פירושים ומ\"מ לתניא פמ\"א ע' תתסח. ובארוכה ברשימות חוב' קמא. נעתק ברשימות לתניא פמ\"א ע' עדר ואילך. [וראה גם ס' תולדות הרא\"ח (קה\"ת תשנ\"ח) ס\"ע פב ואילך]."],["483","5","<b>ביחוד חיצוני דחו\"ב . . חידוש הישנות . . שביחוד פנימי . . זיווג חדש</b>: ראה בכ\"ז לקו\"ת נצבים מז, א. ובארוכה ד\"ה יו\"ט של ר\"ה תרל\"ב בסוף סה\"מ תרל\"א. וש\"נ."],["484","6","<b>שיש כמה נשמות שיושבין שם יותר מג' אלפים שנה</b>: כ\"ה בכ\"מ בדא\"ח, ודיוק לשון זה נת' בסה\"מ מלוקט ח\"ב ע' לז."]]],[2002180198,"בעוה\"ז. וכמ\"כ עי\"ז היחוד של תושב\"כ ותושבע\"פ עצמן שנעשה המשכת מוחין חדשים ממש אפי' בח\"ע, כי שרש יחוד חו\"ב תושב\"כ ושבע\"פ הוא מהכתר כמ\"ש בלק\"ת מהאריז\"ל, וכ\"ז נעשה ע\"י היחוד שלמטה חדשים לבקרים שבכל יום יהיו בעיניך כחדשים כו', ועי\"ז נמשך למעלה ג\"כ המשכת מוחין חדשים כו'.\n<span data-k=\"ks\"><b>קיצור.</b> שבתורה יש ב' בחי' תושב\"כ ושבע\"פ, וגם תו' כמ\"ש למעלה, והתורה כמ\"ש בבי\"ע, וע\"י ברזל בברזל ב' ת\"ח עי\"ז נמשך יחו\"ע דתושב\"כ ושבע\"פ שנמשך מוחין חדשים גם בח\"ע, וכ\"ש מבחי' חידוש הישינות שנמשך מיחוד חיצוני דחו\"ב חיבור אין ויש, והארה מבחי' זו נמשך השגות חדשות בכ\"י בג\"ע, ועד\"ז נבין גם בתושב\"כ ושבע\"פ עצמן היינו בחו\"ב דאצי', וכ\"ז הוא מהחידוש שמחדשים בעוה\"ז ע\"י השינון דשנים שעוסקי' בתורה כו'.</span>\nז) <b>ודברת</b> בם בשבתך בביתך<sup data-n=\"485\">7</sup>, הנה איתא בס\"י שתי אבנים בונות שתי בתים כו' שאבנים נקראו אותיות, לפי שאותיות הם בחי' דומם שאין בהם קטנות וגדלות כו', וצירופי אותיות של תיבה נק' בית וצירופי תיבות ביחד נק' בשם עיר<sup data-n=\"486\">8</sup> כמו למשל צירופי בתים הרבה נק' עיר כו', וכך למעלה כתי' גדול ה' כו' בעיר אלקינו שצירופי אותיות הדבור שנתהוה בהם שמים וארץ שהוא בחי' מל', מלכותך מלכות כל עולמים נק' עיר אלקינו כו', וצריך להמשיך בעיר אלקינו מבחי' ש' הוי' שהוא בחי' גדול הוי' ומהולל מאד כו', שהוא בחי' ח\"ע כי הוי' בחכמה, והיינו שיהי' יחוד ח\"ע בח\"ת יחוד הוי' ואלקים, וזהו ע\"י התורה כי אורייתא מח\"ע נפקת שהוא בחי' גדול הוי', וע\"י התורה נמשך המשכת ש' הוי' בעיר אלקינו. וזהו ודברת בם שהוא לשון הנהגה<sup data-n=\"487\">9</sup> מלשון ידבר עמים תחתינו כו'.\n<b>והנה</b> ארז\"ל (יומא די\"ט ע\"ב) ודברת בם ולא בתפלה, ולהבין החילוק שבין תורה לתפלה הוא כי תפלה הוא בלחש וחשאי ותורה היא בקול רם דוקא וכמארז\"ל אם ערוכה ברמ\"ח איברים שמורה כו', וזהו דכתיב קול ה' בכח שהוא קאי על עשה\"ד<sup data-n=\"488\">10</sup> שהי' בכח, וכמשארז\"ל שהיו שומעים את הקול מכל ד' רוחות, וזהו מ\"ש קודם עשה\"ד וידבר אלקים את כל הדברים האלה לאמר שכתוב בהם דבור, דהנה יש חילוק בין דבור לאמירה, כי דבור הוא בקול ואמירה הוא בלחש<sup data-n=\"489\">11</sup>, וזהו ענין עשרה",[["485","7","<b>ז) ודברת בם בשבתך בביתך</b>: בהבא לקמן בסעיף זה ראה אוה\"ת ואתחנן שם ע' שיב."],["486","8","<b>שתי אבנים בונות שתי בתים . . וצירופי תיבות . . עיר</b>: ראה בכ\"ז תו\"א ויצא כא, א. כב, א. ובכ\"מ."],["487","9","<b>וזהו ודברת בם . . לשון הנהגה</b>: ראה אוה\"ת ואתחנן שם ע' שז. וראה גם תו\"א בראשית א, א. לקו\"ת אמור לג, א. ואתחנן ב, ד. ט, ג. ראה כט, ג. האזינו עד, א. שה\"ש יז, א."],["488","10","<b>קול ה' בכח . . קאי על עשה\"ד</b>: ראה גם לקו\"ת במדבר יד, ד. מאמרי אדהאמ\"צ דרושי חתונה ח\"ב ע' תסד [וש\"נ]. שם ע' תפא. וראה גם יהל אור להצ\"צ ע' קיב: קול ה' בכח בפסוק וידבר אלקים דהתחלת עשה\"ד יש כ\"ח אותיות. עיי\"ש הביאור בזה."],["489","11","<b>יש חילוק בין דבור לאמירה . . בקול . . בלחש</b>: ראה לקו\"ת שלח לט, סע\"ב. חוקת נז, ד. מאמרי אדה\"ז אתהלך לאזניא ס\"ע קד ואילך. מאמרי אדהאמ\"צ דרושי חתונה ח\"א ע' לט. סה\"מ תשי\"ג ע' 340-1. ועוד."]]],[2002180199,"מאמרות שנק' מאמרות ולא דברות שהי' בחשאי כו'. וזהו מ\"ש ודברת בם ולא בתפלה<sup data-n=\"490\">12</sup> כי דבור הוא בקול רם, דהנה כתיב וענו הלוים ואמרו בקול רם ואיתא במד\"ר בקולו של רם, והיינו כי רם הוא בחי' רוממות עצמותו שמלובש בו עצמות אוא\"ס הסוכ\"ע, וזהו ענין וידבר שהוא בקול רם לפי שבדבור של ד\"ת נמשך בחי' גילוי אוא\"ס הסוכ\"ע. וזהו ודברת בם ולא בתפלה, דהנה כתי' הקל קול יעקב קלא קדמאה חסר וא\"ו שהוא קול של תפלה כי ו' הוא המשכה למטה, משא\"כ קול של תפלה הוא בחי' העלאה וע\"כ חסר וא\"ו, וזהו ולא בתפלה כי תפלה צ\"ל בחשאי דוקא לפי שהיא בחי' העלאה, משא\"כ המשמיע קולו בתפלתו ה\"ז מקטני אמנה. אך הנה כ\"ז הוא גירסא שבתורה הוא בדבור דוקא שצריך להשמיע קולו, והנה יש עוד בחי' בתורה שהוא ג\"כ בחשאי והוא בחי' עיון שבתורה וכמשארז\"ל הא לגירסא והא לעיוני שעיון הוא בחשאי, וזהו מ\"ש וידבר אלקים את כל הדברים האלה לאמר, שמתחלה צ\"ל בחי' דבור בחי' גירסא, ואח\"כ לאמר בחשאי שהוא בחי' עיון כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ודברת ל' הנהגה היינו להמשיך בחי' גדול הוי' דחכ' בעיר אלקינו כלליות הדבור המחי' בי\"ע, ורז\"ל בם ולא בתפילה כי תפילה בחשאי העלאה, אבל תורה דבור בקול רם להמשיך בחי' רוממות עצמותו ע\"ד קול רם דלוים, אבל בתפילה המגביה קולו ה\"ז מקטני אמנה, וכ\"ז הוא גירסא שבתו' אבל עיון התורה הוא בחשאי, ולכן קודם עשה\"ד נא' וידבר לאמר ב' הבחי' הנ\"ל.</span>\nח) <b>ובלכתך</b> בדרך, כי הנה דרך הוא הילוך מעיר לעיר, והיינו שע\"י התורה נמשך גם מעיר לעיר שהוא בחי' בי\"ע לכבודי בראתיו יצרתיו אף עשיתיו, והיינו כי בשבתך בביתך<sup data-n=\"491\">13</sup> זהו המשכה רק בבחי' מל' שהוא מקור הנבראים, ואח\"כ ובלכתך בדרך זהו המשכה למטה גם בבי\"ע נתאוה הקב\"ה להיות לו דירה בתחתונים וכמ\"ש ושמרו דרך הוי' לעשות צדקה ומשפט, שע\"י צדקה ומשפט ממשיכים בחי' דרך הוי' שיומשך ש' הוי' גם בבי\"ע, והיינו ע\"י מחדומ\"ע ממשיכים ש' הוי' בבי\"ע, וכמ\"ש כי לא מחשבותי מחשבותיכם ולא דרכיכם דרכי אימתי כי לא מחשבותי מחשבותיכם כשלא דרכיכם דרכי<sup data-n=\"492\">14</sup>, אבל כשדרכיכם דרכי אזי מחשבותי מחשבותיכם, כי ע\"י מחשבה שבתו\"מ ממשיכים בחי' דרך הוי' בבחי' בריאה, וע\"י דבור בד\"ת ממשיכים ביצי', וע\"י מעשה ממשיכים בעשי' כנ\"ל, כי יש כמה בחי'",[["490","12","<b>הקל קול יעקב קלא קדמאה חסר וא\"ו . . תפלה</b>: ראה סידור עם דא\"ח יט, א-ב. לעיל ע' נג. וש\"נ."],["491","13","<b>בשבתך בביתך . . בבחי' מל' . . ובלכתך בדרך .ֿ. למטה גם בבי\"ע</b>: ראה אוה\"ת ואתחנן שם ס\"ע שז: בית בחי' היכלות כו' וזהו\"ע בשבתך בביתך והוא עד\"מ ודוגמא ממ\"ש וה' בהיכל קדשו, אבל בלכתך בדרך זהו כשיוצא לחוץ לברר ק\"נ כו', וע\"כ נאמר שבב' האופנים האלו צריך הכל להיות ודברת בם בדברי תורה בין בשבתך בביתך כי ההיכל הוא מעלים וצריך לזככו ע\"י עסק התורה כו'."],["492","14","<b>אימתי כי לא מחשבותי מחשבותיכם כשלא דרכיכם דרכי</b>: ראה גם לקו\"ת שה\"ש מד, ד."]]],[2002180200,"דרכים וכמ\"ש כי ישרים דרכי הוי' וזהו בחי' מצות שנק' דרכי הוי' כו', וזהו ובלכתך בדרך שע\"י התורה נמשך גם למטה בבי\"ע כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ובלכתך בדרך היינו להמשיך דרך הוי' בבי\"ע, כשדרכיכם דרכי הוי' דרך הוי' אז מחשבותי מחשבותיכם, שע\"י מחדומ\"ע שבתומ\"צ ממשיכים בבי\"ע.</span>"],[2002180201,"<h3>[כרע שכב כארי] ובשכבך ובקומך כו' (ג)</h3>\n<b></b><b>בס\"ד. (ש\"פ שופטים, ט\"ל).</b>\n[שופטים]\nט) <b>ובשכבך</b> ובקומך, הנה כתיב כרע שכב כארי<sup data-n=\"493\">1</sup> וכלביא מי יקימנו וארז\"ל בקשו לקבוע פ' בלק בק\"ש מפני שהוא מעניינא דבפ' ק\"ש כתיב ג\"כ ובשכבך, ופעם כתיב אצל הברכות של יעקב כרע רבץ כארי וכלביא מי יקימנו. והנה החילוק שבין כרע רבץ לכרע שכב הוא, כי כרע רבץ הוא בזמן שבהמ\"ק קיים וכרע שכב הוא בזמן שאין בהמ\"ק קיים, כי הנה שכיבה גורם לשינה וכמ\"ש וישכב וירדם. והנה גלות נמשל לשינה כמו למשל שאנו רואים שבשינה ישנו בו כל הכחות כמו שהוא ער ממש רק שהם בו בהעלם<sup data-n=\"494\">2</sup> והסתלקות אל עצמות נפשו כמו ראי' ושמיעה כו', וכך גלות נמשל לשינה, וכמ\"ש אני ישנה בגלותא, אותותינו לא ראינו, שאינו מאיר בגילוי בחי' ראי' שהוא בחי' נבואה כמו בזמן שבהמ\"ק קיים שהי' מאיר בחי' נבואה באספה\"מ או באספשא\"מ, אבל מ\"מ הי' מאיר בהם נבואה וכמ\"ש וישכון ישראל בטח בדד עין יעקב, עין יעקב הוא בחי' נבואה<sup data-n=\"495\">3</sup>, אבל בגלות אינו מאיר בחי' נבואה אותותינו לא ראינו כו' אין עוד נביא כו'. וזהו אני ישינה בגלותא כו' לפי שקודב\"ה בגלותא סליק לעילא לעילא כו', אך ולבי ער, לבי הוא קודב\"ה וכמ\"ש צור לבבי וחלקי אלקים לעולם, שהקב\"ה נק' צור לבבי כו' וכמ\"ש בזהר שכמו שהלב פליג לכל שייפין כך הקב\"ה איהו ממכ\"ע וסוכ\"ע ומחי' את כולם כו', והיינו שזה",[["493","1","<b>ט) ובשכבך ובקומך, הנה כתיב כרע שכב כארי</b>: מאמר זה הוא בהמשך להמאמרים שלפנ\"ז ד\"ה ושננתם וד\"ה ברזל בברזל. לכללות המאמר ראה בהנסמן ברד\"ה ושננתם הנ\"ל. לקמן בהוספות נדפסה הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר זה, ושם מתחיל: כרע שכב כארי.\nבהבא לקמן בפרק זה ראה ד\"ה כרע שכב באוה\"ת בלק ע' א'מה. וע' א'מח. אוה\"ת ואתחנן שם ע' שטו. ד\"ה כרע שכב תרמ\"ח בסה\"מ תרמ\"ו-נו\"ן ס\"ע תנו ואילך. וד\"ה כרע שכב תשט\"ז (סה\"מ תשט\"ז ע' 521 ואילך. תורת מנחם תשט\"ז ח\"ג ע' 33 ואילך)."],["494","2","<b>והנה גלות נמשל לשינה . . כל הכחות . . בהעלם</b>: בהבא לקמן בפיסקא זו ושלאחרי' ראה בארוכה אוה\"ת מגילת אסתר (הוצאת תש\"נ) ע' רצג ואילך. סה\"מ תרל\"ב ח\"א ע' רנג ואילך. וש\"נ. עטר\"ת ע' דש ואילך. תרפ\"א ע' קפח ואילך. ה'ש\"ת ע' 5 ואילך. תש\"ג ע' 118 ואילך. תש\"ח ע' 115 ואילך. לעיל ח\"א בחלק ההנחות ד\"ה חייב אינש."],["495","3","<b>עין יעקב הוא בחי' נבואה</b>: ראה אוה\"ת ברכה (כרך ו) ע' ב'תקנט (ע\"פ שמו\"ר פל\"ח)."]]],[2002180202,"ששייך שינה הוא רק בבחי' מדות עליונות, אבל בעצמות אוא\"ס אין שייך שם שינה כלל, וכמ\"ש הנה לא ינום ולא יישן שומר ישראל שאין שייך שם שינה כלל, וכמשארז\"ל יוחנן כה\"ג ביטל את המעוררין<sup data-n=\"496\">4</sup> וכי יש שינה לפני המקום, כי ענין בחי' שינה כבי' אינו שייך אלא בבחי' מקום שהוא בחי' מדות עליונות שהם מקור לזמן ומקום, אבל לפני המקום אין שייך שם שינה כלל כו', וזהו ולבי ער כו'.\n<b>והנה</b> בעבודה ענין שינה זהו שאעפ\"י שישנו כל הכחות בהעלם, דהיינו שאעפ\"י שנפש האדם משכלת ומתבוננת בגדולת אוא\"ס ב\"ה שכשמו כן הוא אין לו סוף ואין ערוך אליו כו' וכולא קמי' כל\"ח, ואי לזאת תכלה אליו הנפש ממש בבחי' ביטול ממש להיות גילוי אוא\"ס ב\"ה למטה כמו למעלה, ומ\"מ עכשיו אותותינו לא ראינו שאינו נראה ונגלה גילוי אוא\"ס ב\"ה הסוכ\"ע בבחי' גילוי ממש בנפש האדם להיות התפעלות הנפש כו', מחמת שאינו מאיר בגילוי, אך אעפ\"כ ולבי ער היינו בחי' פנימיות הלב בחי' רעו\"ד שם הוא מאיר בגילוי בחי' אוא\"ס ממש. וזהו כרע שכב כארי וכלביא מי יקימנו היינו שאעפ\"י שכרע שכב דהיינו בגלותא שהוא בבחי' שינה, מ\"מ הוא כארי ששוכב כו', וכמו שאנו רואים שאעפ\"י שהארי ישן מ\"מ מתייראין ממנו להגיע אליו, כך נש\"י אעפ\"י שאני ישינה אך מ\"מ ולבי ער וזהו כארי כו'. משא\"כ כרע רבץ קאי על זמן שבהמ\"ק קיים שאז הוא כרע רבץ שאין שם בחי' שינה כלל אפי' בבחי' חיצוני' הלב שהי' מאיר בהם גילוי אלקות ממש כו'. וזהו מ\"ש כאן ובשכבך ובקומך, שע\"י אותיות התורה נמשך גילוי אלקות גם בשכבך בגלות כו'.\n<b>ובקומך</b> קאי על לע\"ל, דהנה כתי' נפלה לא תוסיף קום בתולת ישראל, והקשה בזהר הא כתי' ביום ההוא אקים את סוכת דוד הנופלת<sup data-n=\"497\">5</sup> ותירץ שמ\"ש לא תוסיף קום היינו מעצמה כמו כל הקימות שהי' מלמטה שמעצמה היא קמה לפי שהיו כל הגליות על זמן, כמו גלות מצרים ת' מאות שנה, גלות בבל שבעים שנה, וכיון שכלה הזמן ממילא היא תקום, משא\"כ לע\"ל לא תקום מצד עצמה אלא קודב\"ה יוקים לה מעפרא ומגלותא. וזהו ובקומך שע\"י התורה יהי' להם קימה כו' רק שלע\"ל יהי' גילוי פנימיות התורה וכמ\"ש ישקני מנשיקות פיהו כו'.\n<span data-k=\"ks\"><b>קיצור.</b> כרע רבץ הוא בזמן שבהמק\"ד קיים, וכרע שכב הוא בזה\"ג כי שכיבה גורם לשינה, שאני ישינה כו', ומ\"מ לבי ער בבחי' פנימיות הלב, וגם בזמן השכיבה נמשל כארי ששוכב שהכל יראים ממנו גם כששוכב כך בנש\"י ולבו של הקב\"ה ער שגם בהיותם כו' לא מאסתים כו', וזהו ובשכבך יש כ\"ב ך\"ב אותיות התורה, ובקומך קאי על ער שקוב\"ה יוקים לה מעפרא, שיהי' קימה שלימה, וזהו ע\"י פנימיות התורה שיתגלה לע\"ל טעמי תורה כמ\"ש רש\"י ע\"פ ישקני מנשיקות פיהו.</span>",[["496","4","<b>וכמשארז\"ל יוחנן כה\"ג ביטל את המעוררין</b>: ראה גם תו\"א צג, א. ובכ\"מ."],["497","5","<b>כתי' נפלה לא תוסיף קום . . והקשה בזהר הא כתי' . . אקים את סוכת דוד הנופלת</b>: ראה בכ\"ז אוה\"ת בלק שם ע' א'מט. וראה לקו\"ת תצא לו, ג."]]],[2002180203,"יו\"ד) <b>והנה</b> כ\"ז עתה תלמוד גדול<sup data-n=\"498\">6</sup> מפני שמביא לידי מעשה, משא\"כ לע\"ל יהי' מעשה גדול, וזהו שבפ' שני' כתיב מעשה קודם לתלמוד דפ' שני' קאי על לע\"ל, וכמ\"ש מתחלה והי' אם שמוע תשמעו, ואח\"כ וסרתם ועבדתם אלקים אחרים כו' וחרה אף ה' כו' שהוא מרמז על גלות, ואח\"כ ושמתם את דברי אלה שהוא בחי' תשובה שאין ישראל נגאלין אלא בתשובה וסוף כל סוף יבאו לבחי' תשובה, ואז יהי' מעשה גדול לפי שאשת חיל עטרת בעלה נקבה תסובב גבר, וכמ\"ש והי' ביום ההוא יצאו מים חיים מירושלים חצים אל הים הקדמוני, ירושלים הוא סופא דכל דרגין שהוא בחי' מל' מצות המלך בחי' מעשה כו' וים הקדמוני הוא בחי' ים החכמה שאורייתא מח\"ע נפקת, וזהו מ\"ש כאשר יאמר משל הקדמוני, ונק' רק בחי' כד מים החכמה וכמ\"ש ותמלא כדה ותעל, וים הקדמוני הוא בחי' עצמות ח\"ע שנק' בחי' ים כמו שהים הוא עמוק מאד, וכך כתי' מאד עמקו מחשבותיך שהוא בחי' ח\"ע. והנה לע\"ל יקבל בחי' חכ' מבחי' ירושלים שהוא בחי' מל' כי מעשה גדול, והיינו לפי ששרש המעשה הוא מבחי' כתר עליון שלמעלה מהחכ' כו'. והנה עתה איננו יכולים להמשיך רק בחי' חכמה, אבל לא בחי' כתר, אבל לע\"ל יהי' גילוי בחי' כתר שהוא לשון כותרת ומקיף שהוא מקיף של החכמה וגם סיג לחכמה שתיקה ע\"כ לע\"ל יהי' מעשה גדול מתלמוד כנ\"ל.\n<span data-k=\"ks\"><b>קיצור.</b> שלע\"ל יהי' מעשה גדול כי אחע\"ב, וביום ההוא יצאו מ\"ח מירושלים אל הים הקדמוני, כי שרש המל' מרדל\"א כמ\"ש המק\"מ הובא בהגהות לד\"ה לך לך שבת\"א<sup data-n=\"499\">7</sup>, ועכשיו ההמשכה מבחי' חכמה לבד אבל לע\"ל יתגלה הכתר ולכן אז מעשה גדול.</span>\nיא) <b>נמנו</b> וגמרו גדול תלמוד שמביא לידי מעשה, והנה י\"ל שהרי גם לפי\"ז מעשה גדול שהרי א' גדול תלמוד מפני שמביא לידי מעשה נמצא שעיקר הוא המעשה כי זיל בתר טעמא כו'. והנה מתחלה י\"ל ענין המעלה של מעשה, דהנה איתא במד\"ר ע\"פ מכון לשבתך פעלת הוי'<sup data-n=\"500\">8</sup> גדול מה שנאמר בבנין בהמ\"ק יותר ממה שנאמר בברה\"ע, שבברה\"ע כתיב ויאמר אלקים שבעש\"מ נבה\"ע במאמר לבד, ולא כתיב בהן פעולה, משא\"כ בבנין בהמ\"ק כתיב מכון לשבתך פעלת כו'. נמצא מובן מזה שמעשה גדול מבחי' דבור. וזהו שמצינו שבכל דבר גבוה והפלגת הטוב כתיב בהן פעולה או מעשה, וכמו מה רב טובך אשר צפנת כו' פעלת לחוסים בך, מה רב טובך קאי על הפלגת הטוב דלע\"ל כתיב בהן פעולה, וכן כתיב עדן עין לא ראתה אלקים זולתך יעשה למחכה לו כתיב עשי' כו', או כמ\"ש כי כאשר השמים החדשים",[["498","6","<b>יו\"ד) והנה כ\"ז עתה תלמוד גדול</b>: בהבא לקמן ראה אוה\"ת ואתחנן שם ס\"ע רמז ואילך."],["499","7","<b>כמ\"ש המק\"מ הובא בהגהות לד\"ה לך לך שבת\"א</b>: ראה אוה\"ת לך לך (כרך ד) תרפז, א (בשם הע\"ח). לקו\"ת חוקת נח, ב (בשם הע\"ח). שם סד, א (בשם המק\"מ). סה\"מ תרל\"ג ח\"א ע' רנד. וע' רעג. ח\"ב ע' שצא (בשם המק\"מ)."],["500","8","<b>והנה מתחילה י\"ל ענין . . מעשה . . מכון לשבתך פעלת הוי'</b>: בהבא לקמן בפרק זה ראה אוה\"ת ואתחנן שם ע' רמט וע' רנא."]]],[2002180204,"והארץ החדשה אשר אני עושה כו', שמכ\"ז מובן שמעשה הוא בבחי' גבוה מאד. ולכאורה אינו מובן זה שהרי כתיב כל הנק' בשמי ולכבודי בראתיו יצרתיו אף עשיתיו שבריאה הוא בחי' מחשבה, ויצי' הוא בחי' דבור שהוא בחי' צורה לחומר, ואף עשיתיו הוא בחי' עולם העשי' שהוא בחי' היותר אחרון ולכן נאמר אף להפסיק הענין, כי עשי' מרוחק יותר מיצי' מכמו יצי' לגבי הבריאה כו' כמ\"ש במ\"א<sup data-n=\"501\">9</sup>, ולכאורה הוא להיפך ממה שמבואר לעיל.\n<b>אך</b> הענין הוא דהנה אנו רואים שהחילוק בין דבור למעשה הוא כי דבור אין בו כח פנימי' כלל רק בחי' כח חיצוני' בחי' הבל הלב בעלמא שאין בו עמל ויגיעה כלל, וזהו ענין עש\"מ שבהן נברא העולם שהם בחי' הארה בעלמא שאינו נוגע אל עצמותו כלל, וכמ\"ש בכ\"ד בדברי רז\"ל שלא בעמל ולא ביגיעה ברא הקב\"ה את עולמו, משא\"כ במעשה מלובש כח פנימי יותר שמתלבש בו כח הפועל בנפעל כו'. והנה למעלה ענין מעשה זהו מ\"ש הקב\"ה מניח תפילין הקב\"ה מתעטף בציצית שזהו בחי' מעשה, כמו למשל למטה כשצריך להניח תפילין זהו ע\"י פעולה כו'. ועד\"ז יובן למעלה ענין הקב\"ה מניח תפילין, והיינו שבזה מלובש כח פנימי יותר מאוא\"ס, שבברה\"ע אינו נמשך כ\"א הארה בעלמא, כי התהוות העולמות הוא מבחי' הדבור שהוא הארה כנ\"ל רק שדבורו של הקב\"ה חשיב מעשה, אבל במצות מלובש כח יותר עליון מבחי' פנימי' אוא\"ס כו'.\n<b>וזהו</b> ענין מה שמעשה גדול מתלמוד כי תלמוד הוא בחי' דבור, משא\"כ מעשה הוא בחי' פעולה, מלבד מה שמעשה גדול לפי שהוא כפי' והכרח ביטול הרצון כו' כנ\"ל, הנה לבד זה הוא גדול מחמת שהוא בחי' מעשה בעצמה, והגם כי בדבור דת\"ת עקימת שפתים הוי מעשה עכ\"ז אינו דומה לבחי' מעשה דמעשה המצות שהם בחי' מעשה בעצם כו'. וזהו שאנו רואים שאין מענישים כ\"א על מעשה בפו\"מ, משא\"כ על לאו שאין בו מעשה אין לוקין עליו כו'. וזהו ג\"כ מה שנמצא בדברי רז\"ל ענין מעשה רב, שדבור יכול שיאמר אף בדבר שאינו אמת כ\"כ להלכה למעשה, וע\"כ על דבור אין אנו סומכין כ\"כ, משא\"כ על מעשה אנו סומכין להורות כך ההלכה כו'. ובזה יובן דברי רז\"ל גדול מה שנאמר במקדש יותר ממה שנאמר בברה\"ע, והיינו לפי שבמקדש הוא מלובש כח פנימי' יותר עליון כו'. ומ\"ש בראתיו יצרתיו אף עשיתיו אין הפי' שהוא נעשה ע\"י עשי' שלמעלה, אלא ענין דמיון עולם העשי' לבחי' מעשה שכמו שמעשה הוא בחי' אחרונה שהרי מתחלה כשצריך לעשות איזה מעשה מתחלה צריך לצייר בשכל איך לעשות ואח\"כ משכל למחשבה וממחשבה לדבור שמצוה לעשות ואח\"כ נעשה הפעולה כו', שהמעשה הוא סוף ההשתל', וכך העשי' הוא בחי' סוף לסדר השתלשלות המדריגות כו', וזהו שנק' אף עשיתיו, אבל אין הפי' שמלובש בו כח פנימי כמו במעשה כו' שהרי עולם העשי'",[["501","9","<b>כי עשי' מרוחק יותר מיצי' מכמו יצי' לגבי הבריאה כו' כמ\"ש במ\"א</b>: ראה תו\"א מג\"א צה, ב. לקו\"ת בלק סז, א ואילך. סה\"מ תרל\"ג ח\"א ע' קנד-ה. וע' קעב. ח\"ב ע' שעב."]]],[2002180205,"נתהוה מעש\"מ כמו כל העולמות בריאה יצי' ואדרבה שמלובש בו כח חיצוני' יותר לפי שנתהוה מחילופי' ותמורות כו', כמ\"ש בסש\"ב ח\"ב<sup data-n=\"502\">10</sup>.\n<span data-k=\"ks\"><b>קיצור.</b> גדול מה שנאמר בבהמ\"ק מברה\"ע, דכתיב מכון כו' פעלת, ובכל הפלגת הטוב נא' ל' פעולה או עשי', ולכאו' הלא כתי' אף עשיתיו, אך הענין שהפרש בין דבור לעשי' שבדיבור רק הארה לבד ובעשי' יש פנימיות יותר, ולכן גדול מ\"ש במקדש, וז\"ש אף עשיתיו זהו שענין המעשה הוא כח היותר אחרון שגם זולתו ממלא אותו משא\"כ דיבור מחבר אותו עם זולתו, וה\"ה בערך למח' שמגלה העלם העצמי לגבי עצמו כו'.</span>\n(יב) <b>והנה</b> מעתה<sup data-n=\"503\">11</sup> י\"ל מ\"ש נמנו וגמרו תלמוד גדול שמביא לידי מעשה, הנה כתיב לא איש אל ויכזב ובן אדם ויתנחם ההוא אמר ולא יעשה ודיבר ולא יקימנה, ולכאורה אינו מובן ענין אומרו איש ואדם. והענין הוא דהנה אדם הוא בחי' מ\"ש ועל הכסא דמות כמראה אדם עליו מלמעלה שהוא בחי' מדות עליונות כו', וזהו ג\"כ ענין איש כי איש הוא ג\"כ בחי' מדות, והנה בבחי' מדות אדם ואיש שם יוכל להיות שינוים.\n<b>ובזה</b> יובן מה שאנו מבקשים ומתפללים בכל יום רפאנו<sup data-n=\"504\">12</sup> ה' ונרפא כו' ברך עלינו כו', ולכאורה אינו מובן זה מהו ענין הבקשה שאנו מבקשים בכל יום הלא כל דבר קצוב מר\"ה<sup data-n=\"505\">13</sup>, וא\"כ הבקשה היא לכאורה אך למותר, שממ\"נ אם נקצב לו ממילא יומשך לו הבקשה, ואם לאו לא יועיל כו'. אך הענין הוא לפי שאף שנקצב בב\"ד של מעלה מ\"מ יוכל להיות שישתנה לפי אופן מעשה התחתונים, והיינו שלא יומשך השפעה בגשמי' כ\"א שישאר ברוחני', ובגשמי' יכול להיות שלא יומשך אף שנקצב לו שיחי', מ\"מ אפשר שלמטה לא יומשך רק שזה החסד שנקצב לו יותן לו בג\"ע לע\"ל. וע\"ז אנו מבקשים בכ\"י היינו שהחסד זה שנקצב יומשך למטה בגשמי' כו', והיינו לפי שזה שנקצב בר\"ה הוא בבחי' ב\"ד של מעלה שהוא בחי' אדם ואיש שהוא בחי' מדות עליונות וע\"כ יכול להיות שינוים.\n<b>אך</b> כ\"ז הוא בבחי' אדם, אבל יש בחי' שלמעלה מאדם ואיש, וזהו כי לא איש אל ויכזב ובן אדם ויתנחם, וכמ\"ש לא אדם הוא להנחם, ובבחי' זו אין שם שינוים",[["502","10","<b>שנתהוה מחילופי' ותמורות כו' כמ\"ש בסש\"ב ח\"ב</b>: שעהיחוה\"א פ\"א ופי\"ב."],["503","11","<b>יב) והנה מעתה י\"'ל מ\"ש נמנו וגמרו</b>: בהבא לקמן בפרק זה ראה (בקיצור) אוה\"ת ואתחנן שם ס\"ע רנא-ב."],["504","12","<b>ובזה יובן מה שאנו מבקשים . . בכל יום רפאנו</b>: בהבא לקמן בפיסקא זה ראה בארוכה לקו\"ת קרח נה, ג ואילך. [ד\"ה והנה פרח מטה אהרן]. דרמ\"צ קו, א ואילך. קיב, א ואילך. סה\"מ תרכ\"ז ע' סד ואילך. קונ' ומעין סוף מאמר יז ואילך (ע' 108 ואילך). חנוך לנער ע' 46 ואילך. סה\"מ מלוקט ח\"ד ע' רצא ואילך."],["505","13","<b>כל דבר קצוב מר\"ה</b>: בלקו\"ת קרח שם עיקר דינו של האדם הוא בר\"ה ויוהכ\"פ."]]],[2002180206,"כלל. וזהו ההוא אמר ולא יעשה ודבר ולא יקימנה, ששם אפי' דבור חשוב כמעשה שאין שם שינוים כלל, והיינו שזהו החילוק בין ממכ\"ע לבחי' סוכ\"ע, כי בבחי' ממכ\"ע פועל העלאת מ\"ן לשנות סדרי ההמשכה וע\"כ יכול להיות השתנות עפ\"י אופן מעשה התחתונים, משא\"כ בבחי' סוכ\"ע אין שם שינוי כלל, לפי שקמי' כחשיכה כאורה שוין.\n<b>והנה</b> בזה יובן ענין גדול תלמוד שמביא לידי מעשה, והיינו לפי שתלמוד הוא מבחי' סוכ\"ע שלמעלה מבחי' אדם ששם אפי' בחי' דבור חשוב כמעשה, שהרי התלמוד מבאר פי' התרי\"ג מצות ונודע כי תרי\"ג מצות דאורייתא וז' דרבנן הוא תר\"ך עמודי אור<sup data-n=\"506\">14</sup> שהוא בחי' כתר בחי' סוכ\"ע, וע\"כ אעפ\"י שהדבור אינו חשוב כמעשה אך הדבור של תורה הוא חשוב כמעשה, מאחר שמדבר איך לעשות, וא\"כ זה המעלה גופא של בחי' מעשה שמלובש כח פנימי' יותר עליון זהו ג\"כ בתורה, וזהו גדול תלמוד שמביא לידי מעשה, והיינו שגם בתורה יש המעלה של מעשה כו'. וזהו שהתורה נק' חרב פיפיות, והיינו ב' בחי' פיות, פה של ממכ\"ע ופה של סוכ\"ע. ולהבין ענין בחי' ב' פיות אלו, הענין הוא דהנה יש שני בחי' אותיות, אתוון זעירין ואתוון רברבין, והנה אתוון זעירין זהו ענין מ\"ש בהבראם בה' בראם ה' זעירא, והיינו לפי שהוא רק מבחי' הארה בעלמא, ושם הקטנה רחל שם ה' קטנה כו', שהתהוות העולמות מבחי' קטנות וצמצום אתא קלילא דלית בי' מששא כו', וזהו ענין פה של בחי' ממכ\"ע, אך יש בחי' אתוון רברבין וכמ\"ש פום ממלל רברבן שהוא בחי' אותיות שמאיר בהם גילוי אוא\"ס הסוכ\"ע כו', וזהו ענין שיש בתורה ג\"כ וכמ\"ש והיו הדברים האלה אשר אנכי מצוך היום, ששרש התורה הוא מבחי' אנכי מהותו ועצמותו ממש, וע\"כ גם זאת המעלה שבמעשה שהוא שמלובש כח פנימי' ישנו ג\"כ בתורה וע\"כ גדול תלמוד מפני שמביא לידי מעשה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> איש ואדם ז\"ע מדות, ושם שייך שינוי' אבל למעלה מבחי' איש ואדם לא יש שם שינוי' כלל, וז\"ע הבקשות שבש\"ע הגם כי מזונותיו קצובי' בר\"ה עכ\"ז יכול להיות שיתעכב, וזהו אדם נידון בכ\"י, וכ\"ז הוא בבחי' ממכ\"ע אבל בבחי' סוכ\"ע אין שם שינוי' כלל, וז\"ע מעמה\"צ ששרשם בבחי' הכתר בחי' סוכ\"ע, ומ\"מ המביא לידי מעשה זהו תלמוד שמפרש ענין המעשה איך לעשות, ולכן גם בתלמוד עצמו יש כח זה וזהו ענין פום ממלל רברבין, והיו הדברים האלה אשר אנכי מצוך שבד\"ת הכתוב מדבר כו'.</span>",[["506","14","<b>ונודע כי תרי\"ג . . וז' דרבנן הוא תר\"ך עמודי אור</b>: ראה אגה\"ק סכ\"ט (קמט, סע\"ב ואילך). ועוד."]]],[2002180207,"<h3>ולא אבה כו'</h3>\n<b></b><b>בס\"ד. (ש\"פ תצא, ט\"ל).</b>\n<b></b>ג\"פ ד\"א כו' בלעם בלא עם כו' שם הוי' שבנפש כו' ויהפך\n[תצא]\n<b>ולא</b> אבה<sup data-n=\"507\">1</sup> הוי' אלקיך לשמוע אל בלעם ויהפוך הוי' אלקיך לך את הקללה לברכה כי אהבך הוי' אלקיך, להבין מהו ענין שנא' ג\"פ הוי' אלקיך בפסוק זה, וגם מהו ויהפוך ה' את הקללה לברכה מאחר שלא שמע אל בלעם<sup data-n=\"508\">2</sup> כלל א\"כ א\"צ להפוך. הענין הוא שיש מקטרגים שמקטרגים על ישראל שז\"ע מה שנוטלין שופר בר\"ה לערבב הקטיגור<sup data-n=\"509\">3</sup> והוא שמחפש אחר עוונות בנ\"י ומדקדק אחריהם ללמד עליהם חובה, וזה נק' בחי' בלעם שכך הי' דרכו של בלעם ג\"כ שהי' מחפש ג\"כ למצוא מקום עון לישראל ראש הפעור הנשקפה ע\"פ הישימון וישת אל המדבר פניו, מקומות שהיו עתידים שם ישראל לחטוא כו'. והנה שם בלעם פירשו בגמ' בלעם בלא עם ל\"א בלה עם<sup data-n=\"510\">4</sup>, ולהבין ענין זה מהו בלא עם.\n<b>אך</b> הענין הוא דהנה כתיב לעברך בברית הוי' אלקיך כו', למען הקים אותך היום לו לעם ולהיות לך לאלקים, וצ\"ל דמה צריך כריתות ברית ע\"ז על הקים אותך היום לו לעם, דבשלמא על להיות לך לאלקים שייך ע\"ז כריתות ברית, אבל על להיות לו לעם אינו מובן. אך הענין הוא דהנה כתיב מלכותך מלכות כל עולמים ואין מלך בלא עם, והנה אנו רואים למטה שאינו שייך מלוכה כ\"א על אנשים כמותו שהם בחי' מדברים ויש להם שכל ודעת כמותו רק שהוא מלך ומתנשא עליהם, אבל על בהמות וחיות<sup data-n=\"511\">5</sup> אינו שייך לשון מלוכה עליהם רק המנהיג אותם נק' רועה כו'. וכך יובן למעלה כתי' מלכותך מלכות כל עולמים ואין מלך בלא עם, וע\"כ צ\"ל העם",[["507","1","<b>ולא אבה</b>: מיוסד וביאור על ד\"ה זה בלקו\"ת תצא לח, ג ואילך [והביאור שם לט, ב ואילך]. מאמר הלקו\"ת נמצא בנו\"א וביאורים כו': בסה\"מ תקס\"ו ע' שלד. ס' מאמרי אדהאמ\"צ דברים ח\"ב ע' תרמב ואילך. אוה\"ת תצא ע' תתקפא ואילך [שם הוא המאמר שבס' מאמרי אדהאמ\"צ]. תתקצה ואילך. תתר ואילך. ובכת\"י נמצא ג\"כ ד\"ה ולא אבה הנחת הר\"ה מפאריטש משנת תר\"ז. וראה עוד ע\"פ זה בתו\"ח בראשית קיז, א.\nונמצא בשינויים ותוס' הגהות וכו' בד\"ה זה בסה\"מ עטר\"ת ע' תרלא ואילך. וחלקו נמצא בד\"ה השקיפה בסה\"מ ה'ש\"ת ע' 155 ואילך. [מיוסד על סה\"מ עטר\"ת שם. וראה גם ד\"ה על ג\"ד העולם עומד סה\"מ ה'ש\"ת שם ע' 161]. ובד\"ה קול קורא במדבר בסה\"מ תש\"א ע' 74 ואילך. וראה גם ד\"ה השקיפה תשכ\"ז בסה\"מ מלוקט ח\"ד ע' שעב-ג. וע' שעט.\nמאמר זה נמצא בכת\"י 466 רצד, א [כת\"י זה נק' ”בוך במדבר דברים — ר' בערל קאליסקער\". שם חסרים כמה פיסקאות במאמר זה]. ובשלימות יותר בכת\"י 1038 קמז, א. וכאן בס' תרל\"ט נרשם המאמר בתוס' הגהות בגוכי\"ק.\nראה לקמן בהנחות מאמר זה מהנחת כ\"ק אדמו\"ר מהורש\"ב נ\"ע. בכותרת: ”ש\"פ תצא ט\"ל לפ\"ק (ביאור על ד\"ה ולא אבה שם לקו\"ת)\"."],["508","2","<b>וגם מהו ויהפוך ה' את הקללה לברכה מאחר שלא שמע אל בלעם</b>: כמה שורות הוא ע\"פ לשון הלקו\"ת תצא שם (לח, ג)."],["509","3","<b>שז\"ע מה שנוטלין שופר בר\"ה לערבב הקטיגור</b>: עי' ר\"ה טז, רע\"ב ורש\"י ותוס' שם."],["510","4","<b>פירשו בגמ' בלעם בלא עם . . בלה עם</b>: ראה בארוכה אוה\"ת בלק ע' תתצט. סה\"מ תרכ\"ט ע' ערב."],["511","5","<b>שאינו שייך מלוכה כ\"א על אנשים . . אבל על בהמות וחיות</b>: ראה בכ\"ז לקו\"ת דרושים לר\"ה נו, סע\"ב-ג. ובארוכה מאמרי אדה\"ז כתובים ח\"א ע' עו ואילך. אוה\"ת דרושים לר\"ה ע' א'שלה ואילך. סה\"מ תר\"ס ע' ח ואילך."]]],[2002180208,"בערך ודוגמא למלך כמובן ממשל הנ\"ל, ואיך יתכן זה שיהיו עם שהם בחי' נבראים בע\"ג בערך ודוגמא לבורא כו' שהוא בלתי בע\"ג בתכלית. ובזה יובן מה שצריך כריתות ברית ע\"ז למען הקים אותך היום לו לעם שיהי' בערך ודוגמא למעלה. אך עדיין י\"ל זה איך יכול להיות שיהיו בערך ודוגמא.\n<b>והענין</b> הוא, דהנה כתיב נעשה אדם בצלמינו כדמותנו, וגם זה צ\"ל איך יכול להיות בצלמנו כדמותנו. אך הנה כתי' ועל הכסא דמות כמראה אדם עליו מלמעלה דהיינו שנתצמצם בבחי' כמראה אדם, דבאמת בעצמות אוא\"ס כתי' כי לא אדם הוא אך שנתצמצם בבחי' כמראה אדם כדי להיות מקור לעולמות, דהנה בחי' אדם הוא בחי' ג' קוין חסד דרועא ימינא גבורה דרועא שמאלא כו', והיינו כמו למטה שכל השפעות והמלאכות הוא ע\"י יד ימין שעיקר הכח הוא ביד ימין, וכך למעלה השפעת חסד וטוב נק' בשם דרועא ימינא, וגבורה דרועא שמאלא, כי מלך במשפט יעמיד ארץ ע\"כ צריך להיות ב' הקוין חו\"ג כו', ותפארת גופא הוא בחי' הרחמים וכמ\"ש המו מעי לו רחם ארחמנו כו', וכן יש בחי' ראש שהוא חכ' מוחא כו', וע\"כ נק' בחי' אדם כו'. וזהו ועל הכסא דמות כמראה אדם דהיינו שנתצמצם בבחי' כמראה אדם, כי בעצמותו ומהותו אינו שייך כלל בחי' אדם וכמאמר ולאו מכא\"מ איהו כלל רק שנתצמצם בבחי' ע\"ס כדי להיות מקור להשתלשלות העולמות כו', וזהו לאחזאה איך מתנהג עלמא כו' אבל לאו כו'. וע\"ז הבחי' נאמר נעשה אדם בצלמנו כדמותנו, כי נש\"י נקראים ג\"כ בשם אדם וכמשארז\"ל אדם אתם אתם קרוים אדם והיינו ע\"י שהם בבחי' בצלמינו כדמותינו<sup data-n=\"512\">6</sup> פי' בצלמנו הוא בחי' יחו\"ע ביטול במציאות למסור נפשו באחד, וכדמותנו הוא בחי' יחו\"ת ביטול היש לאין ועי\"ז נקראו בשם אדם שהם דוקא דוגמא למעלה.\n<b>ובזה</b> יובן מ\"ש למען הקים אותך היום לו לעם, דהיינו שיהי' הוא ית' נק' מלך על עם והעם צ\"ל בערך למלך כנ\"ל, ואיך הוא אלא לפי שנתצמצם בבחי' כמראה אדם ונש\"י נקראים ג\"כ בשם אדם, והגם שבאמת אין ערוך כלל למעלה וכמ\"ש אברהם<sup data-n=\"514\">7</sup> ואנכי עפר ואפר, והיינו לפי שאברהם הוא בבחי' בריאה רק שהי' מרכבה לבחי' מדות דאצי' ע\"כ אמר שהוא לגבי מדות דאצי' הוא רק בערך עפר ואפר, אך מ\"מ הוא דוגמא למעלה, וע\"כ נקראים בחי' עם שהם בדוגמא למלך כו'. אך כדי שיהי' בחי' מלך צריך לקבל מקודם עול מלכותו ברצון קבלו עליהם, והיינו שצריך לקבל עומ\"ש וכמשארז\"ל למה קדמה פ' שמע לוהא\"ש כדי שיקבל עליו עומ\"ש תחלה, ועי\"ז נק' מלך ישראל וגואלו דוקא, והיינו לפי שישראל מקבלים עליהם",[["512","6","<b>והענין הוא דהנה כתיב נעשה אדם בצלמינו כדמותינו</b>: בהבא לקמן ראה סה\"מ תר\"ל ע' רמב ואילך. רנ ואילך. תרל\"א ס\"ע ב ואילך."],["514","7","<b>וכמ\"ש אברהם ואנכי עפר ואפר . . לגבי מדות דאצי'</b>: ראה בכ\"ז אגה\"ק סי' טו (קכא, סע\"א ואילך). סה\"מ תר\"ל ע' נו ואילך. תש\"ב ע' 84. ועוד."]]],[2002180209,"עומ\"ש כו'. אך לע\"ל כתי' והי' הוי' למלך על כל הארץ, והיינו לפי שכתי' כי אז אהפוך אל עמים שפה ברורה לקרוא כולם בשם ה' ולעבדו שכם א', ויקבלו כולם עליהם עומ\"ש וע\"כ נאמר והי' ה' למלך על כל הארץ כו'. וזהו למען הקים אותך היום לו לעם.\n<b>אך</b> בלעם הוא בלא עם, והיינו שלא רצה להיות בבחי' עם ולקבל עליו עומ\"ש ויהי' בטל לאלקות כו', רק רצה שיהי' בחי' נפרד וילך אחר תאוות גשמיות, ועכ\"ז יקבל ג\"כ השפעת האלקות כו' ואיך יכול להיות זה, והיינו שיקבל מבחי' רם, כי לא אדם הוא למעלה מבחי' כמראה אדם, אשר שם כחשיכה כאורה ואם צדקת מה תתן לו כו', והיינו שהי' מקטרג שגם ישראל אינם מקבלים עליהם עומ\"ש כו'. אך לא אבה הוי' אלקיך לשמוע אל בלעם, והיינו לפי שכך עלה ברצונו להתצמצם ולהתלבש דוקא בבחי' כמראה אדם שיהי' מלך על עם דוקא, וכענין כד סליק ברעותי' למברי עלמא והיינו שכך עלה ברצונו כו'. וזהו ולא אבה, אבה היינו בחי' רצון, וכ\"כ למה, ביאר הכתוב מצד כי הוי' אלקיך<sup data-n=\"515\">8</sup> שהוי' אלקיך ממש שורה בכל נפש, שבכל נפש יש בחי' הארה משם הוי' ממש וכמ\"ש כי חלק הוי' עמו, ועוד ראי' שהרי כתי' ועל הכסא<sup data-n=\"513\">9</sup> דמות כמראה אדם עליו מלמעלה הוא דמות כבוד הוי', הרי בחי' כמראה אדם הוא בחי' הוי' כו', וכתי' נעשה אדם בצלמנו כדמותנו כו', הרי מבואר שבכל נפש יש הארה מש' הוי' ממש ועמ\"ש בלק\"ת בד\"ה ראה אנכי<sup data-n=\"516\">10</sup>.\n<b>וביאור</b> ענין זה, כי הנה פי' הוי', יו\"ד חכ', ה' בינה, וא\"ו מדות כו'. והנה על היו\"ד יש ג\"כ קוץ שהוא למעלה מבחי' יו\"ד כו', וביאור ענין מהו קוצו של יו\"ד, הנה כתי' והחכמה מאין תמצא דהיינו שאינו בדרך השתל' כו', כי מחכמה ולמטה נק' בחי' השתלשלות כמו מחכמה לבינה ומדות שאינו דבר חדש רק גילוי ההעלם, אבל התהוות החכמה מלמעלה מהחכמה אינו בחי' העלם וגילוי אלא שהוא דבר חדש לגמרי ואינו מושג ומובן כלל איך נתהוה שכל זה. וכן כשלומד מסכת אחת בעיון ושגורה בפיו וכאלו מונחת אצלו בקופסא ואח\"כ כשעוסק בענין אחר או לומד מס' אחרת אעפ\"כ כשרוצה נזכר<sup data-n=\"517\">11</sup> על כל מסכת ההיא שלמד תחלה, הרי ע\"כ צ\"ל שישנה במוחו ושכלו גם בעת שאינו מהרהר בה כלל, והיינו במקור השכל וא\"כ איך ומה הוא מהות שכל זה שיש אצלו אף כשאינו מחשב בה כלל הרי אין זה מושג כלל איך ומה הוא, וע\"כ נק' בחי' אין כו'. וזהו והחכמה מאין תמצא שהתהוות החכמה הוא מבחי' אין מבחי' שאינו מושג ומובן כלל, ולכן בחי' קוצו של יו\"ד הוא בחי' רמז בלבד שאינו",[["515","8","<b>וכ\"כ למה, ביאר הכתוב מצד כי הוי' אלקיך</b>: בהבא לקמן ראה לשון הלקו\"ת תצא שם."],["513","9","<b>ועל דמות הכסא דמות כמראה אדם . . כי לא אדם . . אדם . . ג' קוין</b>: ראה בכ\"ז בארוכה תו\"א יתרו עב, ד ואילך. סה\"מ תרל\"ב ח\"א ע' יב. וס\"ע טו-ז. ובכ\"מ."],["516","10","<b>ועמ\"ש בלק\"ת בד\"ה ראה אנכי</b>: דף יח, א ואילך."],["517","11","<b>כשלומד מסכת . . ואח\"כ . . לומד מס' אחרת אעפ\"כ כשרוצה נזכר</b>: ראה משל זה בארוכה בלקו\"ת הוספות לס ויקרא נב, סע\"ג-ד. מאמרי אדה\"ז ענינים ע' שכא. מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תתקכא. דרך מצותיך קלו, א. אוה\"ת ויקרא (כרך ב) ע' תשג. וע' תשו-ז. סה\"מ תרמ\"ז ע' מח."]]],[2002180210,"בחי' אות, שרומז לא\"ס בלבד ברמז בעלמא בלי שום תפיסא<sup data-n=\"518\">12</sup> כי לית מח' תפיסא בך כלל, וכמ\"ש ודי לחכימא ברמיזא, שמחמת שהשכל גדול מאד א\"א להתלבש בבחי' אותיות כ\"א ברמז בעלמא, וכך הקוץ שעל היו\"ד הוא בבחי' רמז בעלמא.\n<b>וענין</b> קוצו ש\"י שיש בנפש, כי הנה<sup data-n=\"519\">13</sup> בכל נפשות הצדיקים יש בחי' אהבה הטבעית<sup data-n=\"520\">14</sup> המסותרת<sup data-n=\"521\">15</sup> ומוטבעת בטבע נפשו האלקית<sup data-n=\"522\">16</sup> שלא להיות נפרד מיחודו ואחדותו ית', ואין אדם עובר עבירה אא\"כ נכנס בו רוח שטות המטעה אותו לומר שאעפ\"כ עודנו כו' אבל ליפרד מיחודו ית' הרי אפי' קל שבקלים מוסר נפשו עק\"ה כו' מחמת טבע נפשו, נר ה' נשמת אדם<sup data-n=\"523\">17</sup>, כנר הדולק שהשלהבת עולה מאליה כו' בלי טעם ודעת אלא שהיא מסותרת ומכוסה בלבוש שק הוא הגוף הגשמי וממנו בא הרוח שטות כו', אבל כשמעורר את האהבה עד שתחפץ לצאת מלבושיה הרי הוא בא לידי יראת חטא שלא לעבור אפי' על דבר קל של ד\"ס כי חמורים ד\"ס יותר מד\"ת שלכן נקראו סופרים, כי הנה יש בחי' סופר וספר וסיפור<sup data-n=\"524\">18</sup>, ספר הוא בחי' תשב\"כ וסופר הוא העושה את הספר הוא בחי' תשבע\"פ א\"ח עטרת בעלה. וזהו ומותר האדם מן הבהמה אין היינו בחי' אין שיש בכל נפש מישראל דהיינו בחי' רצון שלמעלה מטעם ודעת כו'.\n<b>וענין</b> בחי' יו\"ד דש' הוי'<sup data-n=\"525\">19</sup>, הנה יו\"ד הוא בחי' חכמה כח מ\"ה שהוא בחי' אצי' כי יו\"ד באצי' כו', והנה פי' אצי' הוא מל' ויאצל<sup data-n=\"526\">20</sup> מן הרוח אשר עליו כו'",[["518","12","<b>קוצו של יו\"ד הוא בחי' רמז בלבד . . שרומז לא\"ס בלבד ברמז בעלמא בלי שום תפיסא</b>: כ\"ה גם בביאור לד\"ה ולא אבה בלקו\"ת תצא שם לט, ב. ובלקו\"ש חי\"ט ע' 420 וחל\"ט ע' 147 הע' 21 כ' על ל' זה: מאריכות לשונו משמע שכוונתו הוא לב' ענינים: א) הטעם מה שבחי' כתר נרמזת בקוצו של יו\"ד דוקא — לפי שה”קוצו של יו\"ד הוא בחי' רמז בלבד\". ב) שגם בהקוץ, עם היותו ”בחי' רמז בלבד\", אינו נתפס בו, ורק ”רומז כו' ברמז בעלמא\", וכמפורש בהגהות הצ\"צ ל[לקו\"ת תצא] שם (אוה\"ת תצא ע' תתר. ובארוכה ד\"ה אורח חיים תרס\"ט), שהוא כמו ענין לחכימא ברמיזא, ע\"ש. ומזה מובן גם בנוגע לבחי' חכמה שמדמה שם לכתר — שאינה נתפסת בהיו\"ד (רק שהיו\"ד מרמז עלי')."],["519","13","<b>וענין קוצו ש\"י שיש בנפש, כי הנה</b>: להבא להלן ראה לקו\"ת תצא שם (לח, ג). התוכן מכאן ואילך, נמצא ג\"כ בסה\"מ תרכ\"ט (הוצאת תשנ\"ב) רצט ואילך. ובשינויים בסה\"מ תרל\"ב ח\"א ע' רצג."],["520","14","<b>כי הנה בכל נפשות הצדיקים יש בחי' אהבה הטבעית</b>: בלקו\"ת תצא (ובסה\"מ תרכ\"ט) שם: בכל נפש מישראל. [ועד\"ז בד\"ה זה עטר\"ת: ולכן ישנה אהבה זו בכאו\"א מישראל. ועד\"ז כותב כאן לקמן בהמאמר: היינו בחי' אין שיש בכל נפש מישראל. ולפעמים שינויים כאלו הם מחמת הצענזור]."],["521","15","<b>המסותרת</b>: בלקו\"ת תצא שם: המיוסדת. אך בכת\"י 1824 תיקן כ\"ק אדמו\"ר הצ\"צ: המסותרת."],["522","16","<b>ומוטבעת בטבע נפשו האלקית</b>: כ\"ה גם בלקו\"ת תצא ובסה\"מ תרכ\"ט ותרל\"ב שם. וראה עד\"ז הלשון בתו\"א ויגש מד, ב: והוא הנק' אהבה מסותרת שהיא האהבה שיש בטבע תולדת הנפש האלקית כו'. ועוד. ובגוכי\"ק תרל\"ט כאן יש כעין קו על תיבת ”האלקית\", ואינו ברור בכת\"י אם ר\"ל להשמיט תיבה זו מכאן."],["523","17","<b>ואין אדם עובר עבירה . . אפי' קל שבקלים מוסר נפשו . . מחמת טבע נפשו נר ה' נשמת אדם</b>: ראה בכ\"ז בארוכה תניא פי\"ח-י\"ט (כד, א ואילך)."],["524","18","<b>יש בחי' סופר וספר וסיפור</b>: ראה בכ\"ז לקו\"ת דרושים לחה\"ס פ, ב. שה\"ש ז, א. סה\"מ תרל\"ג ח\"ב ע' תקמה. תרל\"ד ע' נה. ועוד."],["525","19","<b>וענין בחי' יו\"ד דש' הוי'</b>: מכאן ואילך הוא ע\"פ לקו\"ת תצא שם (לח, ג) ס\"ב."],["526","20","<b>אצי' הוא מל' ויאצל</b>: ראה בכ\"ז בארוכה תו\"א בראשית ג, א. וירא יד, א. מאמרי אדה\"ז תקס\"ג ח\"א ע רצב ואילך. אוה\"ת ואתחנן ע' קפו ואילך. סה\"מ תרל\"ב ח\"א ע' מב. וע' רד. ובכ\"מ."]]],[2002180211,"שהוא הפרשת הארה מעצמותו כו', והנה לפ\"ז משמע שיש שייכות וערך עכ\"פ לפי שהוא הארה מעצמותו כו', וצ\"ל שהרי כתי' אין ערוך אליך שאפי' ח\"ע אין ערוך אליו. אך הענין הוא דבאמת שהוא הפרשת הארה מעצמותו, אך ההארה הנ\"ל אינו מאיר כמו שהוא, שאם הי' מאיר כמו שהוא לא הי' באפשרי להתהוות עולמות כלל רק שהיו בטלים ונכללים בעצמותו כו', אלא הארה הנ\"ל אינו מאיר כ\"א ע\"י צמצום וירידה, כדמיון הארה היוצאת דרך שערות הראש<sup data-n=\"527\">21</sup> שצומחין ויונקים מן המוחין שבראש דרך הגולגלתא החופפת על המוחין, שמעלמת ומסתרת את המוחין עצמן שלא יהיו בגילוי, כדי שעי\"ז תצמחנה השערות מעצם הגולגלתא החופף ומכסה על המוחין, והארה ההיא מצומצמת מאד עד שאין לה ערך ויחוס עם הארת המוחין עצמן כמו שאין ערך ויחוס לשערות עם המוחין, שהרי אפי' אם מגלחין את השערות לא ירגיש כאב במוחין כלל. ועכ\"ז יונקי' השערות מהמוחין כו', ולכך יש בשערות ג\"כ קדושה וכמ\"ש בנזיר קדוש יהי'<sup data-n=\"528\">22</sup> גדל פרע שער ראשו, ולכך גם בכהנים קדושתם תלוי' בשערות, אך עכ\"ז הוא רק הארה מצומצמת מהמוח כו'.\n<b>וכך</b> ככל המשל הזה ויותר מזה לאין קץ<sup data-n=\"529\">23</sup> הוא ענין התהוות החכמה מלמעלה מן החכמה מאור א\"ס ב\"ה שהוא רם ונשא כו' יותר מהתהוות המדות אהוי\"ר מן החב\"ד, שעצמיות החב\"ד הן מלובשות במדות, אבל התהוות החכמה מאוא\"ס ב\"ה אין עצמיות אוא\"ס ב\"ה מלובש בה אלא הארה מועטת ומצומצמת מן ההעלם, דהיינו לאחר ההעלם וההסתר עצמיות אוא\"ס ב\"ה וכמ\"ש ישת חשך סתרו שמסתתר בבחי' חשך והעלם להיות גילוי ההארה בבחי' חכמה ראשית גילוי ההשתלשלות, וזהו אבא יונק ממזלא כו' שהוא רק המשכה בדרך צמצום והארה. והנה<sup data-n=\"530\">24</sup> תחלת בריאת העולמות הי' מפני כי חפץ חסד הוא, אך מה שבטובו מחדש בכ\"י מעשה בראשית, מחדש בבחי' יש מאין מבחי' חכמה וצמצום בכל יום כי בכל יום מתחדשת הארה אחרת (וגם בכל שעה מתחדש צירוף ש' הוי'<sup data-n=\"531\">25</sup> כו') באתעדל\"ת תליא מילתא, וצ\"ל בחי' צמצום והעלם זה גם באתעדל\"ת, והוא להיות בחי' בטל רצונך כו' דהיינו לצמצם ולכבוש את כל רצונותיו אשר לא לה' המה, הן במחשבה רבות מחשבות בלב איש ועצת ה' היא תקום, והן בדבור שלא להיות דבורו ורוח פיו כרצונו, והן במעשה עוצם עיניו מראות ברע ולא תתורו אחרי לבבכם כו' בין באיסור בין בהיתר",[["527","21","<b>כדמיון הארה היוצאת דרך שערות הראש</b>: כמה שורות (מכאן, עד: לא ירגיש כאב במוחין כלל) הוא ע\"פ לשון הלקו\"ת תצא שם לח, סוף ע\"ג."],["528","22","<b>יש בשערות ג\"כ קדושה כמ\"ש בנזיר קדוש יהי'</b>: ראה בכ\"ז בארוכה לקו\"ת אמור לא, ד ואילך. שה\"ש לו, ד. ובכ\"מ. וראה ספרי במדבר עה\"פ (ו, ה)."],["529","23","<b>וכך ככל המשל הזה ויותר מזה לאין קץ</b>: כמה שורות הוא ע\"פ לשון הלקו\"ת תצא שם לח, ריש ע\"ד."],["530","24","<b>והנה תחילת בריאת העולמות</b>: לפיסקא זו ראה לקו\"ת תצא שם לח, ד (עם הוספות)."],["531","25","<b>בכל שעה מתחדש צירוף ש' הוי'</b>: ראה גם לעיל ד\"ה ושננתם פ\"ו. וש\"נ."]]],[2002180212,"כמארז\"ל קדש א\"ע במותר לך והוא בכל שיעור קומה של אדם כו', וזהו וכל קומה לפניך תשתחוה, להשליך נפשו ורצונו מנגד כו', וביטול זה הוא בבחי' חכמה כי בחכמה אתברירו לברר הטוב מהרע ולבטל רצון הרע מפני הטוב בכח החכמה שבנפש, ולכן ארז\"ל קדש א\"ע כו' כי קדש הוא בחכמה כמו קדש לי כל בכור כו'. וע\"י בחי' ביטול זה שבאתעדל\"ת, שמבטל ומסלק א\"ע ורצונו ליבטל אליו ית', אתעדל\"ע להיות ביטול וסילוק עצמיות אור א\"ס ב\"ה שלא יאיר ויתגלה אלא בבחי' צמצום בהעלם אחר העלם בבחי' ישת חשך סתרו, חשך ולא אור. רק למעלה הצמצום הוא בחי' ירידה מעצמותו, ולמטה הצמצום הוא להיפוך דהיינו שלא להוריד ולימשך אחר תאוות הגוף ונה\"ב כו'. וזהו בחי' יו\"ד שבנפש, וע\"י גילוי בחי' יו\"ד שבנפש עי\"ז נמשך מלמעלה גילוי בחי' יו\"ד שהוא בחי' חכ' כו'. ובכלל הוא בחי' יראה עילאה, כי אית יראה ואית יראה<sup data-n=\"532\">26</sup>, אית יראה הוא בחי' יר\"ת וזהו ייראו מה' כל הארץ, ואית יראה שהוא בחי' יר\"ע וזהו יראו את ה' קדושיו כו', את ה' את הטפל שהוא טפל ובטל לעצמות אוא\"ס מכל וכל. וע\"י גילוי בחי' יו\"ד שבנפש עי\"ז נמשך מלמעלה גילוי בחי' יו\"ד שהוא בחי' חכ'.\n<b>וענין</b> הה\"א של ש' הוי' שבנפש<sup data-n=\"533\">27</sup> הוא כי הנה ה' ראשונה הוא בחי' בינה עילאה בחי' התפשטות הה\"א באורך ורוחב ממכ\"ע וסוכ\"ע מן צמצום הנקודה כו', ובנפש הוא התפשטות והתרחבות ההשגה מן ברק המבריק במוח שהוא בחי' נקודה כו' להיות מרחיב דעתו ורוח בינתו בגדולת א\"ס ב\"ה איך שהוא ממכ\"ע וסוכ\"ע בהארה אחת מצומצמת כו', ועי\"ז יהי' ג\"כ ההתפשטות וההתגלות בלב והתלהבות והתלהטות רשפי אש האהבה, וכן שמחת הנפש בה' עושה הוא ע\"י התרחבות ההתבוננות בלב אם הבנים שמחה. ואתעדל\"ת לגילוי בחי' ה' זו היא בחי' תשובה עילאה ממטלמ\"ע (וזהו תשובה תשוב ה') ויצעקו אל ה' בצר להם כי הירידה מאור פניו ית' הוא בבחי' צר בבחי' הארה מועטת ומצומצמת, ובפרט אם ישים אשם נפשו מכל מעשיו דבוריו ומחשבותיו אשר לא לה' המה אשר בהבל בא ובחשך ילך, ואי לזאת ישים אליו לבו רוחו ונשמתו אליו יאסוף לדבקה בו ית' ממש ורוח אייתי רוח ואמשיך רוח כו'. ועד\"ז סובב הולך כל ענין התפלה<sup data-n=\"534\">28</sup> להתבונן בירידת והשתלשלות אור א\"ס ב\"ה בהארה מועטת ומצומצמת בחי' ממכ\"ע וסוכ\"ע עד שיהללו את שם ה' כו' בחי' שם בלבד וישתבח שמך לעד כו' בכדי שעי\"ז יבא לקיום ואהבת בק\"ש את הוי' אלקיך ממש להיות גילוי אוא\"ס ב\"ה ממש, ואותה אנו מבקשים שיהי' בבחי' גילוי ההתפשטות באורך ורוחב בלב ונפש, וזהו והחזירנו בתשובה שלימה לפניך פי' להיות המשכת פניך פנימיותך דהיינו בחי' אוא\"ס ב\"ה ממש וכמ\"ש יאר ה' פניו כו'.",[["532","26","<b>אית יראה ואית יראה . . ייראו מה' כל הארץ .ֿ. יראו את ה' קדושיו</b>: ראה בכ\"ז בארוכה אוה\"ת בשלח ע'תלב ואילך. תס ואילך. סה\"מ תרכ\"ז ע רמז ואילך. וש\"נ. שנט ואילך."],["533","27","<b>וענין הה\"א של ש' הוי' שבנפש</b>: פיסקא זו ושלאחרי' הוא ע\"פ לשון הלקו\"ת תצא שם לט, א."],["534","28","<b>ועד\"ז סובב הולך כל ענין התפלה</b>: ראה בכ\"ז בארוכה לעיל ד\"ה עבדו את ה' בשמחה. וש\"נ."]]],[2002180213,"<b>וענין</b> הוא\"ו ה\"א בנפש הוא להיות גילוי ההמשכה בתומ\"צ בקיום המעשה בפועל ממש, כי התורה היא בחי' וא\"ו קול קורא במדבר פנו דרך ה' להיות המשכת קול התורה קורא דרך ה' וגילוי אורו ית' אפי' בבחי' מדבר שהוא העוה\"ז שיהי' בו כן בקדש חזיתיך המשכת קדש עליון (ועמ\"ש בד\"ה כי תשמע בקול פ' ראה<sup data-n=\"535\">29</sup>), והמשכה זו היינו בה' תתאה היא בחי' המעשה והי' מעשה הצדקה מעשה דייקא וצדקה היא כללות המצות כי כמו שצדקה הוא להחיות רוח שפלים<sup data-n=\"536\">30</sup> כו' כך כללות המצות הן להיות המשכת חיות ואוא\"ס ב\"ה למטה בעולם השפל הגשמי ונגלה כבוד ה' למטה כו' והוא בחי' ה' כי צדק מלאה ימינך שנק' צדק בלא ה' וכשמלאה ימינך התפשטות והמשכת החסד אזי הוא בתוס' ה' צדקה<sup data-n=\"537\">31</sup> (וע' בזהר פ' בחקתי דקי\"ג ע\"ב ובפי' הרמ\"ז שם ובאדר\"ז דרצ\"א סע\"ב ודרצ\"ב ע\"א), והנה גילוי זה שבבחי' המעשה הוא ע\"י בחי' הוא\"ו שהוא ענין ההמשכה כו'.\n<b>וזהו</b> ולא אבה הוי' אלקיך כו' מצד כי הוי' אלקיך שיש בכל נפש בחי' הוי' שהוא ביטול הרצון שלמעלה מן הטעם ודעת כו', וגם בחי' יו\"ד וה' וע\"כ ולא אבה לפי שכך עלה ברצונו כו', והגם שאינו מושג ומובן לנו למה עלה כך ברצונו, כי אם צדקת כו', אך אעפ\"כ זה אנו יודעים שכך עלה ברצונו שיהי' דוקא לו דירה בתחתונים<sup data-n=\"538\">32</sup> ע\"י מעשה המצות כו'.\n<b>ומעתה</b> י\"ל ענין ויהפוך הוי' אלקיך לך את הקללה לברכה כו', הענין הוא דהנה מ\"ש ולא אבה הוי' אלקיך היינו בחי' צדיקים שמקיימין תומ\"צ, וע\"כ ולא אבה. אך ענין ויהפוך את הקללה כו' ענין קללה הוא כמ\"ש בפ' ראה את הקללה אם לא תשמעו אל מצות הוי' אלקיכם, ועכ\"ז ויהפוך הוי' אלקיך כו'.\n<b>ולהבין</b> כ\"ז הנה כתיב שובה ישראל עד הוי' אלקיך כו', והנה כתיב וירא כל העם וירונו ויפלו על פניהם ויאמרו הוי' הוא האלקים הוי' הוא האלקים ב\"פ<sup data-n=\"539\">33</sup>, ולהבין למה כפלו ב' פעמים. והענין הוא כי הוי' הוא האלקים הא' היינו כי הוי' הוא גילוי אוא\"ס ב\"ה, ואלקים הוא בחי' צמצום והעלם כדי שיתהוה מקור לעולמות בע\"ג ונפרדים שנראה העולם ליש ודבר נפרד כו', והוי' הוא האלקים היינו שצריך",[["535","29","<b>ועמ\"ש בד\"ה כי תשמע בקול פ' ראה</b>: לקו\"ת פ' ראה כג, א."],["536","30","<b>שצדקה הוא להחיות רוח שפלים</b>: ראה אגה\"ק ס\"ח (קיב, ב ואילך). סי\"ז (קכה, סע\"א). תו\"א וישב כט, ד. בשלח סג, ב. יתרו סז, ג. סה\"מ תרל\"ג ח\"ב ע' תסה. ועוד."],["537","31","<b>צדק מלאה ימינך . . צדק בלא ה' . . בתוס' ה' צדקה</b>: ראה לקו\"ת נצבים נא, סע\"ג. וראה גם סידור עם דא\"ח עח, ד. שערי אורה כה, ב ואילך."],["538","32","<b>שאינו מושג ומובן לנו למה עלה כך ברצונו . . אעפ\"כ זה אנו יודעים . . דירה בתחתונים</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"א ע' שלח. אוה\"ת בלק ע' תתקצז. סה\"מ תרכ\"ז ס\"ע תנג-ד. וש\"נ. תר\"ל ע' רפט. המשך תרס\"ו ס\"ע ז. סה\"מ תש\"ב ע' 34. לקו\"ש ח\"ו ע' 21. ועוד."],["539","33","<b>ולהבין כ\"ז הנה כתיב שובה ישראל . . הוי' הוא האלקים ב\"פ</b>: הבא לקמן בפיסקא זו מיוסד על ד\"ה שובה ישראל בלקו\"ת דרושים לשבת שובה סד, ג ואילך. סה, ד ואילך."]]],[2002180214,"להמשיך בחי' הוי' בבחי' אלקים שלא יראה העולם ליש ודבר נפרד כו' וכמ\"ש כי שמש ומגן הוי' אלקים, שע\"י המגן הוא גילוי השמש, וכך יהי' הוי' אלקים שיהי' גילוי בחי' הוי' בבחי' אלקים. והוי' הוא האלקים הב' היינו שהוא כאלקים יחשב לגבי למעלה הימנו וזהו ויקרא הוי' הוי' ופסיק טעמא<sup data-n=\"540\">34</sup> בגווייהו, הוי' הא' הוא מ\"ש עד שלא נבה\"ע הי' הוא ושמו בלבד, והוי' הב' הוא בחי' מהוה שמהוה כל העולמות, וע\"כ צ\"ל פסיק טעמא בגווייהו כו' דהיינו צמצום כו'. והנה מי שהעביר את הדרך וחטא על הנפש שפגם באיזה ל\"ת או בביטול מ\"ע כו' הרי א\"א לו להמשיך בחי' הוי' בבחי' אלקים שהרי פגם בש' הוי' כו', כי המצות נק' מצות הוי', וע\"כ צריך להמשיך מלמעלה מש' הוי' והיינו מבחי' הוי' הוא האלקים הב' שהוי' כאלקים יחשב אשר שם כחשיכה כאורה ומשם יכול להיות שזדונות נעשו כזכיות ממש, והוא ע\"י תשובה מעומקא דלבא כו' ויצעקו אל הוי' בצר להם, כי גדול כח בע\"ת דמשכין לי' בחילא יתיר, והיינו ע\"י בחי' ובכל מאדך למעלה מכדי שתוכל נפשו שאת, ועי\"ז ויהפוך הוי' אלקיך לך את הקללה לברכה, שמשם נמשך מחילת וסליחת העוונות וזדונות נעשו כזכיות כו'.\n<b>ובכלל</b> ענין ולא אבה הוי' אלקיך הוא בחי' ר\"ה<sup data-n=\"541\">35</sup> שתוקעין בשופר כדי לערבב השטן שלא ישמעו אליו, אבל אם היו שומעין לו לא הי' יכול להתהפך מזדונות לזכיות, רק שאין שומעין לו מצד כי הוי' אלקיך כו' שהוא בחי' צדיקים כו', וע\"כ צ\"ל בר\"ה בחי' יראה לקבל עליו עומ\"ש כו'. אבל יוהכ\"פ הוא בחי' ויהפוך הוי' אלקיך לך את הקללה לברכה, זדונות נעשו כזכיות ע\"י תשובה, כי יוהכ\"פ בלא תשובה אינו מכפר כו', לפני הוי' תטהרו כו'. וביאר אח\"כ כי אהבך הוי' אלקיך, היינו שגם בבחי' הוי' דלעילא אשר שם כחשיכה כאורה ממש ואם צדקת מה תתן לו כו' עכ\"ז כי אהבך הוי' אלקיך, שם ג\"כ, וכמ\"ש הלא אח עשו ליעקב, היינו שלגבי עצמותו שוין עשו ויעקב לפי שאם צדקת מה תתן לו כו', ועכ\"ז ואוהב את יעקב דוקא, ואת עשו שנאתי לפי שכך עלה ברצונו, וזהו בחי' סוכות שהוא בחי' וימינו תחבקני שהוא אהבה הבאה מלמעלה ע\"י מקיפים דסוכה, והיינו שהמקיפים דסוכה הוא בחי' סוכ\"ע ומשם נמשך ג\"כ בחי' וימינו תחבקני כו'.",[["540","34","<b>וזהו ויקרא הוי' הוי' ופסיק טעמא</b>: ראה בכ\"ז לעיל ע' קיב. וש\"נ."],["541","35","<b>ובכלל ענין ולא אבה . . הוא בחי' ר\"ה</b>: בהבא לקמן עד סוף המאמר ראה גם ד\"ה השקיפה בסה\"מ ה'ש\"ת שם ע' 159 ואילך."]]],[2002180215,"<h3>את ה' האמרת כו'</h3>\n<b>בס\"ד ש\"פ תבא ט\"ל.</b>\n<b>את</b> הוי' האמרת<sup data-n=\"542\">1</sup> היום כו' ולשמור חוקיו ומצותיו, וה' האמירך היום כו' ולשמור כל מצותיו, והקשה באוה\"ח, מה שייך בשבח האמירך שהוא שבח הקב\"ה לישראל שבח דלשמור כל מצותיו, שהרי זה שייך רק בשבח נש\"י להקב\"ה שהוא ענין אומרו ולשמור חוקיו ומצותיו כו' והיינו שהוא בחי' קבעומ\"ש, אבל מה שייך ענין זה בשבח הקב\"ה מה שמשבח לישראל. אך הענין<sup data-n=\"543\">2</sup> יובן בהקדם פי' האמרת שיש בו ג' פירושים הא' מל' שבח ורוממות הב' לשון לבוש כמ\"ש בצע אמרתו ות' בזע פורפירא דילי'<sup data-n=\"545\">3</sup>, הג' לשון אמירה ודבור. ונבין תחילה פי' האמרת<sup data-n=\"544\">4</sup> שפי' רז\"ל<sup data-n=\"546\">5</sup>* ל' שבח אתם עשאוני חטיבה אחת בעולם אף אני אעשה אתכם חטיבה אחת בעולם, אתם עשאוני חטיבה אחת בעולם שמע ישראל ה' אלקינו ה' אחד, אף אני אעשה אתכם חטיבה אחת בעולם ומי כעמך כישראל גוי אחד בארץ, ובשניהם נא' אחד, וצ\"ל מה\"ע אחד. הנה רבו הפי' בתי' אחד, ובכלל יש בו ג' פי' הא' הוא כמארז\"ל במד\"ר<sup data-n=\"547\">6</sup>* אחד אין כיוצא בו (ועמ\"ש במ\"א<sup data-n=\"548\">7</sup> בענין ודברים אחדים שדברו על ה' אחד ועל אחד הי' אברהם), וצ\"ל לכאורה מהו השבח שאין כיוצא בו, והאיך יעלה על לב איש ח\"ו שיש כיוצא בו, גם צ\"ל איך הוא בשבח דהאמירך שהוא השבח שהקב\"ה משבח את ישראל<sup data-n=\"549\">8</sup>, ענין אין כיוצא בו, הב' פי' אחד ע\"ד שארז\"ל במד\"ר<sup data-n=\"550\">9</sup>* מהיכן זכו ישראל לק\"ש ממ\"ת,",[["542","1","<b>את ה' האמרת</b>: מיוסד על ד\"ה זה באוה\"ת תבוא ע' תתרנז-ח. וראה גם שם (כרך ה) ס\"ע ב'סט-ע. וחלקו מיוסד על לקו\"ת שלח מו, ד ואילך [ד\"ה אני ה\"א]. ואוה\"ת האזינו ע' א'תש [ד\"ה ראו עתה]. מאמר זה (עד לקמן פיסקא: ”ועתה י\"ל הפי' השני\" בתוך המאמר דש\"פ נצו\"י) נמצא בשינויים בסה\"מ תרל\"ב ח\"ב ע' תעו ואילך. וכאן הוא עם הגהות נוספות מכ\"ק אדמו\"ר מהר\"ש שנרשמו בס' תרל\"ט [ולהלן יצויין בעז\"ה המקומות שבהם ניתוספו ההגהות]. וראה גם מהדו\"ק של המאמר בסה\"מ תרל\"ב שם ע' תע ואילך. חלק מהמאמר נמצא בשינויים ובתוס' הגהות בסה\"מ תרל\"ו ח\"ב ע' תקפג [ד\"ה ראו עתה]. וראה גם בהמשך תער\"ב ח\"א ע' שפ. עניני המאמר נמצאים בשינויים והוספות בסה\"מ תרע\"ח ע' תיא ואילך. תרפ\"ו ע' קנא ואילך [ד\"ה כל המאריך]. סה\"מ מלוקט ח\"א ע' נב ואילך [ד\"ה מים רבים תשי\"ז]. ד\"ה כנשר יעיר תשכ\"ב. לתחילת המאמר ראה גם ד\"ה את ה' האמרת בהמשך תער\"ב ח\"א ע' שפ.\nהמאמר דתרל\"ב נדפס בקונטרס בפ\"ע (קה\"ת תשכ\"ב) בתוס' הערות ומ\"מ מכ\"ק אדמו\"ר זי\"ע שבאו כאן באותיות בולטות. [בסה\"מ תרע\"ח ובסה\"מ מלוקט שם, נדפסו ג\"כ הערות נוספות מכ\"ק אדמו\"ר זי\"ע על מאמר זה. וגם הערות אלו נכללו כאן].\nוראה גם לקמן הנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע ממאמר זה."],["543","2","<b>אך הענין יובן בהקדים</b>: בהבא לקמן (עד פיסקא: וביאור הענין) ראה אוה\"ת תבוא שם ע' תתרנז-ח."],["545","3","<b>כמ\"ש בצע אמרתו ות' בזע פורפירא דילי'</b>: ראה גם לקמן בהנחות כ\"ק אדמו\"ר מהורש\"ב (ריש ד\"ה את ה' האמרת הב' מש\"פ נצבים) ובהמ\"מ שם."],["544","4","<b>שיש בו ג' פירושים . . ונבין תחילה פי' האמרת</b>: שורות אלו ניתוספו בגוכי\"ק תרל\"ט שם."],["546","5","<b>שפי' רז\"ל</b>: ברכות ו, סע\"א. במדב\"ר פי\"ד, ד."],["547","6","<b>כמארז\"ל במד\"ר</b>: נשא פ\"י, ה."],["548","7","<b>וע' מ\"ש במ\"א</b>: ראה לקו\"ת לג\"פ רד\"ה ויאמר ה' הן עם. [אוה\"ת נח (כרך ו) תתרסה, סע\"א]."],["549","8","<b>שהוא השבח שהקב\"ה משבח את ישראל</b>: תיבות אלו ניתוספו בגוכי\"ק תרל\"ט שם."],["550","9","<b>שארז\"ל במד\"ר</b>: ראה דברים רבה פ\"ב, לא: א\"ל שמע ישראל אנכי ה\"א, נענו כולן ואמרו ה\"א ה' אחד. — ומה שמחלק בפנים לשנים: אנכי — השיבו ה' אלקינו, לא יהי' לך — השיבו ה' אחד. אולי י\"ל שהוא ע\"פ הירוש' (ברכות פ\"א ה\"ה) דעשה\"ד כלולים בק\"ש: אנכי ה\"א — שמע ישראל ה\"א. לא יהי' גו' על פני — ה' אחד. וס\"ל דהמדרש רבה כאן קיצר, וד\"ת כו' ועשירים במק\"א.\n[וראה לקמן במאמר זה הנחת כ\"ק אדמו\"ר מהורש\"ב נ\"ע, פיסקא ד\"ה הנה באחד]."]]],[2002180216,"אמר הקב\"ה שמע ישראל אנכי ה' אלקיך, השיבו ישראל ה' אלקינו, לא יהי' לך כו' השיבו ישראל ה' אחד, ונמצא כי ה' אלקינו ה' אחד הוא קיבול על ב' דברות דאנכי ולא יהי' לך, ופי' הג' בענין אחד שהוא מצוה בפ\"ע, והוא מצות ליחדו שיוצא מפסוק<sup data-n=\"551\">10</sup>* שמע ישראל כו' ה' אחד, והיינו כי ב\"נ אינם מוזהרים על השיתוף כמ\"ש הרמ\"א באו\"ח ססי' קנ\"ו, והגם דכתיב באדה\"ר ויצו, וארז\"ל אין<sup data-n=\"552\">11</sup>* צו אלא כו', מ\"מ לא נצטוו על השיתוף רק ישראל כמ\"ש שמע ישראל כו' ה' אחד שז\"ע מצות לייחדו<sup data-n=\"553\">12</sup>.\n<b>וצ\"ל</b> ההפרש בין עבודת כוכבים ומזלות לבחי' השיתוף<sup data-n=\"554\">13</sup>, הנה ארז\"ל<sup data-n=\"555\">14</sup>* דקרו לי' אלקא דאלקי', והיינו כי הם אומרים רם על כל גוים ה' על השמים כבודו, שלהיותו רם ונשא<sup data-n=\"556\">15</sup>* הוא רק על השמים כבודו אבל הארץ עזב בידי המזלות ומערכות אלקות, כי השפלה לפניו ית' להשפיל א\"ע בעלולים השפלים כמו הארץ וכל אשר בה, וזהו לפי סברתם שהם חושבים שהבריאה היא בבחי' השתלשלות עו\"ע<sup data-n=\"557\">16</sup>*, אבל באמת אינו כן כי המגביהי לשבת המשפילי לראות בשמים ובארץ כתי', שלהיותו מגביהי לשבת לכן הוא משפילי לראות בהשגחה פרטית בשמים ובארץ בשוה, דהן אמת שארז\"ל<sup data-n=\"558\">17</sup>* אין לך עשב מלמטה שאין לו מזל מלמעלה המכה בו ואומר גדל שזהו בדרך השתלשלו' עו\"ע, אבל מ\"מ הבריאה אינו בדרך עו\"ע כלל וקמי' ית' כחשיכה כאורה שוין וכשם שהארץ היא השפלה גם לפי דעתם כן באמת גם השמים הם בחי' השפלה וכמ\"ש היושבי בשמים שהקשו בזהר<sup data-n=\"559\">18</sup>* דהל\"ל היושב בשמים, אלא שזהו בחי' המשכת והשפלת בחי' היו\"ד בבחי' שמים שזה נחשב כמשל הישיבה שע\"י שהאדם יושב עד\"מ הנה עי\"ז נשפל כמלא קומתו כן בחי' המשכת היו\"ד לבחי' שמים נחשב לבחי' השפלה, וכ\"ש לגבי' ית' שכחשיכה כאורה שוין",[["551","10","<b>שיוצא מפסוק</b>: סהמ\"צ להרמב\"ם מ\"ע ב'. הל' יסוה\"ת בתחלתו. ובכ\"מ. וראה ג\"כ סהמ\"צ להצ\"צ מצות אחדות ה'."],["552","11","<b>ויצו וארז\"ל אין</b>: זח\"ג קיא, ב. וראה ג\"כ סנה' נו, ב. זח\"א כז, ב. ובכ\"מ."],["553","12","<b>ה' אחד שז\"ע </b> [ שזהו ענין]<b> מצות לייחדו</b>: תיבות אלו ניתוספו בגוכי\"ק תרל\"ט שם."],["554","13","<b>וצריך להבין ההפרש בין עבודת כוכבים . . לבחי' השיתוף</b>: בהבא לקמן (עד פיסקא: וביאור הענין הנה בזהר) ראה אוה\"ת בראשית (כרך ז) תתשסד, ב ואילך. וראה גם אוה\"ת נח (כרך ג) תרנח, א ואילך. יתרו ע' תשנה. ואתחנן ע' שעג. ד\"ה באתי לגני תשי\"ג. [ובהנסמן לקמן הערה: ענין השיתוף]."],["555","14","<b>הנה ארז\"ל</b>: מנחות קי, א. ועייג\"כ תניא פכ\"ד. ש' האמונה פכ\"ב. דרוש דתער השכירה להצ\"צ (בסו\"ס דרך מצותיך ח\"ב [אוה\"ת נ\"ך (כרך ב) ע' תשסח]). ובכ\"מ."],["556","15","<b>שלהיותו רם ונשא</b>: ראה סידור ח\"ב ד\"ה אד' שפתי [רלז, ב]. סד\"ה הלל (בסו\"ס דרמ\"צ [קנב, א])."],["557","16","<b>שהבריאה היא בבחי' השתלשלות עו\"ע</b>: ראה הגהות לד\"ה פתח אלי' — תרנ\"ח [ע' לח-ט] (הועתק קטע זה ב”התמים\" ח\"א מב, ע\"א ד\"ה וביאוה\"ע. ועיי\"ש ח\"ב ע' פח)."],["558","17","<b>שארז\"ל</b>: ראה ב\"ר פ\"י, ו. זח\"א רנא, א. מו\"נ ח\"ב פ\"י."],["559","18","<b>שהקשו בזהר</b>: ח\"ג רסה, ב."]]],[2002180217,"לפניו ית' ה\"ז ודאי בחי' השפלה, ולכן כמו שגם הם מודים שעל השמים כבודו כן באמת גם בבחי' הארץ וכל אשר בה הוא משגיח בבחי' השגחה פרטיות בכל פרט ופרט בכל נברא, וכמארז\"ל בחולין ס\"פ א\"ט דס\"ג ע\"א ר\"י כי הוי חזי שלך אמר משפטיך תהום רבה, וכי הוי חזי נמלה הוי אמר צדקתך כהררי אל, ופי' רש\"י דאפי' נמלה אית לה חיותה כגדולה, ומשפטיך אף בתהום רבה, שזמנתה שלך לשפוט ולעשות נקמתך בדגת הים להמית המזומנים למות לשון מורי עכ\"ל, ומכאן הביא רבינו זצ\"ל<sup data-n=\"560\">19</sup>* תשו' להאומרים שההשגחה היא רק במין האדם, שהרי גם על דגי הים יש השגחה פרטית להזמין המזומנים למות, וכן במד\"ר פ' וישלח<sup data-n=\"561\">20</sup>* פע\"ט ארז\"ל שגם צפור מבלעדי שמי' לא מתצדיא, שב\"ק יוצא ואומר דימוס או ספקולא, וע' במד\"ר קהלת ומג\"א<sup data-n=\"562\">21</sup>*, ובירושלמי פ\"ט דשביעית, וא\"כ יש השגחה פרטית בכ\"ד, ומ\"ש (חבקוק א' י\"ד) ותעשה אדם כדגי הים כרמש כו' שארז\"ל ע\"ז<sup data-n=\"563\">22</sup>* בע\"ז ד\"ד ע\"א מה דגי הים<sup data-n=\"564\">23</sup> כל הגדול מחבירו בולע כו' כך אלמלא מוראה של מלכות איש את רעהו חיים בלעו ולכן ארז\"ל הוי מתפלל בשלומה של מלכות שאלמלא מוראה איש את רעהו חיים בלעו, אין הכוונה שבלא דין ומשפט כ\"א כמו שפי' רש\"י בחולין גבי שלך, והמופת לזה שהרי הוכיחו מזה בגמ' שגם במין האדם כן הוא ובאדם הם מודים שיש השגחה פרטי', אלא ודאי גם בכ\"ד יש השגחה פרטיות, שהרי במין האדם<sup data-n=\"565\">24</sup> ודאי כו' מ\"מ אנו צריכים להתפלל בשלומה של מלכות ע\"ז כו' וכן הוא גם בשארי מינים כו' שיש השגחה פרטי' בכ\"ד, והעובדים לשמש ולירח או לכל צבא השמים אשר לא צויתי הם אינם מאמינים בזה, וזהו עבודת כוכבים ומזלות שנצטוה אדה\"ר שגם ב\"נ מוזהרים על ד\"ז.\n<b>אבל</b> ענין השיתוף<sup data-n=\"566\">25</sup>* הוא ע\"ד שארז\"ל<sup data-n=\"567\">26</sup>* ג' שותפים יש באדם אב ואם והקב\"ה אב כו' אם כו' והקב\"ה נותן בו נשמה שהעיקר הוא חלק הקב\"ה שהרי בצאת הנפש",[["560","19","<b>רבינו זצ\"ל</b>: אדמו\"ר הזקן. וראה רשימות הצ\"צ לתהלים (יהל אור) לו, ז סק\"ג [ע' קלב]."],["561","20","<b>וכן במד\"ר פ' וישלח</b>: להעיר מקהלת יעקב מע' השגחה. וי\"ל דלכן תשובה נצחת הביא רבנו מש\"ס חולין דוקא."],["562","21","<b>במד\"ר קהלת ומג\"א</b>: קה\"ר פ\"י, ח. מג\"א רבה פ\"ג, ז."],["563","22","<b>שארז\"ל ע\"ז</b>: ולהעיר ממו\"נ ח\"ג ספי\"ז."],["564","23","<b>שארז\"ל ע\"ז בע\"ז ד\"ד ע\"א מה דגי הים</b>: בסה\"מ תרל\"ב שם: שארז\"ל ע\"ז מה דגי הים כל הגדול מחבירו בולע כו' אין הכוונה כו'. [וכל השאר כאן הוא הוספה בגוכי\"ק תרל\"ט]. וראה הערה לקמן בסמוך. לכללות ענין המבואר כאן בענין השגחה פרטית — ראה גם בלקו\"ש ח\"ח ע' 277 ואילך [ונדפס גם באגרות קודש ח\"א ע' קסח. וראה ג\"כ שם ח\"ב ע שצד]."],["565","24","<b>בכ\"ד יש השגחה פרטיות, שהרי במין האדם</b>: בסה\"מ תרל\"ב שם: בכ\"ד יש השגחה פרטית, וזהו שארז\"ל הוי מתפלל בשלומה של מלכות שאלמלא מוראה איש את רעהו חיים בלעו, שהכוונה הוא ג\"כ כמו שפי' רש\"י בחולין, שהרי במין האדם. [ובס' גוכי\"ק תרל\"ט כאן העביר קולמוס על שורות אלו. וראה הערה הקודמת]."],["566","25","<b>ענין השיתוף</b>: ראה בכ\"ז סהמ\"צ להצ\"צ מצות מילה. שם מצות אחדות ה'. ד\"ה אנכי בספר תרכ\"ו [ע' נג]. ד\"ה מי כמוכה תרכ\"ט [סה\"מ תרכ\"ט ע' קנה]. ד\"ה מי כמוכה תרל\"ז. ובכ\"מ."],["567","26","<b>ע\"ד שארז\"ל</b>: נדה לא, א. קדושין ל, ב."]]],[2002180218,"מן הגוף נשאר חלק אב ואם כאבן דומם שכל איברי הגוף<sup data-n=\"568\">27</sup> אינם פועלים מאומה, ונמצא כי אינם שותפים שוים, וגם כי בחלק האב ואם באמת העיקר הוא הקב\"ה שהרי ארז\"ל<sup data-n=\"569\">28</sup>* ע\"פ אין צור כאלקינו אין צייר כאלקינו שצר צורה בתוך צורה, והרי אין האב ואם יודעים מאומה איך נצטייר הולד מהטפה רק כאשר משתהה הטפה בבטן האם ט' חדשים ברצונו של הקב\"ה מצטייר ממנה ציור הולד ברמ\"ח אברים מגודלים, ונמצא הרי רובא ככולו הוא חלק הקב\"ה כו' ומ\"מ קראן שותפים כאמרם ז\"ל ג' שותפים כו' וצוה לכבד אותם כמ\"ש כבד את אביך ואת אמך הוא מפני כי עכ\"פ יש להם קצת שותפות שהרי הם בעלי בחירה עכ\"פ, ואם לא יקח אשה לא יוליד, ונמצא הגם כי חלקם הוא קטן מאד מ\"מ מאחר שיש להם קצת שותפות קראן שותפים, וע\"ד שארז\"ל<sup data-n=\"570\">29</sup> כל האומר ויכולו כאילו נעשה שותף להקב\"ה במעשה בראשית, נשמע מזה עכ\"פ דמי שאין לו הבחירה חפשית שודאי אינו שייך כלל לקרותו בשם שותף, כמו עד\"מ הארץ שממנה יוצאת לחם שזהו ע\"י שזורעין בה וכשיורד גשם על הארץ מצמיח מפני כח הצומח אשר מלובש בארץ, האם נאמר<sup data-n=\"571\">30</sup> שלהארץ יש שותפות בצמיחה זו, או כמו ממגד תבואות שמש וממגד גרש ירחים האם נאמר שמפני שירידת השפע נמשך דרך בהם יש להם שותפות, ודאי אינו כן שהרי הם כגרזן ביד החוצב בו שא\"א לומר שהגרזן הוא שותף במלאכה זו שחוצב האבנים מן ההר אלא הוא כלי שבו וע\"י חוצבים מן ההר, אבל לא נערוך לו המעלה שיהי' שותף עם האדם החוצב בו, והיינו להיותו אינו בעל בחירה כלל, כן השמש והירח וכל צבא השמים ומערכות אלקות המשפיעים חיות ברצון הבורא הנה הם רק שלוחי השפע שע\"י עובר השפע והוא כמארז\"ל הנ\"ל שאין לך עשב כו' שאין לו מזל כו' אבל הנה בחי' המזל שהוא מקור המשפיע החיות להעשב הצומח למטה, הנה הוא כגרזן ביד החוצב בו שאינו בעל בחירה כלל, ולכן א\"א לתארו במעלת השיתוף כלל. אך הנה על דבר זה נצטוו ישראל לבד כמ\"ש שמע ישראל כו' ה' אחד<sup data-n=\"572\">31</sup>, אבל ב\"נ אינם מצווים על השיתוף לפ\"ד הרמ\"א הנ\"ל שנמשך אחר הר\"ן והתוס'<sup data-n=\"573\">32</sup>*, והיינו לפי שיצב גבולות עמים למספר בנ\"י ע' נפש יוצאי ירך יעקב והם מקבלים ההשפעה מע\"ש, ולכן לא נצטוו על דבר זה, אבל ה' אחד הוא מצות לייחדו הוא אזהרת השיתוף שלא לשתף שום דבר עם ש\"ש כלל, וה\"ז כמ\"ש וידעת היום והשבות אל",[["568","27","<b>שכל אברי הגוף</b>: כן תוקן בגוכי\"ק תרל\"ט. ובתרל\"ב שם: שכלי השכל. [וראה לקמן בהנחת כ\"ק אדמו\"ר מהורש\"ב נ\"ע: ואפי' חושים המעולים כמו שכל וכדומה מסתלקים ממנו]."],["569","28","<b>שהרי ארז\"ל</b>: ברכות י, א."],["570","29","<b>וע\"ד שארז\"ל . . שותף להקב\"ה במע\"ב</b>: תיבות אלו ניתוספו בגוכי\"ק תרל\"ט שם."],["571","30","<b>האם נאמר שלארץ יש שותפות בצמיחה זו</b>: בסה\"מ תרל\"ב שם (ע' תעט) נוסף כאן הגה\"ה מגוכי\"ק אדמו\"ר מהר\"ש בשולי הגליון."],["572","31","<b>כמ\"ש שמע ישראל כו' ה' אחד</b>: בסה\"מ תרל\"ב שם נוסף כאן הגה\"ה."],["573","32","<b>אחר הר\"ן והתוס'</b>: בד\"ה מי כמוכה הנ\"ל מציין לתוד\"ה שמא בבכורות (ב, א) וד\"ה אסור בסנה' (סג, ב), ר\"ן ספ\"ק דע\"ז, רי\"ו ני\"ז ח\"ה, ואשר בשו\"ת ושב הכהן סל\"ח ושו\"ת שער אפרים סכ\"ד נחלקו ע\"ז. — ועייג\"כ נו\"ב מהד\"ת חיו\"ד סקמ\"ח. פ\"ת ליו\"ד סקמ\"ז סק\"ב. פרמ\"ג בשפתי דעת סו\"ס סה. שדי חמד פאת השדה כללים אות ג' ס\"ו סקי\"א ובספרים שהובאו שם."]]],[2002180219,"לבבך כי הוי' הוא האלקים בשמים ממעל ועל הארץ מתחת אין עוד שאין זולתו כלל, וכדכתיב ראו עתה כי אני אני הוא ואין אלקים עמדי כו'.\n<b>וביאור</b> הענין הנה בזהר<sup data-n=\"574\">33</sup> הקשה<sup data-n=\"575\">34</sup>* מהו ראו עתה, מאחר שאני אני הוא קאי על לעתיד, ומהו ראו עתה. אך הענין דכתיב אני ראשון ואני אחרון, שלעתיד יתחברו ב' בחי' אני ועכשיו בכ\"מ שנז' אני הוא רק פ\"א אני אבל לעתיד יהי' ב\"פ אני כא' כו'. והענין יובן בהקדם שרש ענין<sup data-n=\"576\">35</sup> ההפרש בין ג\"ע לתחה\"מ* בדרך קצרה, שג\"ע הוא תענוג הנשמות בלא גופים, ויש ב' בחי' ג\"ע, ג\"ע התחתון וג\"ע העליון, ויש נשמות שאינם באים כלל לבחי' ג\"ע העליון כלל, והגם כי בכל ג\"ע יש כמה מדרגות שע\"ז ארז\"ל<sup data-n=\"577\">36</sup>* ת\"ח אין להם מנוחה כו' שנאמר ילכו מחיל אל חיל, מ\"מ בד\"כ הם רק ב' בחי' ג\"ע העליון והתחתון, ותחה\"מ הוא רק בחי' אחת, והגם כי גם בתחה\"מ יש כמה חילוקי מדרגות שכ\"א נכוה מחופתו<sup data-n=\"578\">37</sup>* של חבירו, מ\"מ בכלל הוא רק בחי' א' ולא כמו ג\"ע שיש בכללו ב' בחי' ג\"ע, וגם יהיו נשמות בגופים דוקא, ולכאורה צ\"ל מה\"ע שיצטרכו הנשמות שיושבים בג\"ע יותר מג\"א שנה כמו האבות ומשה וכדומה לירד להתלבש בגוף בשביל לבוא לעונג שיתגלה בתחה\"מ, ולמה היתה כזאת מלפניו ית' שיצטרכו להתלבש שנית בגוף, גם מה יתרון ויקר ענג זה כ\"כ שכדאי כ\"ז בשבילו כו'. הענין הוא דג\"ע הוא בחי' תענוג הנשמות ממה שלומדים בג\"ע הלכות התורה ברוחניות והרי הם משיגים הארה מבחי' זיו השכינה, שמזה נמשך הענג שהוא ענג נפלא עד אין קץ, ואמנם יש מבחי' התענוג מה שנפל בשה\"כ, והוא בלעו\"ז, וזהו שארז\"ל<sup data-n=\"579\">38</sup>* כשראו כרך גדול של רומי, שר\"א בכה ור\"ע שחק, שבכיות ר\"א הי' על ירידת התענוג כ\"כ להתלבש בדברים גשמי' כו' ור\"ע שחק דאם לעוברי רצונו כך לעושי רצונו עאכ\"ו, דהנה יש מלאכים<sup data-n=\"580\">39</sup>* שנק' בשם קרבים כמ\"ש וכל קרבי את שם קדשו, שכמו הקרבים מבררים המאכל שהמובחר יתעלה להיות חיות למוח ולב, והפסולת יודחה לחוץ, כן המלאכים אלו הם המבררים ירידת השפע, וכן בעליות המדרגות מלמטלמ\"ע כמ\"ש במ\"א בענין עולים",[["574","33","<b>וביאור הענין הנה בזהר</b>: הבא לקמן (עד פיסקא: ובזה יובן ל' המד\"ר) מיוסד על ד\"ה אני ה\"א בלקו\"ת שלח שם מו, ד ואילך. ואוה\"ת האזינו ע' א'תש-א. וראה גם מאמרי אדה\"ז תק\"ע ע' קיח ואילך."],["575","34","<b>בזהר הקשה</b>: ח\"ב קח, ב. — להעיר מפדר\"א רפל\"ד."],["576","35","<b>שורש ענין ההפרש בין ג\"ע לתחה\"מ</b>: ראה תו\"א יתרו עג, ב. וככה תרל\"ז פ\"ה ואילך. ד\"ה זה היום תרס\"ו. ובכ\"מ. וראה גם סה\"מ תרל\"ב ח\"א ע' קכא ואילך. וש\"נ. ס\"ע רנח ואילך]."],["577","36","<b>שע\"ז ארז\"ל</b>: ברכות בסופה."],["578","37","<b>נכווה מחופתו</b>: ב\"ב עה, א. ומוכח שם בסוגיא (ובקרא) דזהו לנשמות בגופים היינו בתחה\"מ — אף שגם בג\"ע יש הענין דחופה ונכווה כו' (זח\"א לט, א ועוד)."],["579","38","<b>וזהו שארז\"ל</b>: ראה מכות בסופה. וראה תו\"א ר\"פ בשלח [סא, ג]. שם ר\"פ תצוה [פא, סע\"א-ב]. ובתו\"ח שם ע' שמו. [בתו\"ח הוצאת תשס\"ג הוא בח\"א קלה, סע\"ג ואילך]."],["580","39","<b>יש מלאכים</b>: ראה בכ\"ז ד\"ה יסובבנהו לאדה\"ז (ברוקלין תשכ\"ב). [סה\"מ תקס\"ו ע' שסא. שצג]. וראה לקו\"ת ר\"פ צו [ז, ב]. שם פ' שלח ד\"ה ענין הנסכים פ\"ב [מא, ד]. ועוד."]]],[2002180220,"ויורדים<sup data-n=\"581\">40</sup>* בו בסולם דתורה ותפלה כו', וכן להאדם ניתן העבודה לברר את בחי' התענוג הזה מירידתו, וכל ענין התלבשות הנשמה בגוף הוא בשביל זה שעי\"ז יתברר בחי' התענוג ויהי' יתרון האור מתוך החשך דוקא, ועיקר גילוי דבר זה יהי' לעתיד כי בד\"כ ההפרש<sup data-n=\"582\">41</sup>* בין ג\"ע לתחה\"מ שג\"ע הוא בחי' ממכ\"ע שיש בו חילוקי מדרגות לכן יש ב' בחי' ג\"ע התחתון<sup data-n=\"583\">42</sup> והעליון, והגם כי כדאי כל יסורי גיהנם בכדי לבוא לגילוי השגת התענוג גם מבחי' ג\"ע התחתון, ונודע כי יסורי איוב<sup data-n=\"584\">43</sup>* ע' שנה אינם כדאי נגד שעה א' מן הגיהנם ומ\"מ כדאי כל יסורי גיהנם כמארז\"ל מוטב דלידייני'<sup data-n=\"585\">44</sup>* כו' בשביל גילוי ג\"ע שי\"ל גם בשביל בחי' התחתונה שבג\"ע התחתון, והיינו מפני היותו תענוג נפלא מאד עד אין קץ, מ\"מ הוא רק מבחי' ממכ\"ע שיש בו חילוקי מדרגות עד שנחלק לב' בחי' התחתון והעליון כו', אבל תחה\"מ הוא בחי' א' להיותו מבחי' אוא\"ס הסוכ\"ע ששם אינו שייך מעלה ומטה כמו ביושר, ולכן היא בחי' אחת בד\"כ רק שגם בבחי' החופה אין כל המקיפים שוים כו', אבל מ\"מ הוא בחי' א' בד\"כ ויהי' הגילוי בארץ שלמטה דוקא להיות כי נעוץ תחלתן בסופן שבסוף דוקא שהוא בחי' ארץ שבמעשה שמים קדמו כו' שם יהי' גילוי זה להיות כי בסוף דוקא יש כוונת נעיצת התחילה יותר מכמו היותו בבחי' ראש המתפשט כמ\"ש בד\"ה ועמדו רגליו<sup data-n=\"586\">45</sup>* כו', ולכן תחה\"מ בארץ דוקא להיות כי בארץ דוקא יהי' גילוי הארת בחי' סוכ\"ע כו', וזהו ענין אני אני שיהי' לעתיד שיתחברו ב' בחי' אני, ויהי' רק מדרגה א' בד\"כ, ורק עכשיו הוא העבודה שזהו דכתיב ראו עתה שצריכים לראות עתה בבחי' היום לעשותם שמאיר ג\"כ הארת הסובב לכן יוכל להכין בעוה\"ז ע\"י העבודה שיזכה לעתיד לבחי' הגילוי דחיבור ב' בחי' אני, וזהו שארז\"ל במד\"ר ס\"פ בא ספי\"ט אבל לעתיד אני לבדי, י\"ל ע\"ד ונשגב ה' לבדו ביום ההוא שביום ההוא יהי' גילוי מבחי' לבדו היינו בחי' הוא והוי' כמו שהם בבחי' לבדך כמ\"ש בד\"ה כי מי נח<sup data-n=\"587\">46</sup>*, והוא ענין יתרון האור שמתוך החשך דוקא.\n<b>וביאור</b> הענין צ\"ל ההפרש בין<sup data-n=\"588\">47</sup> שרפים לחיות ואופנים*, שנת' בד\"ה כי מי נח הנ\"ל שהשרפים אומרים קדוש שהוא מחמת ההשגה<sup data-n=\"589\">48</sup> שאימא מקננא בכורסי', ולכן הם עומדים ממעל לו* ע\"ש, אבל החיות והאופנים הם ברעש גדול,",[["581","40","<b>כמ\"ש במ\"א בענין עולים ויורדים</b>: ראה רד\"ה ויחלום תש\"ח (קונטרס נב). [סה\"מ תש\"ח ע' 80. וראה לקו\"ת דרושים ליוהכ\"פ סח, ב. אוה\"ת ויצא (כרך ה) תתמא, ב. תתמג, ב]."],["582","41","<b>בד\"כ ההפרש</b>: ראה בכ\"ז תו\"א ד\"ה להבין כו' האבות ה\"ה המרכבה [עג, ב]. לקו\"ת שלח (מו, ד). ובכ\"מ."],["583","42","<b>כי כדאי כל יסורי גיהנם בכדי לבוא . . ג\"ע התחתון</b>: בכת\"י המעתיק הי' רשום: ג\"ע התחתון והעליון. ובגוכי\"ק העביר קולמוס למחוק תיבת: והעליון."],["584","43","<b>ונודע כי יסורי איוב</b>: הקדמת הרמב\"ן לאיוב הובא באגה\"ת פי\"ב."],["585","44","<b>כמארז\"ל מוטב דלידייני'</b>: חגיגה טו, ב. ראה לקו\"ת בשלח ד\"ה ראו פ\"ב. [א, ד]."],["586","45","<b>כמ\"ש בד\"ה ועמדו רגליו</b>: סה\"מ תר\"ל ע' שכ. וראה גם סה\"מ תרל\"ב ח\"ב ע' שסז. וש\"נ."],["587","46","<b>בד\"ה כי מי נח</b>: דשנת תרל\"ב (לא נדפס לע\"ע). [נדפס בסה\"מ תרל\"ב ח\"ב ע' תס]."],["588","47","<b>ההפרש בין שרפים לחיות ואופני'</b>: ראה לקו\"ת במדבר כח, ד. שם מז, א. ובכ\"מ."],["589","48","<b>מחמת ההשגה . . הם עומדי' ממעל לו</b>: ראה לקו\"ת חקת רד\"ה אז ישיר [סב, ג]. ושם אמור ד\"ה ונקדשתי פ\"ה [לב, ב] באו\"א."]]],[2002180221,"ע' בתוס' ד\"ה ברוך בחולין דצ\"ב ע\"א, שהרעש הוא מחמת העדר השגתם שלהיותם אינם משיגים לכן הם ברעש ע\"ד בן כפר שראה כו' והוא מחמת הסתר היצי' לגבי הבריאה, שרק זו\"נ מקננא ביצי', וכ\"ש אופנים דעשי' שהרעש הוא עוד יותר גדול<sup data-n=\"590\">49</sup>, להיותם מרוחקים יותר כמ\"ש אופן א' בארץ דתרגומו מלרע, וכ\"ש בחי' התענוג שנפל בשבה\"כ בדברים גשמי' שהריחוק אינו בערך כלל נגד ריחוק הנ\"ל דבי\"ע, שזה לא נתברר עדיין, וכנודע המשל מהפלת החומה שכל הגבוה יותר נופל למטה יותר, עכ\"פ יצא לנו מזה שמחמת הסתר הגשמי' שמסתתר על בחי' התענוג שיש בו צ\"ל הרעש ביתר שאת ויתר עז על בחי' הרעש דחיות ואופנים ג\"כ, ורעש אותיות שער שעי\"ז יומשך בחי' זה השער כו' כי יש שער בימין<sup data-n=\"591\">50</sup>* ושער בשמאל שער בימין הוא בחי' זה השער לה', ושער בשמאל הוא בחי' שער רישי' כעמר נקי, וכמו השערה שיונק מהמוח הגם שיניקתה הוא מהמוח, מ\"מ חיותה מצומצמת מאד שהרי כשגוזזי' השערות לא יש שום כאב כלל וכלל והיינו להיות כי החיות אשר בהם הוא מצומצם מאד, ועד\"ז יובן בנמשל דכתיב קווצותיו<sup data-n=\"592\">51</sup> תלתלים תלי תלים של הלכות* שקאי על הלכות התורה, דכתיב בהם ג\"כ סלסלה ותרוממך שע\"י בירור וסלסול השערות להפריד ההלכות שלא יהי' שום קושיא מזה לזה עי\"ז מתרומם נפש האדם, ואמנם שרש שרשן של הלכות שבתורה הוא שאורייתא מחכמה נפקת, ובחי' הארת התענוג שמאיר בחכמה הוא ע\"י בחי' שערות שאבא יונק ממזלא הוא מזל הח' ונוצר שכל בחי' השערה הוא הארה מצומצמת וכנ\"ל במשל כו', אבל בחי' זה השער הוא כמשל השער שהוא שער המשמש כניסה ויציאה, ושער זה הוא עוד שער רחב עד\"מ שער החצר שהכל יכולים לעבור דרך בו, וע\"י בחי' בירור התענוג שנפל בשה\"כ עד שנתלבש בדברים גשמי' דעשי' שמקבלים חיות משמרי אופנים ודרך בחי' המזלות שמשפיעים לכל עשב בפרט, ועושים מזה מצוה אשר צונו עד\"מ ציצית מצמר גשמי ותפילין מקלף גשמי, וסוכה מסכך הגשמי, וד' מינים שבלולב מצמחים הגשמים, וע\"י עשיית המצוה בדבר גשמי הלזה מגביהי' אותה שתעלה מנפילתה וקבלת חיותה מק\"נ להכלל ולהבטל בתענוג העצמי, שזהו שמברכין על המצות אשר קדשנו אשר הוא בחי' הענג העצמי, וע\"י בחי' בירור זה יזכה המברר ועושה המצוה לגילוי בחי' זה השער שהוא שער רחב הוא בחי' רחבה מצותך מאד שהם כלים רחבים לקבל גילוי בחי' מאד העליון שז\"ע אדם אדמה לעליון שנת' בד\"ה קרוב ה' לכל קוראיו וביאוריו<sup data-n=\"593\">52</sup>*, וז\"ע יתרון אור מתוך החשך דוקא, וע\"ד",[["590","49","<b>וכ\"ש אופנים דעשי' שהרעש הוא עוד יותר גדול</b>: בסה\"מ תרל\"ב שם (ע' תפא) נוסף כאן הגה\"ה מגוכי\"ק אדמ\"ר מהר\"ש בשולי הגליון. לכללות המבואר כאן ראה גם בסה\"מ תרל\"ג ח\"א ע' יג שמביא מהמאמר דתרל\"ב: והיינו ע\"ד שנת' בד\"ה את ה' האמרת (ל\"ב) בענין והאופנים וחיוה\"ק ברעש גדול שענין הרעש שלהם הוא מחמת העדר ההשגה ע\"ד בן כפר כו'. וראה גם שם ע' כ."],["591","50","<b>כי יש שער בימין</b>: ראה בכ\"ז לקו\"ת שלח (מז, א ואילך)."],["592","51","<b>קווצותיו תלתלים תילי תילים של הלכות</b>: שה\"ש ה, יא. ובמדרש רבה שם."],["593","52","<b>בד\"ה קרוב ה' . . וביאוריו</b>: דשנת תרל\"ב (לא נדפס לע\"ע). [נדפס בסה\"מ תרל\"ב ח\"ב ע' תב. תה]."]]],[2002180222,"שאין אדם רואה<sup data-n=\"594\">53</sup>* מתוך הלבן אלא מתוך השחור שבעין, שע\"י שהחשך מכסה על בחי' התענוג המלובש בו בבחי' נפילה ע\"י הסתר זה נעשה הרעש גדול מאד יותר הרבה מבחי' הרעש דאופנים שהרעש שלהם הוא רק מצד היותם בעשי' ע' בכהאריז\"ל ובלק\"ת בד\"ה האזינו השמים השלישי<sup data-n=\"595\">54</sup>* בסופו, וכ\"ש בחי' התענוג העצום שמוסתר בדברים הגשמי' ולכן מבחי' בירור דרעש זה נעשה שער הוא בחי' זה השער בחי' שער רחב עצמות לובן התענוג כו' שלמעלה הרבה מבחי' העונג דח\"ס הנמשך ע\"י השערות כנ\"ל.\n<b>ובזה</b> יובן ל' המד\"ר הנ\"ל אני לבדי כי י\"ל שמלבד שע\"י בירור הניצוצות שנפלו בשבה\"כ מעולם התהו יורשים בחי' אורות דתהו הנה עי\"ז מאיר ומתגלה מה שלמעלה מתהו ותיקון, והיינו כי התהו הי' בונה ע\"מ לסתור, והשבירה הי' שהי' סותר ע\"מ לבנות בכוונה וכאשר מבררים בבחי' התיקון שהוא לעשות לתקן בתיקוני המצות עד\"מ שופר מקרן גשמי וד\"מ שבלולב מצמחים הגשמי' הרי ע\"י עשיית מצות אלו וכדומה להם משלימים את בחי' הרצון שסתר ע\"מ לבנות בכוונה וע\"י השלמת רצון זה שנתאוה שיהי' ממעשה התחתונים דוקא עי\"ז יתגלה בחי' שלמעלה מתהו ותיקון, וזהו אני לבדי בחי' הוא וש' הוי' כמו שהם בבחי' לבדך כנ\"ל, שנת' ענינו בד\"ה כי מי נח הנ\"ל, וכ\"ז צריכים לראות בעבודה דעכשיו, וזהו ראו עתה השגה בבחי' ראי' איך שיהי' חיבור ב' בחי' אני ע\"י הבירורים דבחי' התענוג דעכשיו כו'.\n<b>ובכ\"ז</b> יובן שרש ענין האמרת ל' שבח אתם עשאוני חטיבה אחת כו' שמע כו' ה' אחד, שלפי המד\"ר שקאי על קיבול ב' דברות דאנכי ולא יהי' לך, שהם כלליות התרי\"ג מצות<sup data-n=\"596\">55</sup> כי תרי\"ג מצות* ניתנו כו' אנכי ולא יהי' לך מפי הגבורה שמענו, ותרי\"א כמנין תורה צוה לנו משה, וע\"י בירור המצות נשלם רצונו ית' שאמר ונעשה רצונו כו' וה\"ז שבח גדול, וכ\"ש לפי הפי' הג' שה' אחד הוא לרבות ענן השיתוף שזהו עוד יותר מבחי' אנכי ולא יהי' לך שזהו רק אזהרת עבודת כוכבים ומזלות הם בחי' שמש וירח כו' אשר לא צויתי, וה\"ז שבח יותר מקיום שארי מצות כו'.",[["594","53","<b>שאין אדם רואה</b>: להעיר מלקו\"ת האזינו סד\"ה כנשר יעיר [עח, ג]."],["595","54","<b>ובלק\"ת בד\"ה האזינו השמים השלישי</b>: עז, ב. וראה גם שם עד, ד ואילך."],["596","55","<b>תרי\"ג מצות</b>: מכות כג, סע\"ב. ושם."]]],[2002180223,"<h3>[את ה' האמרת] ומעתה צ\"ל פי' הא' (ב)</h3>\n<b>בס\"ד (ש\"פ נצו\"י).</b>\n<b>ומעתה</b> צריך להבין<sup data-n=\"597\">1</sup> פי' הא' שאחד הוא אין כיוצא בו שלכאורה צ\"ל מה\"ע השבח שאין כיוצא בו והאיך יעלה על לב איש ח\"ו שיש כיוצא בו. אך הענין הוא דצ\"ל מ\"ש ואתה הוא ושנותיך לא יתמו שגם בזה צ\"ל איך שייך לומר ענין ושנותיך הוא בחי' הזמן וגבול בהבורא ית' שהוא בלתי בעל גבול, ואומרו אח\"כ לא יתמו, ותי' הרשב\"א<sup data-n=\"598\">2</sup> שלהיות הנברא הוא בע\"ג לכן א\"א לו להשיג ענין בחי' בלתי בע\"ג, כ\"א ע\"י שיתארו לו ענין הגבול שאינו תמה ע\"ז ומבין בהגבלת שכלו המוגבל<sup data-n=\"599\">3</sup>, ואח\"כ אומרים שהוא זמן ארוך כ\"כ עד שהוא בבע\"ג כו', וה\"ז כדי לשבר את האוזן, וע\"ד דכתיב עיני ה', אזני ה', תהי נא אזניך קשובות לקול תחנוני כו'.\n<b>אך</b> י\"ל באו\"א, והוא כי הנה נודע שענין הזמן הוא בבחי' מל' כל עולמים, שבזה שייך זמן עבר הוה ועתיד חלוקים בג' תי' מלך מלך ימלוך כו', וזהו ענין שארז\"ל<sup data-n=\"600\">4</sup>* יומו של הקב\"ה אלף שנה הכוונה כי יחידות עשירות מאות הוא בבי\"ע, ואלפים הוא בבחי' מ' מל' כל עולמים דאצי'<sup data-n=\"601\">5</sup>, אבל למעלה מבחי' זו<sup data-n=\"602\">6</sup> לא יש בחי' הזמן כלל, וסדר זמנים הוא למעלה מבחי' הגבלת הזמן<sup data-n=\"603\">7</sup>, ומ\"מ א\"א לומר שלא יש כלל בחי' שרש ומקור לזמן זה, שהרי בעה\"ק<sup data-n=\"604\">8</sup>* אמר שאם אתה אומר שהוא ית' בבע\"ג ואין לו כח בגבול הרי אתה מחסר שלימותו, ונת' מזה בכ\"ד ששרש בחי' ההגבלה הנמצא ממנו תחלה הוא בחי' כלים דנר\"נ דאצי'<sup data-n=\"605\">9</sup>, ולתווך כל הפי' בזה הוא בחי' ל' כלים דז\"א דאצי', וזהו שרש<sup data-n=\"606\">10</sup> ענין ש' שדי, אבל ש' הוי' שהוא הי' הוה ויהי' כאחד הוא בחי' בבע\"ג לגמרי כו' למעלה משרש ומקור הזמן לגמרי, ומצד בחי' אוא\"ס",[["597","1","<b>ומעתה צריך להבין</b>: הוא המשך לד\"ה את ה' האמרת היום שלפני\"ז. וראה לעיל בהמ\"מ שם. מכאן עד פיסקא ”ועתה י\"ל הפי' השני\" נמצא בשינויים בסה\"מ תרל\"ב ח\"ב ע' תפג-תפה.\nמאמר זה נמצא ג\"כ לקמן בהנחת כ\"ק אדמו\"ר מהורש\"ב נ\"ע, ומתחיל: את ה' האמרת.\nהבא להלן (פיסקא א' וב') הוא מיוסד על ד\"ה את ה' האמרת באוה\"ת דברים (כרך ה) ע' ב'סט. והתוכן נמצא גם בסה\"מ תרל\"ב ח\"ב ע' תעד-ה."],["598","2","<b>ותי' הרשב\"א</b>: שו\"ת ח\"א סתי\"ח."],["599","3","<b>ומבין בהגבלת שכלו המוגבל</b>: תיבות אלו ניתוספו בגוכי\"ק תרל\"ט."],["600","4","<b>ענין שארז\"ל</b>: ב\"ר פ\"ח, ב. ויק\"ר רפי\"ט. מדרש תהלים צ. וראה ג\"כ סהמ\"צ להצ\"צ מצות האמנת אלקות בסופה."],["601","5","<b>יחידות עשירות . . בבי\"ע ואלפי' . . דאצי'</b>: ראה לקו\"ת ר\"פ ברכה [צג, א]. ביאוה\"ז ואוה\"ת ר\"פ ח\"ש [ביאוה\"ז לאדהאמ\"צ יב, ג. אוה\"ת חיי\"ש ק, ב (בענין מאה עשרים)]. רשימות תהלים להצ\"צ צ, ד ס\"ק ד-ה [ע' שכא-ב]."],["602","6","<b>אבל למעלה מבחי' זו</b>: תיבת ”למעלה\" ניתוסף כאן בגוכי\"ק בס' תרל\"ט. וחסרה תיבה זו בסה\"מ תרל\"ב שם."],["603","7","<b>וסדר זמנים הוא למעלה מבחי' הגבלת הזמן</b>: תיבות אלו ניתוספו בגוכי\"ק תרל\"ט שם."],["604","8","<b>שהרי בעה\"ק</b>: ח\"א פ\"ח."],["605","9","<b>ונת' מזה בכ\"ד ששורש בחי' ההגבלה . . הוא בחי' כלי' . . דאצי'</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' קפח. ח\"ב ע' תמ ואילך. דרמ\"צ קסט, א. אוה\"ת ויקרא (כרך ג) ע' תתפה. אוה\"ת ענינים ע' רעג ואילך."],["606","10","<b>וזהו שורש</b>: ראה בכ\"ז ד\"ה ויצוום וביאורו (באוה\"ת ס' שמות). [אוה\"ת וארא ע' ר-רא. וביאורו שם ע' ריב. וע' קנד ואילך]."]]],[2002180224,"דש' הוי' הי' יכול להתהוות עולמות הא\"ס עד אין שיעור כו', רק בחי' ש' שדי הוא שאמר לעולמו די כו', ומ\"מ כתיב ה' מלך ה' מלך כו' הרי מתלבש בחי' ש' הוי' בבחי' ש' שדי מקור הזמן דבחי' מלך מלך ימלוך<sup data-n=\"607\">11</sup>, וזהו אין כיוצא שיהי' בלתי בע\"ג ובחי' הגבול כאחד, ונמצא זהו כענין שאמרו נמנע הנמנעות<sup data-n=\"608\">12</sup>, להוציא מדעת האומר שרוכב ובלתי רוכב זהו נמנע גם בחק הבורא כ\"א שנמנעו הנמנעות ויכול להיות שני הפכים כאלו רוכב ובלתי רוכב כאחד שהרי ה' מלך כו', וזהו השבח דאין כיוצא בו כו'.\n<b>ומעתה</b> צ\"ל בה' האמירך<sup data-n=\"609\">13</sup> כל פי' אלו ומה\"ע לשמור את כל מצותיו שנא' בהאמירך. והענין הוא שארז\"ל<sup data-n=\"610\">14</sup>* הקב\"ה מניח תפילין, תפילין דמארי עלמא מה כתיב בהו ומי כעמך כו' אחד בארץ, פי' וענין התפילין<sup data-n=\"611\">15</sup> שהקב\"ה הוא בחי' קדוש וברוך בחי' ז\"א דאצי' ע' בלק\"ת בדרוש בהרת<sup data-n=\"612\">16</sup>, והוא מניח תפילין הוא ענין המשכת מוחין לז\"א, וכתיב מגיד דבריו כו' וארז\"ל במד\"ר<sup data-n=\"613\">17</sup>* מה שהוא עושה הוא אומר לישראל לעשות, שפי' בזה שע\"י שאמר לישראל לעשות מצות אלו עי\"ז מפעילים להיות הוא ית' בעצמו עושה, שע\"י שאיש הישראלי מניח תפילין ממשיך שיהי' נמשך המשכת ד' מוחין לז\"א, והוא ע\"י ד\"פ דתפילין קדש רומז<sup data-n=\"614\">18</sup>* על בחי' החכ' והי' כי יביאך בחי' בינה שמע והא\"ש הוא בחי' דעת שנחלק לחו\"ג, וכן ע\"י ציצית להיות הקב\"ה מתעטף בציצית וכדומה כו', וזהו<sup data-n=\"615\">19</sup> האמירך ל' שבח שזהו שבח גדול לישראל שע\"י עשיית המצות שעושים עי\"ז ממשיכים שיהי' נמשך בחי' מצות שלמעלה, ומתורץ בזה ג\"כ ענין לשמור כל מצותיו דכתיב בהאמירך כו'.\n<b>אך</b> מה\"ע אין כיוצא בו בהאמירך שהרי גם בזה נאמר אחד כו', אך הענין יובן ע\"פ מה שנת' במד\"ר ע\"פ חטא חטאה ירושלים<sup data-n=\"616\">20</sup> וכי עובדי כוכבים ומזלות שעובדים לשמש אינם חוטאים כו' אלא שאינם כלום, והיינו כי ע\"י כל דבר שאיש הישראלי עושה ממשיך עי\"ז המשכות עליונות כמו שע\"י יחוד חו\"כ ממשיכים למעלה בחי' יחוד הקב\"ה כנ\"ל עם כנס\"י דלעילא, שלכן מברכין ע\"ז ז' ברכות ואומרים ז\"פ ברוך אתה הוי' להיות כי ממשיכים ז' בחי' אלו כו', ואפי' גם ע\"י דבר שאינו מצוה כלל",[["607","11","<b>דבחי' מלך מלך ימלוך</b>: תיבות אלו ניתוספו בגוכי\"ק תרל\"ט שם."],["608","12","<b>כענין שאמרו נמנע הנמנעות</b>: ראה בהמ\"מ להלן במאמר זה הנחת כ\"ק אדמו\"ר מהורש\"ב נ\"ע."],["609","13","<b>ומעתה צ\"ל בה' האמירך</b>: להבא להלן בפיסקא זו, ראה גם סה\"מ תרל\"ב ע' תעג."],["610","14","<b>שארז\"ל</b>: ברכות ו, א. — ראה תו\"א לה, ב-ג."],["611","15","<b>תפילין דמארי עלמא . . פי' וענין התפילין</b>: ראה גם סה\"מ תרכ\"ז ע' קיא ואילך."],["612","16","<b>ע' בלק\"ת בדרוש בהרת</b>: פ' תזריע כב, ג."],["613","17","<b>וארז\"ל במד\"ר</b>: שמו\"ר פ\"ל, ט."],["614","18","<b>קדש רומז</b>: ראה דרושי תפילין שבסידור [ו, ג ואילך. ז, סע\"א. ח, ב]. באמרי בינה וכו' [שער התפילין יח, א. שם ח\"ג (הוצאת תשמ\"ה) קט, סע\"ג ואילך. קיב, א ואילך. קיח, ג]."],["615","19","<b>וזהו והאמירך ל' שבח וזהו שבח גדול לישראל</b>: בסה\"מ תרל\"ב שם (ע' תפה) נוסף כאן בשולי העמוד הגה\"ה מגוכי\"ק אדמו\"ר מהר\"ש."],["616","20","<b>אך מה\"ע אין כיוצא בו . . במד\"ר ע\"פ חטא חטאה ירושלים</b>: ראה גם אוה\"ת תבוא שם ע' ב'ע. סה\"מ תרל\"ב שם ס\"ע תעה."]]],[2002180225,"כמו נעילת הסנדל ממשיכים ג\"כ להיות בחי' מה יפו פעמיך בנעלים בחי' מלאך סנד\"ל, בחי' כתר דעשי' כו', שלכן מברכין ע\"ז ברכת שעשה לי כל צרכי, והרי בימים שאין נועלים סנדל אין מברכין ברכה זו, ומאחר שבכ\"י מברכין ואומרים ברוך אתה ה' הרי ממשיכים עי\"ז דאל\"כ ח\"ו ה\"ז בכלל דלא תשא כו', וזהו אין כיוצא בו בשבח דהאמירך שלא די מה שממשיכים ע\"י ששומרים כל מצותיו אלא גם ע\"י כ\"ד שאינו מצוה כלל שעושים ג\"כ ממשיכים המשכות אלקות, זה\"ע אין כיוצא בו גם בהאמירך כו', וזהו אחד בארץ שגם בארץ בחי' היותר אחרונה ממשיכים כל בחי' אחד כו'.\n<b>ועתה</b> י\"ל הפי' השני<sup data-n=\"617\">21</sup> של את ה' האמרת שהוא בחי' לבוש כו', והענין הוא דהנה אין מלך בלא עם, והנה עם הוא בחי' נפרדים, והנה כדי שיהי' בחי' נפרדים שהרי כתיב אני הוי' לא שניתי ואתה הוא קודם שנבה\"ע ואתה הוא לאחר שנבה\"ע בלי שינוי כלל, וכדי שיהי' בחי' עם נפרדים זהו ע\"י בחי' לבוש מל' שמתלבש בלבוש גיאות וכמ\"ש ה' מלך גיאות לבש ואין מלך בלא עם וממילא הוצרך להיות גם בחי' עם נפרדים כי על בנים אין שייך מלוכה כ\"א דוקא על עם שהם נפרדים עליהם שייך בחי' מלוכה, והתהוות העם הוא ג\"כ מבחי' מל' לפי שמל' הוא בבחי' רוממות והתנשאות ומאיר בריחוק מקום עי\"ז נעשה בחי' עם נפרדים כו'.\n<b>והנה</b> בבחי' לבוש זה יש ב' בחי', דהיינו שיש בחי' לבוש שהוא בחי' לבוש של הוד וכמ\"ש הוד והדר לבשת שהוא בחי' כבוד הדר מלכותו ויש בחי' לבוש שאינה של הוד, וכמ\"ש אלביש שמים קדרות ושק אשים כסותם כו', והענין הוא דהנה כתיב מלכותך מלכות כל עולמים וממשלתך בכל דור ודור, שיש בחי' מלוכה ויש בחי' ממשלה<sup data-n=\"618\">22</sup>, והנה מלוכה הוא ברצון וכמ\"ש ומלכותו ברצון קבלו עליהם, וממשלה היא בע\"כ, והיינו שמלוכה הוא כשיש בחי' התגלות אוא\"ס במל' אז נק' מלוכה, וזהו שבקי\"ס נאמר ה' ימלוך לעולם ועד, ואז נאמר ל' מלוכה, ומתחלה לא נאמר לשון מלוכה כלל וכמ\"ש מלכותך ראו בניך בוקע ים, שבים דוקא הי' התגלות בחי' המלוכה והיינו לפי שבים הי' התגלות אוא\"ס, הפך ים ליבשה שזהו ענין בחי' מל', שענין המלוכה הוא שיכול להפוך ולשנות את הדבר וע\"כ בקי\"ס שהי' היפך הטבע והפך הים ליבשה זהו ענין התגלות בחי' מלוכה כו', נמצא שמלוכה הוא כשיש בחי' התגלות אוא\"ס במל', והנה בחי' מלוכה הוא ברצון, והיינו כשמקבלים עומ\"ש ברצון, אז נק' בחי' מלך, וזהו ענין ה' מלך גאות לבש שהוא בחי' לבוש של הוד והדר כבוד הדר מל', משא\"כ ממשלה הוא בע\"כ, וזהו וממשלתך בכל דור ודור והיינו כשיש דור שאינם מקבלים עליהם עומ\"ש ח\"ו אז נק' רק ממשלה שהוא בחי' אלביש שמים קדרות ושק אשים כסותם.",[["617","21","<b>ועתה י\"ל פי' השני</b>: בהבא לקמן (בפיסקא זו ושלאחרי') ראה גם ד\"ה את ה' האמרת בסה\"מ תר\"ל ע' רצט ואילך. סה\"מ תרל\"ב ע' תעד."],["618","22","<b>שיש בחי' מלוכה ויש בחי' ממשלה</b>: ראה לקו\"ת ר\"ה נה, ב. נו, ב ואילך. סה\"מ תרכ\"ז ע' תלו. ובכ\"מ."]]],[2002180226,"<b>וזהו</b> את ה' האמרת היום פי' היום הוא ר\"ה<sup data-n=\"619\">23</sup>, דהיינו שבר\"ה ממשיכים בחי' לבוש מל' שהוא בחי' לבוש של הוד והדר, וכמו שאנו אומרים בר\"ה ה' מלך גאות לבש<sup data-n=\"620\">24</sup> כו', וזהו שאנו מבקשים מלוך על העולם כולו בכבודך והנשא על כל הארץ ביקרך, ביקרך דוקא, והופע בהדר גאון עוזך שיהי' גילוי בחי' מלכותו בבחי' לבוש של הוד והדר, וזהו שאנו אומרים גלה כבוד מלכותך עלינו דהיינו שיהי' גילוי כבוד מל' דא\"ס, וזהו ותמלוך אתה הוא הוי' לבדך שיהי' גילוי כל הבחי' במל' מבחי' אתה הוא והוי', וזהו את ה' האמרת היום שבר\"ה ממשיכים בחי' לבוש מל', אמרו לפני מלכיות כדי שתמליכוני עליכם.\n<b>וה'</b> האמירך<sup data-n=\"621\">25</sup>, הענין הוא דהנה ארז\"ל מ\"ט עזי מסגי ברישא והדר אימרי כברייתו של עולם ברישא חשוכא והדר נהורא, והנה אימרא הוא בחי' צדיקים שנק' נהורא כו', והנה מאימרא נעשה לבושים, כי מהצמר של אימרא עושים לבושים וכמ\"ש ומגז כבשים יתחמם, וכן א' כל בגדים הנאמר בתורה הוא מצמר ופשתים, והיינו שע\"י מעשה הצדיקים נעשים לבושים לנשמה, וזהו יביאו כו' והלבישו את האיש כו', ושרש הלבושים נמשך מבחי' לבושי' כתלג חיור כו', דהנה כתיב אם יהיו חטאיכם כשנים כשלג ילבינו אם יאדימו כתולע כצמר יהיו, וכמ\"ש במ\"א ההפרש בין שנים לתולע<sup data-n=\"622\">26</sup>, והיינו שנמשך בר\"ה מבחי' לבושי' כתלג חיור ושער רישי' כעמר נקי להלבין ולטהר את העון, וזהו ע\"י התשובה כו', וזהו וה' האמירך היום דהיינו שנמשך עליך בחי' לבושי' מבחי' לבושי' כתלג חיור ושער רישי' כעמר נקי, וזהו ע\"י את ה' האמרת היום שהיא בחי' לבוש מל' ע\"י קבעומ\"ש ועי\"ז וה' האמירך שנמשך ג\"כ מלמעלה מבחי' לבושי' כתלג חיור שהוא בחי' המשכת יגמה\"ר לטהר ולהלבין את עוונות בנ\"י כו', וזהו שנק' אימרא שהוא בחי' אור כמאמר והדר נהורא, והיינו שאימרא שהוא בחי' לבושי' שנמשך בר\"ה מבחי' לבושי' כתלג חיור נק' נהורא וזהו שר\"ה נק' ג\"כ אור וכמ\"ש ה' אורי וישעי וארז\"ל אורי בר\"ה וישעי ביו\"כ כו'.\n<b>ועתה</b> י\"ל פי' הג'<sup data-n=\"623\">27</sup> של את ה' האמרת שהוא בחי' אמירה ודבור שהוא בחי' שמקיימין את העולם שנברא בעשרה מאמרות, והענין הוא דהנה כתיב כי אמרתי עולם חסד יבנה, דהיינו שצריך לבנות את החסד, דהנה בתחלת בריאת העולמות הי' מצד עצמו כי חפץ חסד הוא<sup data-n=\"624\">28</sup>, משא\"כ עכשיו צריך לבנות את החסד,",[["619","23","<b>פי' היום הוא ר\"ה</b>: ראה לקו\"ת תבוא מא, ג. מב, א. מד, א. סה\"מ תרל\"ב ח\"ב ע' תקצט. וש\"נ."],["620","24","<b>וכמו שאנו אומרים בר\"ה ה' מלך גאות לבש</b>: ראה גם רשימות תהלים להצ\"צ (יהל אור) ס\"ע שלח. לקו\"ש חכ\"ט ע' 317. וש\"נ."],["621","25","<b>וה' האמירך הענין דהנה ארז\"ל מ\"ט עיזי מסגי ברישא והדר אימרי</b>: ראה גם אוה\"ת תבוא ע' תתרפד. סה\"מ תרכ\"ז ע' שסב. תרכ\"ט ע' נח. תרל\"ג ח\"א ע' ריא. רכט."],["622","26","<b>וכמ\"ש במ\"א ההפרש בין שנים לתולע</b>: ראה סה\"מ תרכ\"ז ע' תכו. תרכ\"ט ע' שסח. וש\"נ."],["623","27","<b>ועתה י\"ל פי' הג'</b>: בהבא לקמן (עד: והנה בר\"ה) ראה סה\"מ תר\"ל שם ע' ש ואילך. סה\"מ תרל\"ב שם ע' תעד. וראה גם לקו\"ת שה\"ש יב, ב. ס' מאמרי אדהאמ\"צ דרושי חתונה ח\"א ע' לג ואילך."],["624","28","<b>דהנה כתיב כי אמרתי עולם חסד יבנה . . כי חפץ חסד הוא</b>: ראה גם סה\"מ תרכ\"ז ע' קמ. קמב. תרכ\"ט ע' ט. עג. תו. ועוד."]]],[2002180227,"והיינו שצריך להמשיך את בחי' החסד הזה וכמ\"ש זה היום תחלת מעשיך זכרון ליום ראשון שמעוררים את בחי' החסד שהי' מתחילה מעצמו כי חפץ חסד הוא, ועכשיו אנו מעוררים ומזכירים את בחי' החסד הזה שיהי' גם עכשיו נבנה החסד כו', וזהו את הוי' האמרת והיינו שממשיך את הוי' בבחי' אמירה ודבור שיאמר את העשרה מאמרות, ופי' את הוי' האמרת היינו שממשיך את בחי' ש' הוי' בבחי' אמירה דהיינו בע\"מ. דהנה גדולים מעשה צדיקים ממעשה שמים וארץ, דהנה במעשה שו\"א כתיב בראשית ברא אלקים, שבכל העש\"מ נאמר רק ש' אלקים, ואפי' בראשית נמי מאמר הוא בחי' מאמר אחד נאמר בו ג\"כ רק ש' אלקים, משא\"כ ע\"י מעשה הצדיקים ממשיכים בבחי' הע\"מ בחי' ש' הוי', וזהו שמקיימין את העולם שנברא בעש\"מ<sup data-n=\"625\">29</sup> והיינו כי קיום הוא בחי' יסוד, וזהו כמ\"ש וצדיק יסוד עולם שהוא בחי' סוד הוי' ליריאיו, והיינו שממשיכים בחי' ש' הוי', וזהו שמקיימין שעושין קיום ויסוד וממשיכים מבחי' ש' הוי' בשם אלקים כו'. וזהו את ה' האמרת היום שמתחלה הי' רק מבחי' ש' אלקים אבל עכשיו ממשיכים שיהי' הוי' האמרת כנ\"ל.\n<b>והנה</b> ע\"י מה ממשיכים שיהי' את ה' האמרת שיהי' גילוי בחי' עשרה מאמרות, זהו ע\"י אמר וכמ\"ש יום ליום יביע אמר, אמר הוא ר\"ת אש מים רוח<sup data-n=\"626\">30</sup>, שהוא בחי' קול כי הקול הוא מורכב מאש מים רוח, והנה הדבור נמשך מהקול וע\"י אמ\"ר עי\"ז נמשך שיהי' את ה' האמרת. והענין הוא, דהנה ג' בחי' אלו אמ\"ר הוא בחי' משארז\"ל על שלשה דברים העולם עומד<sup data-n=\"627\">31</sup> על התורה ועל העבודה ועל גמ\"ח, עבודה הוא בחי' אש כי אש הוא בחי' העלאה ממטה למעלה, וכך עבודה הוא שהיו מקריבין את הבהמה ע\"ג המזבח והיתה נכללת באש שלמעלה, וכך גם עתה תפלות כנגד תמידין תקנו, שזהו מ\"ש כמו חלב ודשן תשבע נפשי שצריך להקריב את החלב ודם לאלקות, דהיינו שלא יהי' לו רצון אחר כ\"א רצון פשוט להוי' לבדו וכמ\"ש מי לי בשמים ועמך לא חפצתי בארץ שאין לו שום רצון ותענוג כ\"א לה' לבדו, וזהו בחי' אש, וגמ\"ח הוא בחי' מים שהוא בחי' המשכה כי מים יורדים ממקום גבוה לנמוך כו', ותורה הוא בחי' רוח שהוא רוח פיו כו', והנה ע\"י ג' בחי' אלו עי\"ז ממשיכים שיהי' בחי' גילוי הדבור, דהיינו שיומשך בחי' קיום ע\"מ.\n<b>והנה</b> בר\"ה הוא עיקר בחי' בנין הדבור, וזהו שבמד\"ר פ' אמור מתחיל הפרשה על ענין ר\"ה בפסוק לעולם ה' דברך נצב בשמים<sup data-n=\"628\">32</sup>, והיינו לפי שבר\"ה הוא בחי'",[["625","29","<b>וזהו שמקיימין את העולם שנברא בעש\"מ</b>: ראה גם סה\"מ תרכ\"ז ע' רפד. תרל\"ב ח\"ב ע' תלט. ועוד."],["626","30","<b>אמר הוא ר\"ת אש מים רוח</b>: ראה גם תו\"א בראשית ו, ד. לקו\"ת שה\"ש יב, ב. סידור עם דא\"ח נב, ד. קפא, ב. רסד, ד. מאמרי אדהאמ\"צ דרושי חתונה שם ע' לד. וש\"נ."],["627","31","<b>ג' בחי' אלו אמ\"ר הוא בחי' משארז\"ל על שלשה דברים העולם עומד</b>: ראה גם לקו\"ת שה\"ש שם. ס' מאמרי אדהאמ\"צ שם ע' מט."],["628","32","<b>והנה בר\"ה הוא עיקר בחי' בנין הדבור . . דברך נצב בשמים</b>: ראה גם אוה\"ת תבוא שם ע' תתרסט. סה\"מ תר\"ל שם ע' שא ואילך. תרל\"ב שם ע' תעד."]]],[2002180228,"בנין הדבור דהיינו שיומשך גילוי בחי' ש' הוי' בעש\"מ. וזהו שבר\"ה ג' ספרים נפתחים שהוא כנגד ג' בחי' אמ\"ר וכמ\"ש בס\"י בשלשה ספרים ברא הקב\"ה את עולמו בספר וסופר וסיפור, והיינו כי סיפור הוא בחי' מל' שהוא בחי' דבור, וכדי שיומשך בחי' סיפור הוא ע\"י ספר וסופר, כי סופר הוא בחי' חכ', וכמ\"ש אי' שוקל ואי' סופר<sup data-n=\"629\">33</sup>, והיינו כי החכמה נמשך מבחי' אי', וכמ\"ש והחכמה מאין תמצא, ובחי' אי' שוקל הוא בחי' מתקלא שהוא בוצינא דקרדוניתא שהוא בחי' משקל ומדה שמודד אורות בכלים. והנה כדי שיומשך בחי' ג' ספרים אלו זהו ג\"כ ע\"י קול שהוא כלול מאמ\"ר, והיינו ע\"י קול השופר שיוצא מהבל הלב שהוא כלול מאש מים ורוח כו', וע\"כ סדר תקיעות שלש של שלש שלש כי שלש תקיעות תקיעה שברים תרועה תקיעה, וע\"י ג' בחי' אלו תר\"ת עי\"ז נמשך שיהי' ג' ספרים נפתחים בר\"ה עד שיומשך בבחי' סיפור שהוא בחי' דבור כנ\"ל, וזהו את ה' האמרת היום.\n<b>והנה</b> ענין וה' האמירך היום, הענין הוא דהנה ארז\"ל כל הקורא ושונה<sup data-n=\"630\">34</sup> הקב\"ה קורא ושונה כנגדו ממש שע\"י דבור האדם בד\"ת עי\"ז נמשך להם מלמעלה שיהי' הקב\"ה קורא ושונה כנגדו ממש, וכדי שיהי' בכח האדם ע\"י דבורו בד\"ת להמשיך שיהי' הקב\"ה קורא כנגדו, זהו הכח ניתן להם מלמעלה, וזהו וה' האמירך שהכח הזה שאתה ממשיך שיהי' הקב\"ה קורא ג\"כ זהו וה' האמירך שה' נותן לך כח הזה. וזהו מ\"ש להיות לו לעם סגולה, שזהו כמו סגולה שהוא למעלה מהטעם איך יש ביכולת האדם ע\"י דבורו להמשיך גילוי אוא\"ס הוא רק כמו סגולה שאין לזה טעם כלל כו'. וזהו מ\"ש אח\"כ ולתתך עליון על כל הגוים אשר עשה לתהלה ולשם ולתפארת<sup data-n=\"631\">35</sup>, והיינו כי תהלה הוא מל' בהלו נרו על ראשי שהוא בחי' אש. ולשם הוא בחי' מל' כמ\"ש ויעש דוד שם, מבחי' קדמות השכל כו', וזהו מ\"ש ומי כעמך כישראל גוי אחד בארץ אשר הלכו אלקים לפדות לו לעם ולשום לו שם, בש\"ב ז' ך\"ג, והיינו שיהי' הגדלה בבחי' השם, שיהי' גילוי בחי' מל', וכדי שיהי' הגדלה בבחי' שם זהו ע\"י מים כי מים מצמיחים, והיינו שהוא בחי' המשכת ה' חסדים שהוא ע\"י בחי' גמ\"ח כו'. ולתפארת הוא בחי' קו האמצעי שהוא בחי' תורה בחי' רוח כו'. וזהו ולתתך עליון כו' והיינו שנתן להם זה הכח מלמעלה שיהי' בכחם ע\"י תורה ועבודה וגמ\"ח להמשיך בחי' המשכת גילוי אוא\"ס למטה כנ\"ל.",[["629","33","<b>וכמ\"ש אי' שוקל ואי' סופר</b>: ראה גם תו\"א שמות נג, ב ואילך. ס' מאמרי אדה\"ז תקס\"ה ח\"א ע' רה. ועל נביאים ע' קכג."],["630","34","<b>וה' האמירך . . דהנה ארז\"ל כל הקורא ושונה</b>: ראה גם אוה\"ת תבוא שם ע תתרסט. תתרפח."],["631","35","<b>ולתתך עליון . . לתהלה לשם ולתפארת</b>: ראה גם לקו\"ת תבוא מה, ב."]]],[2002180229,"<h3>ארע\"ק אשריכם ישראל כו'</h3>\n<b>בס\"ד. לא נא'</b>\n<b></b>מקוה ב' פי' כו' מבול כו' יתמו ושם ימותו כו' ויהי שם עם ה'\n(משנה פב\"ת דיומא). אר\"ע אשריכם ישראל<sup data-n=\"632\">1</sup> מפני מי אתם מטהרין ומי מטהר אתכם אביכם שבשמים שנאמר וזרקתי כו', ואומר<sup data-n=\"633\">2</sup> מקוה ישראל ה', מה מקוה מטהר את הטמאים כך הקב\"ה מטהר את ישראל. הנה בפי' תי' מקוה יש שני פירושים, הא' הוא מל' יקוו המים שמקום קיבוץ המים למקום א' נק' בשם מקוה, והב' מלשון קוה אל ה', טוב ה' לקויו שהוא לשון תקוה.\n<b>והנה</b> ידוע שיעור המקוה הוא מ' סאה דוקא, וזהו מ\"ש ויהי שם עם ה' ארבעים יום שהוא ענין מ' סאה דמקוה. ולהבין זה צ\"ל מ\"ש כי מי נח זאת לי אשר נשבעתי מעבור מי נח עוד על הארץ, דלכאורה קשה למה נק' המבול בשם מי נח שהוא לשון נייחא והלא המבול הי' לשחת כל בשר אשר על הארץ שהוא היפך מבחי' נייחא. והענין הוא דהנה ידוע הקושיא המבואר בת\"א<sup data-n=\"634\">3</sup> פ' נח ד\"ה מים רבים כו' למה הי' צריך המבול שיהי' ארבעים יום דוקא, והוא מפני שמ' יום שהלך המבול הם נגד מ' סאה דמקוה, כי המבול הי' כדי לטהר את הארץ<sup data-n=\"635\">4</sup> שהיא בחי' מל' שנטמאה בגזל ובמוציא זרע לבטלה, וע\"י שהשחיתו דרכם על הארץ שהוציאו זרע לבטלה<sup data-n=\"636\">5</sup> בלא נקבה עי\"ז המשיכו את האור עליון למעלה שלא ע\"י נוק' שהיא בחי' מל' שהיא בחי' ארץ, והמשיכו האור בקליפות, וכדי לטהר את הארץ מטומאתה הי' המבול ארבעים יום דוגמת המקוה שצריך ארבעים סאה דוקא.\n<b>ולהבין</b> ענין הטהרה<sup data-n=\"637\">6</sup> של המבול, הנה כתי' מים רבים לא יוכלו לכבות את האהבה ונהרות לא ישטפוה, לפי שהאהבה שלהם נמשך מלמעלה, וכמ\"ש לעיל",[["632","1","<b>אר\"ע אשריכם ישראל</b>: מאמר זה מיוסד על ד\"ה זה באוה\"ת דרושים ליוהכ\"פ ע' א'תקעו ואילך (פרקים: א', ז', ט', י\"ד-ט\"ו ורפי\"ז). ונמצא בשינויים וביאורים בד\"ה זה תרנ\"ה (בסה\"מ ליקוט ח\"ב ע' כט ואילך).\nלהתחלת וסיום המאמר ראה ד\"ה זה בס' תרמ\"ב וד\"ה זה בהמשך תרס\"ו ע' שפ. וע' שפז-ח. וד\"ה זה בסה\"מ תשי\"ז. וראה גם לקו\"ש ח\"א ע' 11 ואילך.\nממעל להמאמר נרשם בגוכתי\"ק: לא נא' [ור\"ל שמאמר זה לא נאמר בשנת תרל\"ט]. וראה לקמן ד\"ה להבין שרשי הדברים הנ\"ל, ובהערתינו בשולי העמוד שם."],["633","2","<b>מקוה ישראל ה' מה מקוה מטהר . . בפי' תי' מקוה יש שני פירושי'</b>: ראה אוה\"ת דרושים ליוהכ\"פ שם ע' א'תקעו: באמת מקוה לשון תקוה, רק על המשנה שמפ' מקוה לשון מה מקוה מטהר קשה. עיי\"ש. וראה גם שם ריש ע' א'תקפו."],["634","3","<b>בת\"א פ' נח בד\"ה מים רבים</b>: דף ח, ג ואילך. [ובהבא לקמן עד פיסקא: אך יש עוד בחי' מקוה ראה תו\"א נח שם. ובהביאור ע\"ז באוה\"ת נח (כרך ג) תרכא, א ואילך]."],["635","4","<b>המבול הי' כדי לטהר את הארץ</b>: בד\"ה זה תרנ\"ה שם מוסיף: לא כמו שסוברים העולם שהמבול הי' רק בכדי להאביד החוטאים, דאם רק זה הי' הכוונה בלבד הרי הקב\"ה שהוא כל יכול הי' יכול להאבידם ברגע אחד, וכמו שמצינו במחנה סנחריב, אלא שעיקר הכוונה הי' בכדי לטהר את הארץ. ע\"כ. ועד\"ז הוא בתו\"א נח ח, ג שם."],["636","5","<b>שהשחיתו דרכם על הארץ שהוציאו זרע לבטלה</b>: ראה בארוכה באוה\"ת נח סז, ב. שם (כרך ג) תרכד, א ואילך (בשם השל\"ה)."],["637","6","<b>ולהבין ענין הטהרה של המבול הנה כתיב מים רבים</b>: בהבא לקמן ראה ד\"ה מים רבים בתו\"א נח שם. ובאוה\"ת נח שם (כרך ג) תרכא, א ואילך."]]],[2002180230,"מיני' רשפי' רשפי אש שלהבת י\"ה ותרגום של רשפיה הוא גומרי פי' גומר הוא גחלת<sup data-n=\"638\">7</sup> שהוא מקור האש. והנה ידוע מ\"ש בס\"י ע\"ס בלי מה כשלהבת הקשורה בגחלת<sup data-n=\"639\">8</sup>, שע\"ס נק' בשם אש. כי טבע האש לעלות למעלה, כי הנה ד' יסודות הם כנגד ד' עולמות אבי\"ע<sup data-n=\"640\">9</sup>, רוח מים עפר הם נגד ג' עולמות בי\"ע, ואש הוא כנגד עולם האצי' שהוא בחי' מדות, והיינו לפי שאור האצי' אין לו כלים להתפשט למטה כמו האש כו', וזהו שנמשל הקב\"ה לאש כמ\"ש כי הוי' אלקיך אש אוכלה<sup data-n=\"641\">10</sup>, והיינו לפי שהחיות הנמשך מאוא\"ס הוא בחי' רצוא ושוב, מטי ולא מטי שאין לו כלי להתפשט למטה, וע\"כ נמשל לאש (ע' בלק\"ת פ' נצבים בדרוש אתם נצבים<sup data-n=\"642\">11</sup>). ושלהבת הקשורה בגחלת, היינו שיש חילוק בע\"ס איך שהם נעשים בגילוי בחי' מדות כשלהבת היוצא בגילוי מן הגחלת, לכמו שהם קשורים במקורם טרם שיצאו לידי גילוי כו'. ושרש אהבה זו של נש\"י נמשך מבחי' שלהבת י\"ה, וע\"כ מים רבים לא יוכלו לכבות, כי מה שמים מכבין אש זהו באש שלמטה, אבל לא אש שלמעלה, כי במקור האש אינו שייך כיבוי, כמו למשל שאנו רואים בצור (הנק' קרעמין) אע\"פ שמוציאים ממנו אש אינו שייך אצלו כיבוי, והיינו לפי שהוא מקור האש, וכך לפי שאהבה זו נמשך מבחי' שלהבת י\"ה אש שלמעלה, וע\"כ אינו יכול לכבות, וכ\"ש ששרשם נמשך מבחי' רשפי אש שהוא מקור של ע\"ס ע\"כ לא יוכל לכבות את האהבה, ואדרבה ע\"י מים רבים הנ\"ל נעשה האהבה לה' חזקה ביותר בבחי' אהבה ותשוקה נפלאה, והיינו שע\"י התבוננות איך שהוא רחוק מה' בתכלית ובהבל בא ובחשך ילך עי\"ז התשוקה והצמאון לה' הוא ביתר שאת וביתר עז.\n<b>וזהו</b> מה שהמבול נק' מי נח, דאין הפי' שהמבול עצמו נק' מי נח, שהרי הוא הי' לשחת את הארץ, רק הפי' שע\"י המבול נעשה אח\"כ בחי' נייחא וכמ\"ש ותרם התיבה<sup data-n=\"643\">12</sup>, שע\"י המבול נעשה אח\"כ בחי' נייחא והתרוממות התיבה. ובעבודה מים רבים נק' טרדות הפרנסה, וע\"י הטרדא אח\"כ כשמתפלל עי\"ז נעשה התגברות האהבה כו', וכמ\"ש ותרם התיבה כי תיבה הוא אותיות התורה ואותיות התפלה<sup data-n=\"644\">13</sup>, וע\"י",[["638","7","<b>ותרגום של רשפיה הוא גומרי . . גחלת</b>: ראה אוה\"ת נח שם תרכא, ב (בשם התרגום יונתן והאבן עזרא)."],["639","8","<b>ידוע מ\"ש בס\"י . . כשלהבת הקשורה בגחלת</b>: בהבא לקמן בפיסקא זו ראה בארוכה באוה\"ת נח (כרך ג) שם תרכא, ב. וראה גם דרך מצותיך קפב, א ואילך. המשך מים רבים תרל\"ו ע' ע ואילך. סה\"מ מלוקט ח\"א ע' כב-ג."],["640","9","<b>ד' יסודות הם כנגד ד' עולמות אבי\"ע</b>: ראה בכ\"ז סה\"מ תרל\"ג ח\"ב ע' שפא [ובהנסמן שם בתחילת המאמר]."],["641","10","<b>וזהו שנמשל הקב\"ה לאש כמ\"ש כי הוי' אלקיך אש אוכלה</b>: ראה בארוכה לקו\"ת אחרי כה, ג ואילך. סה\"מ תר\"ל ע' שי ואילך. וע' שטו ואילך. תרח\"צ ע' מט ואילך."],["642","11","<b>בלק\"ת פ' נצבים בדרוש אתם נצבים</b>: דף מד, ג."],["643","12","<b>ותרם התיבה . . ובעבודה . . טרדות הפרנסה .ֿ. אח\"כ כשמתפלל</b>: ראה בכ\"ז בארוכה בתו\"א פ' נח שם ט, סע\"א. ט, ג ואילך."],["644","13","<b>תיבה הוא אותיות התורה ואותיות התפלה</b>: ראה כתר שם טוב בהוספות ס\"ז-י. צוואת הריב\"ש סו\"ס עה. או\"ת להה\"מ ז, ב. לקו\"ת פנחס עו, ב. תו\"ח נח סא, ב. [ובהמ\"מ שם בהוצאת תשנ\"ג]. אוה\"ת נח (כרך ג) תרמ, א. סה\"מ תרל\"ב ח\"א ע' ו. תרל\"ג ח\"א ע' ב. וש\"נ."]]],[2002180231,"מים רבים הנ\"ל נעשה להם התרוממות בעילוי יותר כו'. וזהו מי נח שנק' נייחא ל' מנוחה שע\"י המבול דוקא נעשה אח\"כ נייחא, וכמו שבת שנק' מנוחה כמ\"ש ומנוחה לחיי העולמים, והמנוחה של שבת נעשה דוקא ע\"י ששת ימי החול ששת ימים תעבוד, שהוא ענין ששת ימי החול ל\"ט מלאכות, שהוא כמו ארבעים סאה במבול וכמ\"ש במשנה אבות מלאכות ארבעים חסר אחת, שהמלאכות הן ארבעים כמו ארבעים סאה דמקוה רק שנחסר אחת. וזהו ג\"כ ענין ל\"ט מלקות<sup data-n=\"645\">14</sup> שנאמר ארבעים יכנו, רק שנחסר אחת כדי שלא יהי' דין קשה כמו המבול<sup data-n=\"646\">15</sup>. וע\"י הל\"ט מלאכות שנק' מים רבים לברר הטוב מהרע, עי\"ז נעשה אח\"כ בשבת בחי' מנוחה עליית העולמות ותרם התיבה כו', על מי מנוחות ינהלני כו'. וכן ע\"י ל\"ט מלקות נעשה אח\"כ בחי' גילוי, וכמו שא' ריש מתיבתא דג\"ע אעא דלא סליק בי' נהורא<sup data-n=\"647\">16</sup> מבטשין לי', וכך גופא דלא סליק בה נהורא דנשמתא מבטשין לי', כי חולשא דגופא תוקפא דרוחא, וע\"י הביטוש נעשה אח\"כ בחי' גילוי הנשמה. וכך ע\"י מים רבים הנ\"ל נעשה אח\"כ האהבה לה' בתוקף. אך הנה כתיב כי מי נח זאת לי אשר נשבעתי מעבור מי נח עוד על הארץ כו', והיינו כי אעפ\"י שמים רבים הנ\"ל מטהרים את הארץ, מ\"מ לא היו מטהרים אלא ע\"י שכלו את הרע לגמרי והעלו את הטוב, אבל הרע עצמו לא נתעלה, וכן ענין ל\"ט מלאכות אעפ\"י שהן בירורים מ\"מ הרי הם רק לברר את הטוב מן הרע, אבל הרע נשאר בבחי' רע.\n<b>אך</b> יש עוד בחי' מקוה שמטהרת את הטמאים לגמרי שמטמא נעשה טהור, וזהו ענין מ' יום של הלוחות וכמ\"ש ויהי שם עם ה' ארבעים יום. ולהבין ענין מקוה זו, צ\"ל משארז\"ל משה רבינו לא מת, כתיב הכא וימת שם ולהלן כתיב ויהי שם עם ה', וילפינן שם שם לגז\"ש מה להלן עומד ומשמש במרום אף כאן עומד ומשמש במרום. וי\"ל א\"כ למה כתיב וימת כו'.\n<b>אך</b> הענין הוא<sup data-n=\"648\">17</sup> דהנה כתיב במדבר הזה יתמו ושם ימותו, ופי' בזהר שע\"י מדבר באו לבחי' תמים תהי'<sup data-n=\"649\">18</sup> עם ה' אלקיך. והנה פי'<sup data-n=\"650\">19</sup> תמים שיהי' תוכו כברו, דהנה",[["645","14","<b>ל\"ט מלאכות . . ארבעים חסר אחת . . ל\"ט מלקות</b>: ראה בכ\"ז אוה\"ת יתרו ע' תתקנד. סה\"מ תר\"ל ע' רמד. וע' רנב."],["646","15","<b>ל\"ט מלקות . . שנחסר אחת כדי שלא יהי' דין קשה כמו המבול</b>: ראה ד\"ה זה תרנ\"ה: ולכן אי' בזוה\"ק שהל\"ט מלקות הוא ג\"כ כמו מקוה ארבעים סאה שהכוונה מהל\"ט מלקות בכדי לאדכאה לבני נשא, אך מה שמלקות הוא ל\"ט הוא מפני שהוא גבורה ובכדי שלא יהי' התגברות הגבורה לכן כתבו רז\"ל מ' חסר אחת, אבל הכוונה הוא כמו מקוה."],["647","16","<b>וכמו שא' . . אעא דלא סליק בי' נהורא</b>: הובא ונת' בתניא פכ\"ט (לה, סע\"ב). וראה גם לעיל ח\"א סד\"ה וידבר גו' זאת חוקת."],["648","17","<b>אך הענין הוא דהנה כתי' במדבר הזה יתמו</b>: בהבא לקמן ראה אוה\"ת דרושים ליוהכ\"פ שם ע' א'תקפד."],["649","18","<b>במדבר הזה יתמו . . שע\"י מדבר באו לבחי' תמים תהי'</b>: בהבא לקמן ראה לקו\"ת פ' ראה לב, ג. אוה\"ת שלח ע' תקכט. נ\"ך ע' תרמח. ביאוה\"ז להצ\"צ ח\"א ע' רסט ואילך. סה\"מ תרל\"ב ח\"ב ע' תנא ואילך."],["650","19","<b>והנה פי' תמים תהי' שיהי' תוכו כברו</b>: בהבא לקמן ראה אוה\"ת דרושים ליוהכ\"פ שם ס\"ע א'תקפא-ב (בשם רבינו בחיי ע\"פ תמים תהי')."]]],[2002180232,"כתיב ויפתוהו בפיהם ובלשונם יכזבו לו כו' ואעפ\"כ והוא רחום יכפר עון<sup data-n=\"651\">20</sup>, והיינו לפי שאעפ\"כ הם בטלים בחיצוניות, והחיצוניות תופס ג\"כ מקום, וכמארז\"ל מאן דלא כרע במודים אינו קם בתחיית המתים, אך אם כרע במודים אף שאינו יודע (וכמו שאמר אביי באו ונחזיק טובה לראש דמעצמי' כרע) קם בתחיית המתים, והיינו לפי שאעפ\"כ בחיצוניות הוא בטל, וכן אדם שהוא מתפלל אעפ\"י שהוא מתפלל בלא כוונה ואינו יודע כלל מה הוא מתפלל אעפ\"כ זה תופס מקום, ואינו דומה כלל למי שאינו מתפלל כלל, וע\"כ אף אם ויפתוהו בפיהם בלבד אעפ\"כ והוא רחום. אך מ\"מ אינו רק בחי' ברו, אבל בתוכו אינו מאיר בחי' אלקות, וזהו מ\"ש כי פנו אלי עורף ולא פנים, היינו אף שפנו אלי<sup data-n=\"652\">21</sup> אך הוא בבחי' חיצוניות ולא בבחי' פנימיות, אבל שיהי' תוכו כברו היינו שיהי' מאיר אלקות בתוך תוכו וכמ\"ש ונקדשתי בתוך בנ\"י היינו שיהי' קדוש בתוכו כו', וכמ\"ש אני הוי' לא שניתי ואתם בנ\"י לא כליתם היינו שהנביא קובל ע\"ז שבאמת הי' צ\"ל כלות הנפש<sup data-n=\"653\">22</sup> מזה, רק לפי שאינו מאיר בבחי' פנימי'. וזהו מ\"ש במדבר הזה יתמו שע\"י מדבר דוקא הגיעו לבחי' תמים תוכו כברו. דהנה ענין מדבר הוא מ\"ש ארץ ציה ועיף בלי מים, שהוא בחי' חשך והעלם שאינו מאיר אלקות בבחי' גילוי, אך עי\"ז שהוא בחי' חשך והעלם, ונעשה בחי' אתכפיא ואתהפכא עי\"ז דוקא נעשה בחי' תמים, כי יתרון האור מן החשך דוקא. וזהו ענין הנסיונות שנעשה לאדם שהנסיון הוא שמסתיר על גילוי אלקותו, לפי שהם הסתר פנים והסתלקות חיות השפע במניעת בריאות הגוף או ממון, כדי להסתיר על אור וחיות ה' וקדושתו, ובשביל כך באין לו הנסיונות כדי שיתגבר עליהם, ועי\"ז יגיע לבחי' גבוה יותר בחי' תמים (וע' בלק\"ת פ' ראה בדרוש אחרי ה'<sup data-n=\"654\">23</sup> אלקיכם). והנה עי\"ז שהוא בחי' תמים עי\"ז הוא עם ה' אלקיך, דהנה ש' הוי' וש' אלקים למעלה הוא בחי' תוך וברו, וכמ\"ש כי שמש ומגן ה' אלקים, ששם אלקים מסתיר על שם הוי', אך ע\"י בחי' תמים עי\"ז נעשה למעלה ג\"כ יחוד ש' הוי' בש' אלקים שיהי' תוכו כברו למעלה ג\"כ כמו שהוא למטה. וזהו במדבר הזה יתמו. ושם ימותו זהו ענין נפילת אפים שהוא למעלה גם מבחי' תמים לפי שהוא מס\"נ ממש כמ\"ש אליך ה' נפשי אשא כמאן דמסר עצמו למיתה שהוא בחי' ביטול במציאות ממש<sup data-n=\"655\">24</sup>. וזהו ענין מ\"ש אין התורה מתקיימת אלא במי שממית עצמו עליה, שהתורה צריך שיהי' בבחי' ביטול דוקא, ואשים דברי בפיך, כל האומר אין לי אלא תורה כו'.",[["651","20","<b>דהנה כתי' ויפתוהו בפיהם . . ואעפ\"כ והוא רחום יכפר עון</b>: ראה פרש\"י ומצו\"ד עה\"פ (תהלים עח, לד-לח)."],["652","21","<b>אף שפנו אלי אך שהוא בבחי' חיצוני' ולא בבחי' פנימי'</b>: ראה בכ\"ז לקו\"ת אחרי כו, ד. דרושים לשמע\"צ פז, א. ועוד."],["653","22","<b>ואתם בנ\"י לא כליתם . . שהנביא קובל ע\"ז שבאמת הי' צ\"ל כלות הנפש</b>: ראה תו\"א יתרו סז, א. לקו\"ת דרושים לר\"ה סא, ד. סה\"מ תרל\"ב ח\"א ע' רצג. תרל\"ג ח\"א ע' רצה."],["654","23","<b>בלק\"ת פ' ראה בדרוש אחרי ה'</b>: דף יט, סע\"ב ואילך."],["655","24","<b>נפילת אפים . . שהוא מס\"נ ממש . . ביטול במציאות ממש</b>: ראה לקו\"ת ראה שם לב, ג."]]],[2002180233,"<b>וזהו</b> וימת שם וגמרינן שם שם מויהי שם עם ה', דהיינו שכשעלה להר לקבל את התורה הגיע לבחי' ביטול במציאות ממש כמו וימת, ואף שמשה הי' בחי' מ\"ה, אך מ\"מ כדי לקבל התורה הי' צריך להגיע לבחי' ביטול גדול יותר אף לפי מדרגתו, וזהו מ\"ש לחם לא אכל ומים לא שתה שאף שאכילתו הי' בחי' גבוה מאד, וגם שאכילתו הי' אכילת לחם אבירים שהי' נבלע באברים, אעפ\"כ כדי לקבל התורה גם אכילתו הוא בחי' יש עדיין, ע\"כ לחם לא אכל כו'. וזהו דעת מ\"ד משה רבינו לא מת, ומ\"ש וימת שם משה היינו שהגיע אח\"כ לבחי' ביטול גדול יותר וכמשארז\"ל גדולים צדיקים במיתתם יותר מבחייהם, לפי שמשה בחייו לא השיג רק מ\"ט שערי בינה, ובמותו השיג גם שער הנו\"ן דבינה, לפי שהגיע לבחי' ביטול גדול יותר, וזהו ויהי שם עם ה' שכדי לקבל את התורה הי' צריך שיהי' בבחי' ביטול במציאות ממש, אין התורה מתקיימת אלא במי שממית עצמו עלי'.\n<b>ולהבין</b> ענין מ\"ש ויהי שם עם ה'<sup data-n=\"656\">25</sup>, הנה כתיב כי עם ה' החסד וכן כתי' ונהורא עמי' שריא, והנה מ\"ש עם ה' החסד דוקא זהו קאי על עצמות אוא\"ס המאיר בכתר עליון, וע\"ז אמר כי עם ה' החסד דהיינו שאין שם רק בחי' חסד לבד וכמ\"ש בע\"ח לית שמאלא בהאי עתיקא, ואין הפי' שאין שם רק בחי' חסד לבד שהרי גם הכתר כלול מכל הע\"ס ויש שם ג\"כ גבורה, אלא ששם גם היד שמאל שהוא בחי' גבורה הוא ג\"כ ימין וכמ\"ש ימינך ה' נאדרי בכח ימינך ה' תרעץ אויב, ב\"פ ימין, והיינו לפי שבקי\"ס הי' הגילוי מבחי' עתיק יומין וכמ\"ש מה תצעק אלי בעתיקא תליא מילתא, וע\"כ כתיב ב\"פ ימין, ואדרבה שמיד שמאל נמשך התגברות החיות יותר, כי למטה באצי' הגבורה הוא בחי' דין ג\"כ, אך למעלה הוא רק בחי' חסד, וחסד זה נמשך מבחי' ולגדולתו אין חקר לפי שאינו תופס מקום כלל ע\"כ הוא רק חסד, לפי שאם יש דין הרי הוא תפיסת מקום עכ\"פ (שפועל שינוי) א\"כ הוא בחי' גבול, משא\"כ כשלגדולתו אין חקר בלי גבול אינו תופס מקום כלל, ע\"כ הוא רק חסד. אך זהו למעלה שהחסד נמשך מבחי' הגדולה. אך למטה הוא להיפוך שהחסד נמשך מצד הביטול<sup data-n=\"657\">26</sup>, לפי שאם הוא יש ודבר אינו יכול להיות משפיע וכמ\"ש ולעלוקה שתי בנות הב הב, לפי שאם הוא יש הוא צריך לכל דבר, וכן אנו רואים בחוש בעושי צדקה שלא יתן כ\"א ע\"י שישים א\"ע כעפר, משא\"כ אם מחשב עצמו ליש ודבר לא יתן כ\"א איזה מותרות ממה שיש לו, אבל לא יגיעו ועמלו לחיי נפשו, שלזה צריך לשבר תאוות נפשו הנמשכים מגסות הרוח ולהחשיב א\"ע שיהי' כמו חבירו המקבל ממנו, ומאי חזית דדמא דידך סומק טפי כו', שיהי' לו מה לאכול ולשתות ולרש אין כל, מאי שנא ולמה יגרע הלא אב א' לכולנו. וע\"כ אברהם שהי' בחי' ואנכי עפר ואפר הי' איש החסד, כי אברהם אבר מ\"ה, וע\"כ הי' איש החסד.",[["656","25","<b>ולהבין ענין מ\"ש ויהי שם עם ה'</b>: בהבא לקמן (בפיסקא זו ושלאחרי') ראה אוה\"ת דרושים ליוהכ\"פ שם ע' א'תקצ-צא (בשם רבינו בחיי ע\"פ ויהי שם עם ה')."],["657","26","<b>למעלה שהחסד נמשך מבחי' הגדולה . . למטה . . מצד הביטול</b>: ראה בכ\"ז בארוכה בסה\"מ תרכ\"ז ע' קצח ואילך (ובהנסמן שם בהמ\"מ)."]]],[2002180234,"<b>וע\"י</b> הביטול שלמטה עי\"ז ממשיך מבחי' עם ה' החסד שנמשך מבחי' הגדולה. וזהו מ\"ש ויהי שם עם ה', כי תורה נמשך ג\"כ מבחי' עם הוי' החסד וכמ\"ש פיה פתחה בחכמה ותורת חסד על לשונה. אך כדי שיומשך התורה למטה מבחי' עם ה' החסד, זהו ע\"י הביטול וכמ\"ש וימת שם משה עי\"ז דוקא המשיך התורה מבחי' עם ה' החסד שהוא בחי' רב חסד.\n<b>והנה</b> ביוהכ\"פ מאיר ג\"כ מבחי' רב חסד זה כמ\"ש כי עמך הסליחה למען תורא, דהיינו שסליחת העוונות נמשך מבחי' כי עמך בחי' עם ה' החסד, לפי שע\"פ חכמה א\"א להיות סליחת העוונות כי שאלו לחכמה נפש החוטאת במה תתכפר כו', וכדי שיהי' בחי' סליחה זהו ע\"י המשכה מבחי' כי עם ה' החסד שאין העון תופס מקום כלל. וזהו שביוה\"כ מתפללים ה' תפלות<sup data-n=\"658\">27</sup> וה' עינויים, והיינו שע\"י ה' בחי' הנ\"ל נמשך מבחי' והיד החמשית שלית שמאלא בהאי עתיקא, ועי\"ז נמשך בחי' סליחה וכמ\"ש כי עמך הסליחה. ומעתה י\"ל מ\"ש ונהורא עמי' שריא, דהנה ארז\"ל אור שנברא ביום ראשון ראה שאין העולם כדאי להשתמש בו הבדילו לצדיקים לע\"ל לעצמו. והענין הוא, דהנה כתיב כי שמש ומגן הוי' אלקים, ששם הוי' אינו מאיר למטה בבי\"ע כ\"א ע\"י שם אלקים, שהוא מסתיר על גילוי שם הוי', אך באצי' מאיר גילוי שם הוי' בלי שום הסתר כו'. וזהו שאור שנברא ביום ראשון הבדילו לעצמו, דהיינו לעולם האצי' שמאיר שם גילוי שם הוי', שאור שנברא ביום ראשון הוא בחי' אור המאיר בשם הוי'. וזהו מ\"ש לדוד ה' אורי וישעי, דהיינו ג\"כ אור המאיר בשם הוי'. וזהו מ\"ש במשה ויהי שם עם ה' והיינו שהשיג שם גילוי אור המאיר בשם הוי', והיינו לפי שקיבל את התורה ובתורה מלובש האור וכמ\"ש עוטה אור כשלמה.\n<b>והנה</b> בזה יובן ענין מ' יום<sup data-n=\"659\">28</sup> שהוא בחי' מ' סאה דמקוה, דהנה מ' סאה דמקוה הוא בחי' ד' יודי\"ן שהוא ד' יודי\"ן של אני לדודי ודודי לי<sup data-n=\"660\">29</sup>, וד' יודי\"ן הוא מילוי של ש' הוי' של ש' ע\"ב שהוא בחי' חכ' סתימאה ולכך הוא בחי' יו\"ד, דהנה יו\"ד הוא בחי' צמצום והיינו שכדי שיומשך מאוא\"ס א\"א להיות כ\"א ע\"י צמצום והארה מאוא\"ס ב\"ה, וכמו למשל המעיין שתחילת המשכתו הוא בבחי' צמצום ואח\"כ נעשה נהר בבחי' התפשטות והתרחבות, ועד\"ז כדי שיומשך בחי' אוא\"ס זהו ע\"י צמצום, ולזה מורה היו\"ד שהוא ראשית הגילוי מאוא\"ס ולכך הוא בצמצום. והנה הוי' במילוי יודי\"ן היינו שהיו\"ד מאיר בכל האותיות בשוה, ולכך כשנמשכים<sup data-n=\"661\">30</sup> הד' יודי\"ן בבחי'",[["658","27","<b>שביוהכ\"פ מתפללי' ה' תפלות וה' עינויים . . מבחי' והיד החמשית</b>: ראה לקו\"ת פנחס פ, סע\"ד ואילך. לקו\"ש ח\"ד ע' 1154."],["659","28","<b>והנה בזה יובן ענין מ' יום</b>: בהבא לקמן ראה אוה\"ת דרושים ליוהכ\"פ שם ס\"ע א'תקצב-ג. הבא לקמן עד סיום המאמר (פיסקא: וזהו שאמר ר\"ע) מיוסד על ד\"ה ענין המקוה בסידור עם דא\"ח שם קנו, א ואילך. ובד\"ה להבין כללות כוונת המקוה שם קנח, ב ואילך."],["660","29","<b>מ' סאה דמקוה . . שהוא ד' יודי\"ן של אני לדודי ודודי לי</b>: ראה אוה\"ת דרושים ליוהכ\"פ שם ע' א'תקעז."],["661","30","<b>כשנמשכי' הד' יודי\"ן בבחי' מקוה דהיינו בחי' בינה</b>: ראה גם לקו\"ת ואתחנן ו, רע\"ג. וראה ד\"ה זה תרנ\"ה: מקוה הוא מקום קיבוץ המים, והנה מים הוא חכמה שהוא שם ע\"ב שם ה' במילוי יודי\"ן כו' ולכן שיעור מקוה הוא מ' סאה נגד הד' יודי\"ן דשם ע\"ב, ועצם המקוה הוא בינה כו' דהמקוה והמים שבו מורה על יחוד חו\"ב. [וראה לקמן הערה ד\"ה: יחוד חו\"ג]."]]],[2002180235,"מקוה דהיינו בחי' בינה כי אהי' עם מילוי ההי\"ן בגימ' מקוה<sup data-n=\"662\">31</sup> שהוא קנ\"א ונעשה יחוד חו\"ג<sup data-n=\"663\">32</sup> עי\"ז מטהר את הטמאים כו'. ולהבין זה מפני מה כשנמשכים הד' יודי\"ן בבחי' בינה עי\"ז המים מטהרים כו', וגם בנש\"י שהמים מטהרים כו', וצ\"ל למה מים דוקא. אך הענין הוא דהנה ארז\"ל כל המתענה תענית חלום בשבת קורעין לו גזר דין של ע' שנה, ולכאורה אינו מובן זה שהרי בשבת הוא בחי' ענג ואסור לצער בשבת<sup data-n=\"664\">33</sup> וא\"כ לכאורה הוא איסור, וא\"כ למה קורעין כו'. אך בזהר מתרץ זה עם משל א', והיינו כמו למשל המלך שעושה משתה והוא בשמחה וכשרואה עני עומד על הפתח ומצער א\"ע אינו יכול לסבול הצער שלו, ומצוה שיעשו רצונו, וכמו למשל מלך<sup data-n=\"665\">34</sup> כשהוא בשמחה עושה הנחה למדינתו ושולח אסיריו חפשי ואינו יכול לסבול הצער שלהם, משא\"כ כשאינו בשמחה, אדרבה מלך במשפט יעמיד ארץ. וכך מי שמתענה תענית חלום בשבת ששבת הוא בחי' ענג וכמ\"ש וקראת לשבת ענג<sup data-n=\"666\">35</sup>, אז תתענג על הוי', וע\"כ מי שמתענה תענית חלום בשבת ומצער א\"ע על עוונותיו עי\"ז אין יכולין לסבול הצער שלו, ומוחלין לו על כל עוונותיו. ובזה יובן הענין מה שהמים מטהרים כי מים הוא בחי' חכמה, והנה חכמה עדיין הוא למעלה מהשגה, והנה אנו רואים שגילוי התענוג הוא דוקא כשנמשך השכל בבחי' הבנה והשגה, משא\"כ כשהוא למעלה עדיין מבחי' הבנה והשגה אינו מתענג כלל, וע\"כ בבחי' חכמה לבד אינו מאיר שם גילוי התענוג עליון, משא\"כ כשנמשך המשכת חכמה בבחי' בינה והשגה עי\"ז נעשה למעלה בחי' גילוי התענוג, וכמ\"ש בע\"ח שהתגלות עתיק יומין הוא בבינה דוקא<sup data-n=\"667\">36</sup>, וע\"כ כשמאיר<sup data-n=\"668\">37</sup> בחי' תענוג עליון וטובל במקוה ומצער א\"ע על עוונותיו אין יכולין לסבול הצער שלו ועי\"ז המים מטהרים לפי שאז מאיר מבחי' תענוג עליון ואינו תופס מקום העון כלל.",[["662","31","<b>אהי' עם מילוי ההי\"ן בגימ' מקוה</b>: ראה כוונת המקוה מהבעש\"ט נדפס בהוספות לסידור עם דא\"ח שטו, א. אוה\"ת דרושים ליוהכ\"פ שם ע' א'תקצב."],["663","32","<b>יחוד חו\"ג</b>: אוצ\"ל: יחוד חו\"ב. [וראה לעיל הערה ד\"ה כשנמשכי' הד' יודי\"ן. ולקמן בסוף המאמר]."],["664","33","<b>ארז\"ל כל המתענה תענית חלום בשבת . . ולכאו' . . ואסור לצער בשבת</b>: בהבא לקמן ראה אוה\"ת דרושים ליוהכ\"פ שם ס\"ע א'תקצה-ו."],["665","34","<b>וכמו למשל מלך</b>: ראה סידור עם דא\"ח שם קנז, א. קנח, סע\"ד. לקמן ד\"ה ומעתה כו' ארז\"ל בכ\"ה באלול נבה\"ע (ע' תקמ)."],["666","35","<b>ששבת הוא בחי' ענג וכמ\"ש וקראת לשבת ענג</b>: ראה לעיל סד\"ה ומעתה כו' הריעו לה' כל הארץ. וש\"נ."],["667","36","<b>שהתגלות עתיק יומין הוא בבינה דוקא</b>: ראה תו\"א ר\"פ לך לך יא, ב. ובכ\"מ."],["668","37","<b>כשמאיר בחי' תענוג עליון וטובל במקוה ומצער א\"ע על עוונותיו . . המים מטהרי'</b>: ראה ד\"ה זה תרנ\"ה: דמפני שהמקוה מורה על יחוד חו\"ב שבהם ועל ידם מתגלה עונג העליון, והטמא טובל א\"ע ומצטער על שנטמא ממלאין לו בקשתו ומטהרים אותו."]]],[2002180236,"<b>וזהו</b><sup data-n=\"669\">38</sup> שאמר ר\"ע אשריכם ישראל לפני מי אתם מטהרין ומי מטהר אתכם, מי הוא בחי' התחברות ויחוד חו\"ב<sup data-n=\"670\">39</sup>, כי יו\"ד הוא בחי' חכמה ומ\"ם הוא בחי' מקוה, וע\"י יחוד חו\"ב עי\"ז מטהר אתכם שהוא בחי' מקוה שלמעלה מבחי' ל\"ט מלאכות ול\"ט מלקות שזה המקוה מטהר את הטמא גופא שמטמא נעשה טהור. וזהו מ' יום שמחדש אלול עד יוה\"כ שיוה\"כ הוא בחי' בינה דהיינו שאז מאיר גילוי התענוג בבינה התגלות עתיק, וע\"כ עי\"ז נמשך מחילת עוונות. אך זהו דוקא ע\"י מקוה שבמקוה יש שני פירושים, א' ל' תקוה, והב' מל' אוה מל' רצון שירצה בזה, ואהבת את הוי' אלקיך, אם ישים אליו לבו רוחו ונשמתו אליו יאסוף, עי\"ז נמשך יחוד חו\"ב שאז מאיר תענוג עליון, ועי\"ז מטהר את הטמאים כו' כנ\"ל.",[["669","38","<b>וזהו שא' ר\"ע אשריכם ישראל</b>: בהבא לקמן עד סוף המאמר ראה אוה\"ת דרושים ליוהכ\"פ שם ע' א'תקפא."],["670","39","<b>מי הוא התחברות ויחוד חו\"ב</b>: ראה גם לעיל ח\"א ד\"ה הללוי' גו' במרומים."]]],[2002180237,"<h3>להבין כו' מצות ותשובה</h3>\n<b>בס\"ד.</b>\n<b></b>הוי' אנכי כו' ב' עומקים כו' אנכי אנכי הוא\nלהבין שרשי הדברים<sup data-n=\"671\">1</sup> הנ\"ל, הנה שרש ההפרש בין מצות מעשיות בכלל למצות התשובה, דמצות מעשיות הוא בש' הוי' והתשובה בבחי' אנכי כו'. הנה תחלה יש להבין שרש ההפרש בין אנכי להוי' כו', בהיות שהמצות הן רמ\"ח אברים, הענין הוא שהן בחי' אורות הנאצלים מן המאציל ביו\"ד ספירות אורות וכלים, וראשיתן הוא בחי' הקו והחוט כו', ו[בחי'] הכלי א\"א כ\"א ע\"י צמצום בתחלה והוא היו\"ד, ואח\"כ התפשטות אורך ורוחב והוא הה\"א, ואח\"כ הוא\"ו כו', ויש ש' הוי' זה לכל ספי' וספי' בפ\"ע וכמבואר במאמר אנת הוא חד ולא בחושבן כו', וכמ\"ש ביאור הדברים במ\"א באריכות<sup data-n=\"672\">2</sup>.\n<b>והנה</b> המצות הן בחי' כלים לאורות עליונים ולכך נק' רמ\"ח אברים דמלכא דידוע דפי' מלכא הוא ז\"א דאצי', ובחי' האברים שלו הן הכלים דשמות דהוי' שיש",[["671","1","<b>להבין שרשי הדברים</b>: מאמר זה נמצא בבוך תרל\"ט לאחרי המאמר שלפניו ד\"ה ארע\"ק אשריכם ישראל, ואפשר נרשם כאן בתור ביאור למאמר הנ\"ל (שם נת' אודות סליחת העוונות).\nמאמר זה הוא ד\"ה זה בס' מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתפג ואילך. [והוא ביאור לד\"ה כי המצוה שם ע' תתעו ואילך. ונו\"א בלקו\"ת נצבים מה, ב ואילך]. — ונמצא בהרחבת הביאור לקמן בספר זה בד\"ה אנכי אנכי תר\"ם, וראה בהנסמן שם לכללות המאמר."],["672","2","<b>וכמבואר במאמר אנת הוא חד . . וכמ\"ש ביאור הדברי' . . במ\"א באריכות</b>: ראה סידור עם דא\"ח קסב, א."]]],[2002180238,"לכל ספי' וספי' שבו בפרט כו', ומבואר במ\"א בפסוק ויעש דוד שם<sup data-n=\"673\">3</sup> דע\"י המצות עושין למעלה שם, דהיינו שם דהוי' הנ\"ל, ויש מצות שרומזים בפרט לאותיות מיוחדות בש' הוי' שבכללות האצי', וכמו מצות התפילין בפ' קדש כו' רומזת לחכמה עילאה שמאיר ביו\"ד דש' הוי' שבכלל, ומצות סוכה רומזת לאות הה\"א דש' הוי' להיות שהסוכה היא בבחי' מקיף בהתפשטות אורך ורוחב כו'. ועד\"ז בפרטות יש כמה מצות תלויות בוא\"ו דש' הוי', ויש כמה מצות תלויות בה\"א אחרונה דש' הוי' כו', וכללותם נק' בשם מצות הוי' כו' וד\"ל. ולזה הטעם עיקר הוידוי בקריאת שמע שעל המטה אם פגם באותיות דש' הוי', כמו באמרו אם פגמתי באות יו\"ד כו'.\n<b>אך</b> הנה מי שפגם אין התיקון בא אלא ממקום שגבוה ממקום הפגם דוקא, ועד\"מ הנהר שנתקלקלו מימיו שחופרין בעומק יותר כנ\"ל, וזהו ע\"י מצות התשובה כנ\"ל דוקא. ושרש הדברים הוא לפי שלמעלה מן בחי' הקו והחוט דאור א\"ס אין שם בחי' אורות בכלים עדיין, כי אינו עדיין בבחי' גילוי האור כו', ושם נאמר ישת חשך סתרו כו' והוא בחי' העלם העצמות דא\"ס דלא ידע לי' בר איהו כו' וכמ\"ש אלקים הבין כו', והוא הנק' אנכי מי שאנכי כו', ועד שם מגיע מצות התשובה דוקא. וזהו כי המצוה הזאת אשר אנכי מצוך כו' וכנ\"ל<sup data-n=\"674\">4</sup>.\n<b>והטעם</b> לזה שהתשובה דוקא מגעת לשם ולא שאר המצות, הנה יובן עפ\"י ידיעה בתחלה להבין שרש ענין ממעמקים קראתיך הוי', פי' ממעמקים ב' עומקים, הוא בחי' ב' יסודות דאו\"א, וזהו מילוי ה' דתשובה תשוב ה'<sup data-n=\"675\">5</sup> כנ\"ל, הה\"א ביסוד אימא, והיו\"ד ביסוד אבא שגנוז ביסוד אימא כו'. וביאור הדברים הנה בחי' עומק הראשון הוא הנק' עומקא דבירא, היינו בחי' יסוד דאימא שהוא כמשל באר מים חיים מכונסים כבר כו', והמעיין שנובע תחת הבאר וממלא אותו בתמידות הוא משל בחי' יסוד אבא שגנוז ביסוד אימא, והוא להיותו בהעלם תחת הארץ כו', והיינו בחי' עומק השני כו'.\n<b>והנה</b> בחי' עומק הראשון יובן בעבודת ה' שהוא בחי' הרצוא שבא מסיבת ההתבוננות דוקא, והוא בחי' רשפי אש התשוקה בהתלהבות, כי בהיותו מתבונן איך דכולא קמי' כלא כו' וכיוצא יתפעל בלבבו לצאת מנרתק גופו כו' בבחי' כלות הנפש, וזהו אם רץ לבך וכנ\"ל, וה\"ז כמשל הבאר שמימיו עולין בו מלמטה",[["673","3","<b>ומבואר במ\"א בפסוק ויעש דוד שם</b>: אגה\"ק סי' ה (קו, ב ואילך. קט, ב). וראה גם לקו\"ת נצבים שם מה, ג."],["674","4","<b>בעומק יותר כנ\"ל . . מצות התשובה כנ\"ל . . וזהו כי המצוה . . כו' וכנ\"ל</b>: קאי על ד\"ה כי המצוה בס' מאמרי אדה\"ז תקס\"ה שם. (ועד\"ז לקמן בהמאמר)."],["675","5","<b>מילוי ה' דתשובה תשוב ה'</b>: בס' מאמרי אדה\"ז תקס\"ה שם: מילוי ה\"י דתשובה תשוב ה\"י. ר\"ל אות ה\"א במילוי יודי\"ן שהוא ”ה\"י\". וכמ\"ש לקמן בהמאמר: הה\"א . . והיו\"ד. וראה גם לקו\"ת נצבים מה, ג שם: תשובה תשוב ה', וה' זו יש בה מילוי יו\"ד (ה\"י)."]]],[2002180239,"למעלה דרך העלאת המעיין כידוע. והעומק השני הוא בחי' שוב שאחרי הרצוא, והוא בחי' ביטול כו' כידוע ומבואר ענינו במ\"א שהוא דרך ירידה והמשכה מלמעלמ\"ט<sup data-n=\"676\">6</sup>, וזה העומק נק' עומק רום, ועומק הראשון נק' עומק תחת כמ\"ש בס\"י ומבואר במ\"א<sup data-n=\"677\">7</sup>, וד\"ל. והנה ב' עומקים הללו מתלבשים זה בתוך זה, והיינו שעמקות דחכמה הוא בחי' הביטול גנוז ומתעלם תוך בחי' יסוד אימא דרצוא הנ\"ל, וזהו כמשל המעיין שגנוז בבאר כו'. והיינו ממעמקים פי' ב' עומקים שזה גנוז בתוך זה, והוא פי' ענין תשוב ה\"י במילוי יו\"ד כו' שתשוב הה\"א דרצוא ושוב יחד למעלה מעלה דהיינו שעולים שניהם יחד ומתבטלים ומתכללים למעלה מעלה והוא בבחי' כתר עליון שלפני הויות דז\"א ודאו\"א כו' והוא בבחי' אנכי מי שאנכי שלפני בחי' הקו והחוט כו'. וזהו ממעמקים קראתיך הוי' פי' אחרי העלי' יש המשכה וירידה, כי אחרי שנתעלה הה\"י במילוי יו\"ד והוא ב' מיני עומקים הנ\"ל למעלה באנכי כו' אזי נמשך עי\"ז בבחי' המשכה וירידה מלמעלה למטה להיות מהות כל הויות בזו\"נ ואו\"א כו', וזהו קראתיך הוי' מלמעלמ\"ט וד\"ל.\n<b>ובכ\"ז</b> יובן היטב שרש ענין אנכי אנכי הוא מוחה פשעיך למעני כו', דלכאורה תיבת הוא מיותר. אך הענין הוא דב' פעמים אנכי הן בחי' ב' יסודות דאו\"א הנ\"ל, כי אנכי הראשון הוא דבינה כידוע, ואנכי השני דבחי' כתר, שהוא אחרי שעלה אור אימא ונתייחד באור אבא ועלו שניהם בעתיקא סתימאה כו' שנק' הוא, וכמ\"ש במ\"א ע\"פ ועבד הלוי הוא<sup data-n=\"678\">8</sup> כו', והוא בחי' העלם העצמות שלפני הצמצום דק\"ו כו', ומשם ירד האור ויאיר בתוס' הארה חדשה באצי', ע\"כ הסליחה והמחילה משם הוא דוקא כמ\"ש הוא מוחה פשעיך הוא דוקא, שהוא בחי' עתיקא סתימא' כו', לפי שב' פעמים אנכי כולל יחוד עליות דאו\"א בתחלה ע\"כ גרמו ירידת אור בתוספת אח\"כ, והוא שרש להארת י\"ג מדה\"ר. וזהו אנכי אנכי הוא מוחה פשעיך להיות נושא עון ועובר על פשע כו' וד\"ל.\n<b>ועתה</b> יובן הטעם שהתשובה מגעת לבחי' אנכי דוקא, דהנה מפני בחי' עליות ב' עומקים הנ\"ל הוא מוחה פשעיך כנ\"ל, א\"כ זהו דוקא בסיבת בחי' אור חוזר דתשובה דהיינו תשוב ה\"י במילוי יו\"ד כנ\"ל, וזהו כי המצוה הזאת אשר אנכי, אנכי דוקא כו'. ומ\"ש היום, היום ולא למחר כו', יובן ג\"כ מפני טעם הנ\"ל בהיות שהארת היו\"ד דש' הוי' שבו נברא העוה\"ב הוא מצד סיבת מעשה המצות וכמ\"ש לעבדה זו",[["676","6","<b>שוב שאחרי הרצוא . . בחי' ביטול . . ומבואר ענינו במ\"א שהוא . . מלמעלמ\"ט</b>: ראה תו\"א בראשית ב, א ואילך. לקו\"ת ראה כט, ב. שה\"ש מו, א ואילך. ובכ\"מ."],["677","7","<b>עומק רום . . עומק תחת . . ומבואר במ\"א</b>: ראה ביאוה\"ז לאדהאמ\"צ צט, ג. שערי תשובה ח\"א כג, א. תורת חיים בראשית ה, ד ואילך. [ובהנסמן בהמ\"מ שם]."],["678","8","<b>וכמ\"ש במ\"א ע\"פ ועבד הלוי הוא</b>: ראה תו\"א ר\"פ לך לך יא, ב. לקו\"ת קרח נה, ב."]]],[2002180240,"רמ\"ח מ\"ע כו' וכידוע ומבואר במ\"א<sup data-n=\"679\">9</sup>, וכ\"ז אינו אלא במצות שתלויות בש' הוי', אבל התשובה מגעת למעלה מש' הוי' כנ\"ל ע\"כ אמר היום ולא למחר מפני שלמעלה הוא מקיבול שכר דלמחר מטעם זה (ועוד מטעם אחר המבואר במ\"א דהיום הוא זמן הבירור משא\"כ עוה\"ב<sup data-n=\"680\">10</sup> הוא לאחר הבירור ע\"ש) וד\"ל.",[["679","9","<b>העוה\"ב הוא מצד סיבת מעשה המצות וכמ\"ש לעבדה . . וכידוע ומבואר במ\"א</b>: ראה תו\"א מקץ לו, ב. לקו\"ת ואתחנן ט, א. סה\"מ תרכ\"ז ע' שכד. [ובהנסמן בהע' שלאח\"ז]."],["680","10","<b>המבואר במ\"א דהיום הוא זמן הבירור משא\"כ עוה\"ב</b>: ראה בארוכה לקו\"ת פנחס עה, סע\"ב ואילך. עו, ג ואילך. ואתחנן ט , סע\"ב. ועוד."]]],[2002180241,"<h3>תקעו</h3>\n<b></b><b>בס\"ד. (ליל ב' דר\"ה, תר\"ם).</b>\nי\"פ\nליל ב' דר\"ה\n<b>תקעו</b> בחדש שופר<sup data-n=\"681\">1</sup> בכסה ליום חגינו, וי\"ל למה נאמר בחדש סתם ולא נאמר באיזה חדש, ורז\"ל למדו שזה בר\"ה לפי שנא' בכסא ליום חגינו, איזהו חג שהחדש מתכסה בו הוי אומר זה ר\"ה, לפי שרוב המועדים הם באמצע החדש ויו\"ט של ר\"ה בתחלת החדש שאז הלבנה מתכסה כו'. אך מ\"מ אינו מובן למה לא נאמר בפירוש בחדש השביעי, כמו שנאמר בתורה ובחדש השביעי באחד לחדש יום תרועה יהי' לכם, ולמה תלה כאן הכתוב ענין תקיעות דראש השנה בכסא כו' היינו במה שהחדש מתכסה דוקא, ומה שייך תקיעת שופר למה שהחדש מתכסה דוקא כו'. אך הענין הוא דהנה כתיב ארץ אשר הוי' אלקיך דורש אותה תמיד<sup data-n=\"682\">2</sup> כו' מרשית השנה",[["681","1","<b>תקעו בחודש שופר</b>: מאמר זה (והמאמר שלאחריו) הוא ד\"ה זה בסה\"מ תרכ\"ז ע' תכח ואילך. וכאן הוא בתוס' הגהות. חלק מהמאמר (ספ\"א עד ספ\"ה) הוא ד\"ה תפלה לדוד הטה ה' אזנך הנמצא בין מאמרי תשרי תרכ\"ז [ראה סה\"מ תרכ\"ו ע' ]. לקמן בהוספות נדפסה הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר זה ושם ההתחלה: תפלה לעני כי יעטוף.\nהמאמר מיוסד על ד\"ה תפלה לעני באוה\"ת דרושים לר\"ה ע' א'שצא ואילך.\nלכללות המאמר ראה גם אוה\"ת משפטים ע' א'קסח. פרקים ו-ח מהמאמר מיוסדים על ד\"ה תקעו בחודש בלקו\"ת לר\"ה נד, סע\"ד ואילך. [הובא בד\"ה תפלה לעני באוה\"ת שם. — ונו\"א בס' מאמרי אדה\"ז תקס\"ח ח\"א ע' תיד ואילך. וביאור ע\"ז שם ע' תיח ואילך. ועוד ביאור ע\"ז באוה\"ת דרושים לר\"ה (כרך ו) ס\"ע ב'תנב ואילך [הובא ונת' בהמשך ר\"ה תרנ\"ט]. וראה שם ס\"ע ב'תפה ואילך].\nתוכן המאמר נמצא בשינויים וכו' בד\"ה ארשב\"נ תר\"צ (סה\"מ קונטרסים ח\"א קיח, א ואילך). ובד\"ה תקעו בחודש וד\"ה דרשו הוי' בהמצאו בסה\"מ תשח\"י. חלק מהמאמר הובא ונת' בד\"ה והי' ביום ההוא דיום ב' דר\"ה תשכ\"ח (סה\"מ מלוקט ח\"ו ע' ו ואילך). ובד\"ה זה דש\"פ האזינו תשכ\"ח. וראה גם ס' השיחות תש\"ה ע' 50. אגרות קודש כ\"ק אדמו\"ר מהוריי\"צ ח\"ד ע' מד-ה. ח\"ו ע' רנו.\nבבוך גוכתי\"ק תרל\"ט (מס. 1069) חסר חלקו הראשון של המאמר (עד אמצע פ\"ד), ונדפס כאן ע\"פ כת\"י מעתיקים: מס' 574 רלה, ב. 717 קמא, א. ועוד."],["682","2","<b>דהנה כתיב ארץ אשר הוי' אלקיך דורש אותה תמיד</b>: בכ\"ז ראה בארוכה אוה\"ת עקב ע' תרא ואילך. וע' תרה ואילך."]]]]});
